INSERT INTO lp_resources (slug, kind, perspective, audience, urgency, evidence_level, emoji, title, summary, body, sections, reading_minutes, min_day, max_day, countries, sex, tags, is_featured, review_status, sort_order) VALUES
  ('mc-homework-routine', 'article', 'scientific', 'shared', 'educational', 'consensus', '📝', '{"en":"Study habits and a homework routine without fights","bn":"ঝগড়া ছাড়া পড়াশোনার অভ্যাস ও বাড়ির কাজের রুটিন"}'::jsonb, '{"en":"A fixed time, a quiet place and a parent nearby — not doing the work — help children learn to study on their own.","bn":"নির্দিষ্ট সময়, শান্ত জায়গা আর পাশে থাকা মা-বাবা — কাজ করে না দিয়ে — শিশুকে নিজে নিজে পড়তে শেখায়।"}'::jsonb, '{"en":"Between 7 and 13, school becomes more serious and homework grows. A calm, predictable routine does more than daily nagging ever can. The aim is not perfect homework. The aim is a child who slowly learns to plan, start and finish work on their own.\n\n## A fixed time and place\n\nChoose one time that suits your family, for example after a snack and a short break. Most children concentrate better once they have eaten and moved a little. Use the same spot each day: a table, good light, the TV off and phones in another room. A corner of a shared room works well if it stays the same.\n\n## Small pieces, short breaks\n\nA long list feels impossible to a tired child. Help them write down today''s tasks and start with one easy item to build momentum. Work in short blocks, for example 20 minutes of work and then a few minutes to stretch or drink water. Older children can make the plan themselves; you only check it.\n\n## Nearby, not doing it\n\nSit close with your own reading or work. Help them read the question, then ask, “What do you think the first step is?” Do not write answers for them. If the teacher only sees perfect homework, they cannot see where your child is struggling.\n\n## Praise the effort\n\nSay “You kept going on that hard sum” rather than “You are so clever.” Praising effort helps children keep trying when work gets harder.\n\n## When homework becomes a battle\n\nIf every evening ends in tears, look for the reason. Is the amount too much? Is your child too tired after school and tuition? Is one subject hard to understand? Talk to the teacher. Children also need play, family time and enough sleep to learn well, so protect those too.\n\n## Sharing the job\n\nIf you come home late, take one part: check the school diary, sign the copy, or ask about one thing they learned today. Grandparents or an older sibling can keep the routine going while parents are at work.","bn":"৭ থেকে ১৩ বছর বয়সে পড়াশোনা আরও গুরুত্বপূর্ণ হয়ে ওঠে, বাড়ির কাজও বাড়ে। প্রতিদিন বকাঝকার চেয়ে একটা শান্ত, নিয়মিত রুটিন অনেক বেশি কাজে দেয়। লক্ষ্য নিখুঁত হোমওয়ার্ক নয়। লক্ষ্য হলো শিশু যেন ধীরে ধীরে নিজেই পরিকল্পনা করতে, কাজ শুরু করতে আর শেষ করতে শেখে।\n\n## নির্দিষ্ট সময়, নির্দিষ্ট জায়গা\n\nপরিবারের সুবিধামতো একটা সময় ঠিক করুন, যেমন স্কুল থেকে ফিরে নাশতা আর একটু বিশ্রামের পর। পেটে কিছু পড়লে আর একটু নড়াচড়া করলে বেশির ভাগ শিশু ভালো মন দিতে পারে। প্রতিদিন একই জায়গায় বসান: একটা টেবিল, ভালো আলো, টিভি বন্ধ, ফোন অন্য ঘরে। ঘর ভাগাভাগি করলেও একটা কোণ ঠিক করে দিলেই চলে, শুধু জায়গাটা যেন রোজ একই থাকে।\n\n## ছোট ছোট ভাগে কাজ\n\nক্লান্ত শিশুর কাছে লম্বা কাজের তালিকা অসম্ভব মনে হয়। আজকের কাজগুলো লিখে নিতে সাহায্য করুন, আর একটা সহজ কাজ দিয়ে শুরু করুন — তাতে গতি আসে। ছোট ছোট সময়ে ভাগ করে পড়ুক, যেমন ২০ মিনিট পড়া, তারপর কয়েক মিনিট হাত-পা টানা বা পানি খাওয়া। বড় শিশুরা নিজেরাই পরিকল্পনা করুক, আপনি শুধু দেখে দিন।\n\n## পাশে থাকুন, করে দেবেন না\n\nনিজের বই বা কাজ নিয়ে কাছেই বসুন। প্রশ্নটা পড়তে সাহায্য করুন, তারপর জিজ্ঞেস করুন, “তোমার কী মনে হয়, প্রথমে কী করতে হবে?” উত্তর লিখে দেবেন না। শিক্ষক যদি শুধু নিখুঁত খাতা দেখেন, তাহলে শিশুটি কোথায় আটকে যাচ্ছে তা বুঝতে পারবেন না।\n\n## চেষ্টার প্রশংসা করুন\n\n“তুমি খুব বুদ্ধিমান” বলার চেয়ে বলুন, “কঠিন অঙ্কটায় তুমি হাল ছাড়োনি।” চেষ্টার প্রশংসা পেলে কাজ কঠিন হলেও শিশু লেগে থাকতে শেখে।\n\n## যখন হোমওয়ার্ক মানেই যুদ্ধ\n\nপ্রতিদিন সন্ধ্যা কান্নায় শেষ হলে কারণ খুঁজুন। কাজ কি বেশি? স্কুল আর টিউশনের পর শিশু কি খুব ক্লান্ত? কোনো একটা বিষয় কি বুঝতে কষ্ট হচ্ছে? শিক্ষকের সঙ্গে কথা বলুন। ভালোভাবে শেখার জন্য শিশুর খেলা, পরিবারের সঙ্গে সময় আর যথেষ্ট ঘুমও দরকার — এগুলোও রক্ষা করুন।\n\n## দায়িত্ব ভাগ করে নিন\n\nবাবা বা মা দেরিতে ফিরলে একটা অংশ নিজের দায়িত্বে নিন: স্কুলের ডায়েরি দেখা, খাতায় সই করা, বা আজ নতুন কী শিখল তা জিজ্ঞেস করা। মা-বাবা কাজে থাকলে দাদা-দাদি, নানা-নানি বা বড় ভাইবোনও রুটিনটা চালিয়ে নিতে পারে।"}'::jsonb, '{"steps":{"en":["Agree on a homework time and place with your child","Write today''s tasks on a small list together","Start with one easy task","Work in short blocks with short breaks","Check the finished work together and praise the effort"],"bn":["সন্তানের সঙ্গে মিলে হোমওয়ার্কের সময় ও জায়গা ঠিক করুন","আজকের কাজগুলো একসঙ্গে ছোট একটা তালিকায় লিখুন","একটা সহজ কাজ দিয়ে শুরু করুন","ছোট ছোট সময়ে পড়ুক, মাঝে একটু বিরতি","শেষ হলে একসঙ্গে দেখুন আর চেষ্টার প্রশংসা করুন"]},"avoid":{"en":["Doing the homework for your child","Shouting, hitting or comparing with cousins and classmates","Homework in front of the TV or with a phone at hand","Filling every free hour with more study"],"bn":["সন্তানের হোমওয়ার্ক নিজে করে দেওয়া","চিৎকার, মারধর, বা চাচাতো-মামাতো ভাইবোন ও সহপাঠীর সঙ্গে তুলনা","টিভির সামনে বা হাতে ফোন নিয়ে পড়া","প্রতিটি অবসর ঘণ্টা আরও পড়া দিয়ে ভরে ফেলা"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['homework', 'study habits', 'routine', 'school', 'concentration']::text[], false, 'in_review'::lp_review_status, 7001),
  ('mc-exam-stress-tuition', 'article', 'scientific', 'shared', 'important', 'consensus', '📚', '{"en":"Exam stress, coaching and too many tuitions","bn":"পরীক্ষার চাপ, কোচিং আর অতিরিক্ত টিউশন"}'::jsonb, '{"en":"Some pressure helps children try; too much harms sleep, health and learning. Here is how to keep the balance.","bn":"একটু চাপ শিশুকে চেষ্টা করতে সাহায্য করে; বেশি চাপ ঘুম, স্বাস্থ্য আর শেখা — সবকিছুর ক্ষতি করে। ভারসাম্য রাখবেন কীভাবে, জেনে নিন।"}'::jsonb, '{"en":"In Bangladesh many children go from school straight to coaching, then to one or two private tutors, then home to homework. Parents do this out of love and worry about the future. But a child who never rests, plays or sleeps enough does not learn better. A tired brain remembers less.\n\n## Signs the pressure is too much\n\n- Headaches or stomach-aches, especially before exams or school\n- Trouble falling asleep, or sleeping far less than 9 hours\n- Crying, anger or giving up easily\n- Saying “I am stupid” or “I will fail anyway”\n- Losing interest in things they used to enjoy\n\n## Look at the whole week\n\nWrite down your child''s week hour by hour: school, travel, coaching, tuition, homework, sleep. Is there time for one hour of active play each day, meals with the family and 9–12 hours of sleep? If not, something has to go. Often one extra tuition can be dropped without any harm to results.\n\n## Ask whether each tuition helps\n\nA tutor is useful when a child truly needs help in one subject. Ask your child and the teacher: which subject is hard, and is this tuition helping? Paying for extra classes because “everyone does it” adds cost and stress without clear benefit.\n\n## Before and during exams\n\n- Help make a simple revision plan, a little each day, instead of last-night cramming\n- Keep normal sleep; staying up late makes recall worse\n- Give regular meals and water; do not skip breakfast\n- Keep a short walk or play every day\n- Talk about effort, not rank: “Do your best; we love you whatever the result”\n\n## After results\n\nPraise what went well first. Then look together at one or two areas to improve. Never shame a child in front of relatives or compare them with a cousin. A child who feels safe at home tries harder next time.\n\n## When to get help\n\nIf worry stops your child from going to school, sleeping or eating, or if they talk about hurting themselves or not wanting to live, see a doctor or a mental health professional soon. Any talk of self-harm needs help the same day.","bn":"বাংলাদেশে অনেক শিশু স্কুল থেকে সোজা কোচিংয়ে যায়, তারপর এক-দুজন প্রাইভেট শিক্ষকের কাছে, তারপর বাড়ি ফিরে হোমওয়ার্ক। মা-বাবা এটা করেন ভালোবাসা থেকে, ভবিষ্যতের দুশ্চিন্তা থেকে। কিন্তু যে শিশু কখনো বিশ্রাম পায় না, খেলে না, ঠিকমতো ঘুমায় না — সে বেশি শেখে না। ক্লান্ত মস্তিষ্ক কম মনে রাখে।\n\n## চাপ বেশি হয়ে যাওয়ার লক্ষণ\n\n- মাথাব্যথা বা পেটব্যথা, বিশেষ করে পরীক্ষা বা স্কুলের আগে\n- ঘুম আসতে দেরি, বা ৯ ঘণ্টার অনেক কম ঘুম\n- কান্না, রাগ, বা সহজেই হাল ছেড়ে দেওয়া\n- “আমি বোকা” বা “আমি তো ফেল করবই” বলা\n- আগে যা ভালো লাগত, তাতে আগ্রহ হারানো\n\n## পুরো সপ্তাহটা দেখুন\n\nসন্তানের সপ্তাহটা ঘণ্টা ধরে লিখে ফেলুন: স্কুল, যাতায়াত, কোচিং, টিউশন, হোমওয়ার্ক, ঘুম। প্রতিদিন এক ঘণ্টা ছোটাছুটির খেলা, পরিবারের সঙ্গে খাওয়া আর ৯–১২ ঘণ্টা ঘুমের সময় কি থাকছে? না থাকলে কিছু একটা বাদ দিতেই হবে। অনেক সময় একটা বাড়তি টিউশন বাদ দিলেও ফলাফলে কোনো ক্ষতি হয় না।\n\n## প্রতিটি টিউশন কাজে লাগছে কি না\n\nকোনো একটা বিষয়ে সত্যিই সাহায্য লাগলে প্রাইভেট শিক্ষক কাজে আসে। সন্তান ও শিক্ষককে জিজ্ঞেস করুন: কোন বিষয়টা কঠিন, আর এই টিউশন কি আসলে সাহায্য করছে? “সবাই পড়ে” বলে বাড়তি ক্লাসে টাকা দিলে খরচ আর চাপ দুটোই বাড়ে, লাভ স্পষ্ট নয়।\n\n## পরীক্ষার আগে ও পরীক্ষার সময়\n\n- শেষ রাতে মুখস্থ না করে প্রতিদিন একটু একটু রিভিশনের সহজ পরিকল্পনা করে দিন\n- স্বাভাবিক ঘুম ঠিক রাখুন; রাত জাগলে মনে রাখার ক্ষমতা কমে যায়\n- নিয়মিত খাবার আর পানি দিন; সকালের নাশতা বাদ দেবেন না\n- প্রতিদিন একটু হাঁটা বা খেলা রাখুন\n- রোল নম্বর নয়, চেষ্টার কথা বলুন: “তুমি তোমার সেরাটা দাও; ফল যা-ই হোক, আমরা তোমাকে ভালোবাসি”\n\n## ফলাফলের পর\n\nআগে যা ভালো হয়েছে তার প্রশংসা করুন। তারপর একসঙ্গে এক-দুটো জায়গা দেখুন যেখানে আরও ভালো করা যায়। আত্মীয়দের সামনে কখনো লজ্জা দেবেন না, কোনো কাজিনের সঙ্গে তুলনাও নয়। ঘরে নিরাপদ বোধ করলে শিশু পরের বার আরও মন দিয়ে চেষ্টা করে।\n\n## কখন সাহায্য নেবেন\n\nদুশ্চিন্তার কারণে সন্তান যদি স্কুলে যেতে, ঘুমাতে বা খেতে না পারে, অথবা নিজের ক্ষতি করার বা বাঁচতে না চাওয়ার কথা বলে — দ্রুত ডাক্তার বা মানসিক স্বাস্থ্য বিশেষজ্ঞের কাছে যান। নিজের ক্ষতির যেকোনো কথা শুনলে সেদিনই সাহায্য নিন।"}'::jsonb, '{"seek_help":{"en":["Worry stops your child from going to school, eating or sleeping for more than a couple of weeks","Frequent headaches or stomach-aches with no clear cause","Your child talks about hurting themselves or not wanting to live — get help the same day"],"bn":["দুশ্চিন্তার কারণে দু-এক সপ্তাহের বেশি স্কুলে যাওয়া, খাওয়া বা ঘুম বন্ধ","স্পষ্ট কারণ ছাড়া ঘন ঘন মাথাব্যথা বা পেটব্যথা","সন্তান নিজের ক্ষতি করা বা বাঁচতে না চাওয়ার কথা বলছে — সেদিনই সাহায্য নিন"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['exam', 'stress', 'tuition', 'coaching', 'pressure', 'rest']::text[], false, 'in_review'::lp_review_status, 7002),
  ('mc-working-with-teachers', 'article', 'general', 'shared', 'educational', 'consensus', '🏫', '{"en":"Working with your child''s teachers","bn":"সন্তানের শিক্ষকের সঙ্গে মিলে কাজ করা"}'::jsonb, '{"en":"Parents and teachers want the same thing. A respectful, regular link between home and school helps children most.","bn":"মা-বাবা আর শিক্ষক — দুজনেই সন্তানের ভালো চান। ঘর আর স্কুলের মধ্যে সম্মানজনক, নিয়মিত যোগাযোগ শিশুর সবচেয়ে বেশি উপকার করে।"}'::jsonb, '{"en":"Children do better at school when their parents and teachers talk to each other with respect. You know your child at home; the teacher sees them with thirty or more classmates. Together you see the whole child.\n\n## Make contact early\n\nDo not wait for a problem. At the start of the year, go to the parents'' meeting or send a short note to introduce yourself. Share anything that may affect learning, such as poor eyesight, a health condition, a new baby at home, a family loss or a recent move.\n\n## Use the school diary and meetings\n\nRead the diary or the school app regularly and sign what needs signing. Go to parent–teacher meetings when you can. If both parents work, take turns, or ask whether a phone call is possible. Fathers'' presence at school matters too; it shows your child that both parents care about their learning.\n\n## When there is a concern\n\n- Ask for a short meeting at a time that suits the teacher\n- Start with what you have noticed: “He has been upset on Sundays and says maths is hard”\n- Ask what the teacher sees in class\n- Agree on one or two small steps, and a time to check again\n- Stay calm and polite, even if you disagree\n\nTeachers can do much more when they feel you are on the same side.\n\n## In front of your child\n\nTry not to criticise a teacher in front of your child. If you disagree, talk to the teacher or the head teacher privately. Children who hear their parents mock a teacher often stop listening in class.\n\n## Things to always raise\n\nTell the school straight away if your child is being bullied, is afraid of an adult at school, or is being hit or humiliated as punishment. Physical punishment in schools is banned in Bangladesh, and it harms learning and mental health. You have the right to ask the school to stop it.\n\n## Saying thank you\n\nA short note or a word of thanks when a teacher has helped means a lot, and costs nothing. It also teaches your child to value the people who teach them.","bn":"মা-বাবা আর শিক্ষক যখন সম্মান নিয়ে একে অপরের সঙ্গে কথা বলেন, তখন শিশু স্কুলে ভালো করে। আপনি সন্তানকে চেনেন ঘরে; শিক্ষক তাকে দেখেন ত্রিশ-চল্লিশজন সহপাঠীর মাঝে। দুজনে মিলে পুরো শিশুটিকে দেখা যায়।\n\n## শুরুতেই যোগাযোগ করুন\n\nসমস্যা হওয়া পর্যন্ত অপেক্ষা করবেন না। বছরের শুরুতে অভিভাবক সভায় যান, বা ছোট একটা চিরকুট পাঠিয়ে পরিচয় দিন। শেখার ওপর প্রভাব ফেলতে পারে এমন কিছু থাকলে জানিয়ে রাখুন — যেমন চোখে কম দেখা, কোনো অসুখ, ঘরে নতুন শিশু, পরিবারে কারও মৃত্যু, বা নতুন বাসায় ওঠা।\n\n## ডায়েরি আর অভিভাবক সভা\n\nস্কুলের ডায়েরি বা অ্যাপ নিয়মিত দেখুন, যেখানে সই লাগে সই করুন। যখন পারেন অভিভাবক-শিক্ষক সভায় যান। দুজনেই চাকরি করলে পালা করে যান, বা ফোনে কথা বলা যায় কি না জিজ্ঞেস করুন। স্কুলে বাবার উপস্থিতিও গুরুত্বপূর্ণ — এতে সন্তান বোঝে, তার পড়াশোনা নিয়ে মা-বাবা দুজনেই ভাবেন।\n\n## কোনো দুশ্চিন্তা থাকলে\n\n- শিক্ষকের সুবিধামতো সময়ে ছোট একটা সাক্ষাৎ চেয়ে নিন\n- আপনি যা লক্ষ করেছেন তা দিয়ে শুরু করুন: “রবিবার এলেই ও মন খারাপ করে, বলে অঙ্ক কঠিন লাগে”\n- ক্লাসে শিক্ষক কী দেখছেন, জিজ্ঞেস করুন\n- এক-দুটো ছোট পদক্ষেপে একমত হোন, আর কবে আবার কথা বলবেন ঠিক করুন\n- মতের অমিল হলেও শান্ত ও ভদ্র থাকুন\n\nশিক্ষক যখন বোঝেন আপনি তাঁর পাশে আছেন, তখন তিনি অনেক বেশি করতে পারেন।\n\n## সন্তানের সামনে\n\nসন্তানের সামনে শিক্ষকের সমালোচনা না করার চেষ্টা করুন। দ্বিমত থাকলে শিক্ষক বা প্রধান শিক্ষকের সঙ্গে আলাদা করে কথা বলুন। যে শিশু মা-বাবাকে শিক্ষক নিয়ে ঠাট্টা করতে শোনে, সে ক্লাসে মন দেওয়া ছেড়ে দেয়।\n\n## যা অবশ্যই জানাবেন\n\nসন্তান যদি বুলিংয়ের শিকার হয়, স্কুলের কোনো বড় মানুষকে ভয় পায়, বা শাস্তি হিসেবে মার খায় বা অপমানিত হয় — সঙ্গে সঙ্গে স্কুলকে জানান। বাংলাদেশে স্কুলে শারীরিক শাস্তি নিষিদ্ধ, আর এটা শেখা ও মানসিক স্বাস্থ্য দুটোরই ক্ষতি করে। স্কুলকে এটা বন্ধ করতে বলার অধিকার আপনার আছে।\n\n## ধন্যবাদ বলুন\n\nশিক্ষক সাহায্য করলে ছোট একটা চিরকুট বা মুখে একটা ধন্যবাদ অনেক বড় ব্যাপার, অথচ খরচ নেই। এতে সন্তানও শেখে, যাঁরা তাকে শেখান তাঁদের সম্মান করতে হয়।"}'::jsonb, '{}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['teacher', 'school', 'parent teacher meeting', 'communication']::text[], false, 'in_review'::lp_review_status, 7003),
  ('mc-reading-for-fun', 'article', 'scientific', 'shared', 'educational', 'consensus', '📖', '{"en":"Reading for fun","bn":"আনন্দের জন্য পড়া"}'::jsonb, '{"en":"Children who read for pleasure, not only for exams, grow their language, imagination and focus. You can make it a habit at home.","bn":"শুধু পরীক্ষার জন্য নয়, আনন্দের জন্য যে শিশু পড়ে, তার ভাষা, কল্পনা আর মনোযোগ বাড়ে। ঘরেই এটা অভ্যাসে পরিণত করা যায়।"}'::jsonb, '{"en":"Many children in Bangladesh read a lot, but only textbooks and guide books. Reading for fun is different. A story or a book about animals, space or cricket, chosen by the child, builds vocabulary, imagination and the ability to focus for a long time. It also gives a tired mind a break from exams.\n\n## Let your child choose\n\nComics, adventure stories, jokes, science facts, rhymes, biographies — all count. Bangla and English books both help. A child who likes one kind of book will read more, and slowly try other kinds. Avoid only books with content that is not suitable for their age.\n\n## Make books easy to reach\n\n- Keep a small shelf or box of books at child height\n- Visit a library, a school library or a book fair together; the Ekushe Boi Mela in February is a good outing for the whole family\n- Swap books with cousins and friends\n- Give books as gifts on birthdays and Eid\n\n## Read together, even with older children\n\nReading aloud does not stop at seven. Take turns reading pages, or read the same book and talk about it. Ask questions with no right answer: “What would you have done?” “Who was your favourite?”\n\n## Find a reading time\n\nTen to twenty minutes before bed, with screens off, suits many families. It also helps sleep. On holidays, a longer reading time in the afternoon can replace some screen time.\n\n## Be a reader yourself\n\nChildren copy what they see. If they see a parent or grandparent reading a newspaper, a novel or a religious book, reading looks normal and enjoyable. Fathers reading with sons and daughters is especially powerful.\n\n## If reading seems hard\n\nSome children avoid books because reading is difficult for them. If your child still struggles to read simple words after the first years of school, mixes up letters a lot, or gets very tired reading, talk to the teacher and a doctor. Their eyes may need checking, or they may need extra help with reading. Early help makes a big difference.","bn":"বাংলাদেশে অনেক শিশু প্রচুর পড়ে — কিন্তু শুধু পাঠ্যবই আর গাইড বই। আনন্দের জন্য পড়া আলাদা জিনিস। নিজের পছন্দে বেছে নেওয়া একটা গল্প, বা পশুপাখি, মহাকাশ বা ক্রিকেট নিয়ে একটা বই শব্দভান্ডার, কল্পনাশক্তি আর অনেকক্ষণ মন দিয়ে থাকার ক্ষমতা বাড়ায়। পরীক্ষার চাপে ক্লান্ত মনকেও একটু বিশ্রাম দেয়।\n\n## সন্তানকে বেছে নিতে দিন\n\nকমিকস, অ্যাডভেঞ্চারের গল্প, মজার কৌতুক, বিজ্ঞানের তথ্য, ছড়া, জীবনী — সবই চলবে। বাংলা আর ইংরেজি দুই ভাষার বইই কাজে আসে। যে শিশু এক ধরনের বই ভালোবাসে, সে বেশি পড়ে, আর ধীরে ধীরে অন্য ধরনেও হাত দেয়। শুধু বয়সের সঙ্গে মানায় না এমন বিষয়ের বই এড়িয়ে চলুন।\n\n## বই যেন হাতের কাছে থাকে\n\n- শিশুর হাতের নাগালে ছোট একটা তাক বা বাক্সে বই রাখুন\n- একসঙ্গে লাইব্রেরি, স্কুল লাইব্রেরি বা বইমেলায় যান; ফেব্রুয়ারির অমর একুশে বইমেলা পুরো পরিবারের জন্য দারুণ একটা বেড়ানো\n- চাচাতো-মামাতো ভাইবোন আর বন্ধুদের সঙ্গে বই বদলাবদলি করুক\n- জন্মদিন আর ঈদে উপহার হিসেবে বই দিন\n\n## বড় হলেও একসঙ্গে পড়ুন\n\nসাত বছর হলেই জোরে পড়ে শোনানো বন্ধ করতে হবে, এমন নয়। পালা করে এক-এক পাতা পড়ুন, বা একই বই পড়ে তা নিয়ে গল্প করুন। এমন প্রশ্ন করুন যার কোনো ঠিক-ভুল উত্তর নেই: “তুমি হলে কী করতে?” “কাকে তোমার সবচেয়ে ভালো লেগেছে?”\n\n## পড়ার একটা সময় ঠিক করুন\n\nঘুমানোর আগে স্ক্রিন বন্ধ করে দশ থেকে বিশ মিনিট পড়া অনেক পরিবারের জন্য ভালো কাজ করে। এতে ঘুমও ভালো হয়। ছুটির দিনে বিকেলে একটু লম্বা সময় পড়া কিছু স্ক্রিন টাইমের জায়গা নিতে পারে।\n\n## আপনি নিজেও পড়ুন\n\nশিশু যা দেখে তা-ই শেখে। মা-বাবা বা দাদা-দাদিকে পত্রিকা, উপন্যাস বা ধর্মীয় বই পড়তে দেখলে পড়াটা তার কাছে স্বাভাবিক আর আনন্দের মনে হয়। বাবা যখন ছেলে-মেয়ের সঙ্গে বসে পড়েন, তার প্রভাব আরও বেশি।\n\n## পড়তে কষ্ট হলে\n\nকিছু শিশু বই এড়িয়ে চলে, কারণ পড়াটা তাদের জন্য কঠিন। স্কুলের প্রথম কয়েক বছর পরও সহজ শব্দ পড়তে খুব কষ্ট হলে, বারবার অক্ষর গুলিয়ে ফেললে, বা পড়তে গিয়ে খুব ক্লান্ত হয়ে পড়লে শিক্ষক আর ডাক্তারের সঙ্গে কথা বলুন। চোখ পরীক্ষা লাগতে পারে, বা পড়ায় বাড়তি সাহায্য লাগতে পারে। আগেভাগে সাহায্য পেলে অনেক বড় পার্থক্য হয়।"}'::jsonb, '{}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['reading', 'books', 'library', 'story', 'language']::text[], false, 'in_review'::lp_review_status, 7004),
  ('mc-learning-differences', 'article', 'scientific', 'shared', 'important', 'consensus', '🧩', '{"en":"Learning differences: when to ask a professional","bn":"শেখার ভিন্নতা: কখন বিশেষজ্ঞের কাছে যাবেন"}'::jsonb, '{"en":"Some bright children struggle with reading, writing, numbers or attention. Notice the signs, get a proper assessment, and avoid labels like “lazy” or “dull”.","bn":"অনেক মেধাবী শিশুরও পড়া, লেখা, অঙ্ক বা মনোযোগে কষ্ট হয়। লক্ষণগুলো খেয়াল করুন, ঠিকমতো মূল্যায়ন করান, আর “অলস” বা “গাধা” জাতীয় তকমা দেবেন না।"}'::jsonb, '{"en":"Every child learns in their own way and at their own pace. Some children, though, work very hard and still struggle in one area. This is not laziness and not a sign of low intelligence. It may be a learning difference such as dyslexia (difficulty with reading and spelling) or ADHD (difficulty with attention, activity and self-control). Only a trained professional can say what is going on.\n\n## Signs worth noticing\n\nReading and writing:\n\n- Still finds it very hard to read simple words after the first years of school\n- Often reverses or mixes up letters and numbers well past the early grades\n- Reads very slowly, guesses words, or avoids reading aloud\n- Spelling is far behind classmates, even for words practised many times\n\nAttention and activity:\n\n- Cannot stay with a task even for a short time, in most settings, not only with homework\n- Constantly moves, fidgets or interrupts, much more than other children of the same age\n- Loses things and forgets instructions every day\n- Acts without thinking in ways that put them in danger\n\nOne sign alone is common in many children. What matters is a pattern that lasts for months, shows up both at home and at school, and gets in the way of learning or friendships.\n\n## First, rule out simple causes\n\nCheck eyesight and hearing. Poor sleep, hunger, worry, bullying or problems at home can also look like attention or learning problems.\n\n## Who to see\n\nStart with your child''s teacher and a paediatrician. They may refer you to a child development centre (Shishu Bikash Kendro) at a medical college hospital, a child psychologist or a child psychiatrist for a full assessment.\n\n## No labels, at home or at school\n\nWords like “lazy”, “dull” or “mad” hurt deeply and stick for years. They also stop children asking for help. Instead, tell your child: “Your brain learns in its own way. We will find out what helps you.” Whatever the result, your child is the same person you love.\n\n## What helps\n\nWith the right support many children with learning differences do very well. Help can include teaching methods for reading, extra time in exams, sitting near the front, short tasks with breaks, clear routines and, for some children with ADHD, treatment the doctor recommends. Ask the school what support it can offer.","bn":"প্রত্যেক শিশু নিজের মতো করে, নিজের গতিতে শেখে। তবে কিছু শিশু অনেক পরিশ্রম করেও কোনো একটা জায়গায় আটকে যায়। এটা অলসতা নয়, বুদ্ধি কম হওয়ার লক্ষণও নয়। এটা হতে পারে শেখার ভিন্নতা — যেমন ডিসলেক্সিয়া (dyslexia, পড়া ও বানানে সমস্যা) বা এডিএইচডি (ADHD, মনোযোগ, অস্থিরতা ও নিজেকে সামলানোয় সমস্যা)। আসলে কী হচ্ছে, তা শুধু প্রশিক্ষিত বিশেষজ্ঞই বলতে পারেন।\n\n## যে লক্ষণগুলো খেয়াল রাখার মতো\n\nপড়া ও লেখা:\n\n- স্কুলের প্রথম কয়েক বছর পরও সহজ শব্দ পড়তে খুব কষ্ট হয়\n- নিচের ক্লাস পেরিয়ে যাওয়ার পরও প্রায়ই অক্ষর বা সংখ্যা উল্টো লেখে বা গুলিয়ে ফেলে\n- খুব ধীরে পড়ে, আন্দাজে শব্দ বলে, বা জোরে পড়া এড়িয়ে যায়\n- বহুবার অনুশীলন করা শব্দের বানানেও সহপাঠীদের চেয়ে অনেক পিছিয়ে\n\nমনোযোগ ও অস্থিরতা:\n\n- অল্প সময়ও কোনো কাজে মন রাখতে পারে না — শুধু পড়ায় নয়, প্রায় সব জায়গায়\n- সমবয়সীদের চেয়ে অনেক বেশি নড়াচড়া, ছটফট বা কথার মাঝে কথা বলে\n- প্রতিদিন জিনিস হারায়, নির্দেশ ভুলে যায়\n- না ভেবে এমন কাজ করে যাতে বিপদ হতে পারে\n\nএকটা লক্ষণ অনেক শিশুর মধ্যেই থাকে। দেখার বিষয় হলো এমন ধরন যা কয়েক মাস ধরে চলছে, ঘরে আর স্কুলে দুই জায়গাতেই দেখা যাচ্ছে, আর শেখা বা বন্ধুত্বে বাধা দিচ্ছে।\n\n## আগে সহজ কারণগুলো বাদ দিন\n\nচোখ আর কান পরীক্ষা করান। কম ঘুম, ক্ষুধা, দুশ্চিন্তা, বুলিং বা ঘরের অশান্তিও মনোযোগ বা শেখার সমস্যার মতো দেখাতে পারে।\n\n## কার কাছে যাবেন\n\nশুরু করুন সন্তানের শিক্ষক আর একজন শিশু বিশেষজ্ঞ ডাক্তারের কাছ থেকে। প্রয়োজনে তাঁরা পূর্ণ মূল্যায়নের জন্য মেডিকেল কলেজ হাসপাতালের শিশু বিকাশ কেন্দ্র, শিশু মনোবিজ্ঞানী বা শিশু মনোরোগ বিশেষজ্ঞের কাছে পাঠাতে পারেন।\n\n## ঘরে বা স্কুলে — কোনো তকমা নয়\n\n“অলস”, “গাধা”, “পাগল” — এ ধরনের কথা গভীরভাবে আঘাত করে, বছরের পর বছর মনে থেকে যায়। এতে শিশু সাহায্য চাইতেও ভয় পায়। বরং বলুন: “তোমার মাথা নিজের মতো করে শেখে। কীসে তোমার সুবিধা হয়, আমরা খুঁজে বের করব।” ফল যা-ই আসুক, আপনার সন্তান সেই একই মানুষ, যাকে আপনি ভালোবাসেন।\n\n## যা সাহায্য করে\n\nঠিকমতো সহায়তা পেলে শেখার ভিন্নতা থাকা অনেক শিশুই খুব ভালো করে। সাহায্যের মধ্যে থাকতে পারে পড়া শেখানোর বিশেষ পদ্ধতি, পরীক্ষায় বাড়তি সময়, সামনের সারিতে বসা, বিরতিসহ ছোট ছোট কাজ, পরিষ্কার রুটিন, আর এডিএইচডি থাকা কিছু শিশুর ক্ষেত্রে ডাক্তারের পরামর্শমতো চিকিৎসা। স্কুল কী সহায়তা দিতে পারে, জিজ্ঞেস করুন।"}'::jsonb, '{"seek_help":{"en":["Struggles with reading, writing or numbers continue for months despite help","Attention or activity problems show up both at home and at school","Your child is losing confidence, avoiding school or being teased about it","The teacher raises a concern about learning or behaviour"],"bn":["সাহায্য সত্ত্বেও কয়েক মাস ধরে পড়া, লেখা বা অঙ্কে কষ্ট চলছে","মনোযোগ বা অস্থিরতার সমস্যা ঘরে ও স্কুলে দুই জায়গাতেই দেখা যাচ্ছে","সন্তান আত্মবিশ্বাস হারাচ্ছে, স্কুল এড়িয়ে যাচ্ছে বা এ নিয়ে খোঁটা শুনছে","শিক্ষক শেখা বা আচরণ নিয়ে দুশ্চিন্তার কথা বলছেন"]}}'::jsonb, 4, 2557, 4748, '{}'::text[], 'any', ARRAY['dyslexia', 'adhd', 'learning difficulty', 'attention', 'assessment', 'special needs']::text[], false, 'in_review'::lp_review_status, 7005),
  ('mc-anger-and-anxiety', 'article', 'scientific', 'shared', 'important', 'consensus', '🌧️', '{"en":"Anger and anxiety in school-age children","bn":"স্কুলপড়ুয়া শিশুর রাগ আর দুশ্চিন্তা"}'::jsonb, '{"en":"Big feelings are normal at this age. Children learn to handle anger and worry when calm adults name the feeling, set limits and teach simple skills.","bn":"এ বয়সে বড় বড় আবেগ স্বাভাবিক। শান্ত বড়রা যখন অনুভূতির নাম দেন, সীমা ঠিক করেন আর সহজ কৌশল শেখান, তখনই শিশু রাগ আর দুশ্চিন্তা সামলাতে শেখে।"}'::jsonb, '{"en":"School-age children face new pressures: exams, friendships, being compared, more rules. Feeling angry or worried is part of growing up. Our job is not to remove these feelings, but to help children understand them and act safely.\n\n## All feelings are allowed, not all actions\n\nTell your child: “It is okay to feel angry. It is not okay to hit, break things or say hurtful words.” When children hear that their feeling is accepted, they calm down faster and listen better.\n\n## Name it to tame it\n\nHelp your child put words to what they feel: angry, jealous, embarrassed, scared, disappointed. Say what you see: “You look really upset that your brother got the front seat.” Naming a feeling helps the thinking part of the brain catch up.\n\n## Teach calm-down skills when they are calm\n\nPractise these on a good day, so they are ready on a hard one:\n\n- Slow breathing: in through the nose for four, out through the mouth for six, a few times\n- Counting to ten, or walking to a quiet corner\n- Squeezing a pillow, drinking water, washing the face\n- Drawing or writing down what made them angry\n\n## Stay calm yourself\n\nChildren copy how adults handle anger. If you shout or hit, they learn that big people solve problems that way. Take a breath, lower your voice, and step away if you need to. Hitting and harsh words do not teach self-control; they increase fear and anger.\n\n## Worry and anxiety\n\nSome children worry a lot: about exams, a parent''s safety, the dark or making mistakes. Anxiety often shows in the body as stomach-aches, headaches or trouble sleeping.\n\n- Listen without brushing it off: “That sounds really scary.”\n- Help them face small fears step by step, rather than avoiding them completely\n- Keep routines predictable, and prepare them for changes\n- Limit frightening news and videos\n\n## After the storm\n\nOnce everyone is calm, talk about what happened and what to try next time. Help your child repair: say sorry, fix what they broke, or help a sibling.\n\n## When to get help\n\nSee a doctor or a child mental health professional if anger or worry is so strong or frequent that it stops normal school, sleep, eating or friendships for several weeks; if your child hurts themselves or others; or if they talk about not wanting to live.","bn":"স্কুলপড়ুয়া শিশুর সামনে নতুন নতুন চাপ: পরীক্ষা, বন্ধুত্ব, তুলনা, আরও বেশি নিয়ম। রাগ বা দুশ্চিন্তা হওয়া বড় হওয়ারই অংশ। আমাদের কাজ এই অনুভূতিগুলো মুছে ফেলা নয় — বরং শিশুকে এগুলো বুঝতে আর নিরাপদভাবে সামলাতে সাহায্য করা।\n\n## সব অনুভূতি চলবে, সব আচরণ নয়\n\nসন্তানকে বলুন: “রাগ হওয়া ঠিক আছে। কিন্তু মারা, জিনিস ভাঙা বা কষ্ট দেওয়া কথা বলা ঠিক নয়।” অনুভূতিটা মেনে নেওয়া হচ্ছে শুনলে শিশু তাড়াতাড়ি শান্ত হয়, আর কথা শোনেও বেশি।\n\n## অনুভূতির নাম দিন\n\nসন্তান যা অনুভব করছে তার নাম খুঁজে দিন: রাগ, হিংসা, লজ্জা, ভয়, হতাশা। যা দেখছেন তা বলুন: “ভাইয়া সামনের সিটে বসেছে বলে তোমার খুব মন খারাপ হয়েছে, তাই না?” অনুভূতির নাম দিলে মস্তিষ্কের ভাবনার অংশটা আবার কাজ শুরু করতে পারে।\n\n## শান্ত থাকার সময় শান্ত হওয়ার কৌশল শেখান\n\nভালো দিনে এগুলো অনুশীলন করুন, যাতে কঠিন দিনে কাজে লাগে:\n\n- ধীরে শ্বাস: নাক দিয়ে চার গুনে শ্বাস নেওয়া, মুখ দিয়ে ছয় গুনে ছাড়া — কয়েকবার\n- দশ পর্যন্ত গোনা, বা একটা শান্ত কোণে চলে যাওয়া\n- বালিশ চেপে ধরা, পানি খাওয়া, মুখে পানি দেওয়া\n- কী নিয়ে রাগ হলো, তা এঁকে বা লিখে ফেলা\n\n## নিজে শান্ত থাকুন\n\nবড়রা রাগ কীভাবে সামলান, শিশু তা-ই নকল করে। আপনি চিৎকার করলে বা মারলে সে শেখে, বড়রা এভাবেই সমস্যার সমাধান করে। একটা লম্বা শ্বাস নিন, গলা নামান, দরকার হলে একটু সরে যান। মারধর আর কড়া কথা আত্মনিয়ন্ত্রণ শেখায় না; বরং ভয় আর রাগ বাড়ায়।\n\n## দুশ্চিন্তা আর উদ্বেগ\n\nকিছু শিশু অনেক বেশি দুশ্চিন্তা করে: পরীক্ষা, মা-বাবার নিরাপত্তা, অন্ধকার বা ভুল করা নিয়ে। উদ্বেগ প্রায়ই শরীরে দেখা দেয় — পেটব্যথা, মাথাব্যথা বা ঘুমের সমস্যা হিসেবে।\n\n- উড়িয়ে না দিয়ে শুনুন: “শুনে তো সত্যিই ভয়ের মনে হচ্ছে।”\n- ভয়কে পুরোপুরি এড়িয়ে না গিয়ে ছোট ছোট ধাপে মোকাবিলা করতে সাহায্য করুন\n- রুটিন নিয়মিত রাখুন, কোনো পরিবর্তন আসার আগে জানিয়ে দিন\n- ভয়ের খবর আর ভিডিও কমিয়ে দিন\n\n## ঝড় থামার পর\n\nসবাই শান্ত হলে কী হয়েছিল আর পরের বার কী করা যায়, তা নিয়ে কথা বলুন। সন্তানকে ভুল শোধরাতে সাহায্য করুন: দুঃখিত বলা, যা ভেঙেছে তা ঠিক করা, বা ভাইবোনকে সাহায্য করা।\n\n## কখন সাহায্য নেবেন\n\nরাগ বা দুশ্চিন্তা যদি এত বেশি বা এত ঘন ঘন হয় যে কয়েক সপ্তাহ ধরে স্কুল, ঘুম, খাওয়া বা বন্ধুত্ব স্বাভাবিকভাবে চলছে না; সন্তান যদি নিজেকে বা অন্যকে আঘাত করে; বা বাঁচতে না চাওয়ার কথা বলে — ডাক্তার বা শিশু মানসিক স্বাস্থ্য বিশেষজ্ঞের কাছে যান।"}'::jsonb, '{"seek_help":{"en":["Anger or worry stops school, sleep, eating or friendships for several weeks","Your child hurts themselves, others or animals","Talk of not wanting to live, or of self-harm — get help the same day"],"bn":["কয়েক সপ্তাহ ধরে রাগ বা দুশ্চিন্তার কারণে স্কুল, ঘুম, খাওয়া বা বন্ধুত্ব ব্যাহত","সন্তান নিজেকে, অন্যকে বা পশুপাখিকে আঘাত করছে","বাঁচতে না চাওয়া বা নিজের ক্ষতির কথা — সেদিনই সাহায্য নিন"]}}'::jsonb, 4, 2557, 4748, '{}'::text[], 'any', ARRAY['anger', 'anxiety', 'worry', 'feelings', 'calm down', 'emotions']::text[], false, 'in_review'::lp_review_status, 7006),
  ('mc-self-esteem-growth-mindset', 'article', 'scientific', 'shared', 'educational', 'research', '🌱', '{"en":"Self-esteem and a growth mindset","bn":"আত্মসম্মানবোধ আর “চেষ্টায় পারা যায়” মানসিকতা"}'::jsonb, '{"en":"Children feel good about themselves when they are loved for who they are and learn that effort and practice help them grow.","bn":"শিশু যখন বোঝে যে সে যেমন তেমনভাবেই ভালোবাসা পায়, আর চেষ্টা ও অনুশীলনে উন্নতি হয় — তখনই তার নিজের প্রতি ভালো ধারণা গড়ে ওঠে।"}'::jsonb, '{"en":"Self-esteem is how a child feels about themselves: “Am I loved? Am I capable?” Between 7 and 13, children start to compare themselves with others in marks, looks, sports and possessions. A steady sense of worth helps them handle failure, resist peer pressure and keep trying.\n\n## Love that does not depend on marks\n\nChildren need to know your love does not go up and down with their results. Say it plainly and often: “I love you, whatever your marks are.” Spend a little time each day doing something together that has nothing to do with study.\n\n## Praise effort and strategy, not only talent\n\nResearch on what is called a growth mindset suggests that children who believe abilities can grow with effort keep trying longer when things are hard. Praise like “You are a genius” can make children afraid of failing. Try instead:\n\n- “You practised every day, and look how much better your handwriting is.”\n- “That was hard, and you tried a different way.”\n- “You did not give up.”\n\n## Mistakes are how we learn\n\nWhen your child makes a mistake, ask “What did you learn?” rather than “Why are you so careless?” Share your own mistakes and how you fixed them. Add the word “yet” to “I can''t do it”: “You can''t do long division yet.”\n\n## Give real responsibility\n\nConfidence comes from doing real things: making a cup of tea, buying bread from the shop, helping a younger cousin. Chores and small jobs show children that they are capable and needed.\n\n## Avoid comparing and shaming\n\n“Look at your cousin, she came first” hurts more than it motivates. So does teasing about weight, skin colour or looks, which is common in many families. Ask relatives kindly to stop such comments. Every child is different; compare a child only with their own past.\n\n## Let them shine somewhere\n\nNot every child is good at exams. One may draw well, another may be kind with little children, another may love football or fixing things. Notice and name these strengths.\n\n## Watch for low mood\n\nIf your child often says “I am useless”, withdraws from friends, or seems sad most days for weeks, talk to them gently and speak to a doctor.","bn":"আত্মসম্মানবোধ মানে শিশু নিজের সম্পর্কে কী ভাবে: “আমাকে কি ভালোবাসা হয়? আমি কি পারি?” ৭ থেকে ১৩ বছর বয়সে শিশু নম্বর, চেহারা, খেলাধুলা আর জিনিসপত্র নিয়ে অন্যদের সঙ্গে নিজেকে তুলনা করতে শুরু করে। নিজের মূল্য সম্পর্কে স্থির ধারণা থাকলে সে ব্যর্থতা সামলাতে পারে, বন্ধুদের চাপে না বলতে পারে, আর চেষ্টা চালিয়ে যায়।\n\n## যে ভালোবাসা নম্বরের ওপর নির্ভর করে না\n\nশিশুর জানা দরকার, ফলাফলের সঙ্গে আপনার ভালোবাসা ওঠানামা করে না। পরিষ্কার করে, বারবার বলুন: “তোমার নম্বর যা-ই হোক, আমি তোমাকে ভালোবাসি।” প্রতিদিন একটু সময় একসঙ্গে এমন কিছু করুন, যার সঙ্গে পড়াশোনার কোনো সম্পর্ক নেই।\n\n## শুধু মেধা নয়, চেষ্টা আর কৌশলের প্রশংসা\n\n“গ্রোথ মাইন্ডসেট” নিয়ে গবেষণা বলছে, যে শিশু বিশ্বাস করে চেষ্টায় দক্ষতা বাড়ে, কাজ কঠিন হলেও সে বেশিক্ষণ লেগে থাকে। “তুমি তো জিনিয়াস” ধরনের প্রশংসা শিশুকে ব্যর্থতার ভয়ে ফেলতে পারে। বরং বলুন:\n\n- “প্রতিদিন অনুশীলন করেছ, দেখো তোমার হাতের লেখা কত সুন্দর হয়েছে।”\n- “কাজটা কঠিন ছিল, তুমি অন্যভাবে চেষ্টা করেছ।”\n- “তুমি হাল ছাড়োনি।”\n\n## ভুল থেকেই শেখা\n\nসন্তান ভুল করলে “এত বেখেয়াল কেন?” না বলে জিজ্ঞেস করুন, “এখান থেকে কী শিখলে?” নিজের ভুল আর কীভাবে তা শুধরেছেন, সেই গল্প বলুন। “আমি পারি না”-র সঙ্গে “এখনো” শব্দটা জুড়ে দিন: “লম্বা ভাগটা তুমি এখনো পারো না।”\n\n## সত্যিকারের দায়িত্ব দিন\n\nআত্মবিশ্বাস আসে সত্যিকারের কাজ করে: এক কাপ চা বানানো, দোকান থেকে রুটি কিনে আনা, ছোট কাজিনকে সাহায্য করা। ঘরের কাজ আর ছোট দায়িত্ব শিশুকে বোঝায় — সে পারে, আর তাকে দরকার।\n\n## তুলনা আর লজ্জা দেওয়া নয়\n\n“দেখো তোমার কাজিন প্রথম হয়েছে” — এ কথা উৎসাহ দেয় না, কষ্ট দেয় বেশি। ওজন, গায়ের রং বা চেহারা নিয়ে খোঁটাও তাই, যা অনেক পরিবারেই খুব চলে। আত্মীয়দের ভদ্রভাবে এমন কথা বন্ধ করতে বলুন। প্রতিটি শিশু আলাদা; তুলনা করলে করুন শুধু তার নিজের আগের অবস্থার সঙ্গে।\n\n## কোথাও তাকে উজ্জ্বল হতে দিন\n\nসব শিশু পরীক্ষায় ভালো করে না। কেউ সুন্দর আঁকে, কেউ ছোটদের সঙ্গে খুব মমতাময়, কেউ ফুটবল ভালোবাসে বা জিনিস সারাতে পারে। এই গুণগুলো লক্ষ করুন, মুখে বলুন।\n\n## মন খারাপ খেয়াল রাখুন\n\nসন্তান যদি প্রায়ই বলে “আমি কোনো কাজের না”, বন্ধুদের থেকে দূরে সরে যায়, বা কয়েক সপ্তাহ ধরে বেশির ভাগ দিন মন খারাপ থাকে — নরমভাবে কথা বলুন, আর ডাক্তারের পরামর্শ নিন।"}'::jsonb, '{}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['self esteem', 'confidence', 'growth mindset', 'praise', 'mistakes']::text[], false, 'in_review'::lp_review_status, 7007),
  ('mc-friendship-peer-pressure', 'article', 'scientific', 'shared', 'educational', 'consensus', '🤝', '{"en":"Friendship and peer pressure","bn":"বন্ধুত্ব আর বন্ধুদের চাপ"}'::jsonb, '{"en":"Friends matter more and more after seven. Know your child''s friends, teach them how to be a good friend, and practise how to say no.","bn":"সাত বছরের পর বন্ধুদের গুরুত্ব দিন দিন বাড়ে। সন্তানের বন্ধুদের চিনুন, ভালো বন্ধু হওয়া শেখান, আর “না” বলার অনুশীলন করান।"}'::jsonb, '{"en":"In middle childhood friends become very important. Children learn from friends how to share, solve arguments, keep promises and feel they belong. Friends can also push them to do things they know are wrong. Both are normal parts of growing up.\n\n## Know the friends\n\nAsk about friends in a relaxed way: “Who did you sit with today? What did you play?” Learn their names. Invite friends home, or meet their parents at school or in the neighbourhood. When you know the friends, you notice changes early.\n\n## Teach friendship skills\n\nSome children make friends easily; others need help. You can practise at home:\n\n- How to join a game: watch first, then ask, “Can I play too?”\n- Taking turns and losing without a fight\n- Saying sorry and making up after an argument\n- Being kind to a child who is new or alone\n\nOne or two good friends are enough. Not every child needs to be popular.\n\n## What peer pressure looks like\n\nAt this age, pressure may be to skip homework, tease another child, share a mean photo, buy something expensive, try a cigarette, or keep secrets from parents. Children go along because they fear being laughed at or left out.\n\n## Practise saying no\n\nRole-play at home. Help your child find words that feel natural:\n\n- “No thanks, I don''t want to.”\n- “My parents would kill me!” (a light way to blame you)\n- “Let''s do something else.”\n- Walking away and finding another friend\n\nAgree on a code word they can text or say on the phone if they want you to come and get them, no questions asked in that moment.\n\n## Stay the safe place\n\nIf your child tells you about a mistake made with friends, stay calm and thank them for telling you. If they get scolded every time, they will stop telling. Talk about what they could do differently next time.\n\n## Good friends, worrying signs\n\nA good friend makes your child feel good about themselves. Be concerned if a friendship involves frequent hurt, threats, stealing, older teens or adults you do not know, or demands to keep secrets from you.","bn":"মাঝ শৈশবে বন্ধুরা খুব গুরুত্বপূর্ণ হয়ে ওঠে। বন্ধুদের কাছ থেকে শিশু শেখে ভাগাভাগি করা, ঝগড়া মেটানো, কথা রাখা, আর কোথাও নিজের জায়গা আছে — এই অনুভূতি। আবার বন্ধুরাই কখনো কখনো এমন কিছু করতে চাপ দেয়, যা সে জানে ঠিক নয়। দুটোই বড় হওয়ার স্বাভাবিক অংশ।\n\n## বন্ধুদের চিনুন\n\nহালকা মেজাজে বন্ধুদের কথা জিজ্ঞেস করুন: “আজ কার পাশে বসেছিলে? কী খেললে?” তাদের নাম মনে রাখুন। বন্ধুদের বাসায় দাওয়াত দিন, বা স্কুলে বা পাড়ায় তাদের মা-বাবার সঙ্গে পরিচিত হোন। বন্ধুদের চিনলে কোনো পরিবর্তন হলে আগেভাগে টের পাবেন।\n\n## বন্ধুত্বের দক্ষতা শেখান\n\nকেউ সহজে বন্ধু বানায়, কারও সাহায্য লাগে। ঘরেই অনুশীলন করা যায়:\n\n- খেলায় কীভাবে যোগ দিতে হয়: আগে দেখা, তারপর জিজ্ঞেস করা, “আমিও খেলি?”\n- পালা করে খেলা, আর ঝগড়া ছাড়া হারতে পারা\n- ঝগড়ার পর দুঃখিত বলা, আবার মিলে যাওয়া\n- নতুন বা একা থাকা শিশুর সঙ্গে ভালো ব্যবহার করা\n\nএক-দুজন ভালো বন্ধুই যথেষ্ট। সব শিশুকে সবার প্রিয় হতে হবে, এমন নয়।\n\n## বন্ধুদের চাপ কেমন দেখায়\n\nএ বয়সে চাপ আসতে পারে হোমওয়ার্ক ফাঁকি দেওয়া, অন্য শিশুকে খেপানো, কারও খারাপ ছবি ছড়ানো, দামি কিছু কেনা, সিগারেট চেখে দেখা, বা মা-বাবার কাছে কিছু লুকানো নিয়ে। হাসির পাত্র হওয়া বা দল থেকে বাদ পড়ার ভয়ে শিশু রাজি হয়ে যায়।\n\n## “না” বলার অনুশীলন\n\nঘরে অভিনয় করে অনুশীলন করুন। সন্তানের মুখে স্বাভাবিক লাগে এমন কথা খুঁজে দিন:\n\n- “না রে, আমার ইচ্ছে নেই।”\n- “আম্মু-আব্বু জানলে আমাকে আস্ত রাখবে না!” (হালকাভাবে দোষটা আপনার ঘাড়ে দেওয়া)\n- “চল, অন্য কিছু করি।”\n- সরে গিয়ে অন্য বন্ধুর কাছে যাওয়া\n\nএকটা গোপন সংকেত শব্দ ঠিক করুন, যা সে ফোনে বললে বা লিখে পাঠালে আপনি গিয়ে তাকে নিয়ে আসবেন — সেই মুহূর্তে কোনো প্রশ্ন না করে।\n\n## নিরাপদ আশ্রয় হয়ে থাকুন\n\nবন্ধুদের সঙ্গে করা কোনো ভুলের কথা সন্তান বললে শান্ত থাকুন, বলার জন্য ধন্যবাদ দিন। প্রতিবার বকা খেলে সে বলা বন্ধ করে দেবে। পরের বার অন্যভাবে কী করা যেত, তা নিয়ে কথা বলুন।\n\n## ভালো বন্ধু, চিন্তার লক্ষণ\n\nভালো বন্ধুর সঙ্গে থাকলে শিশু নিজের সম্পর্কে ভালো বোধ করে। চিন্তার কারণ আছে যদি বন্ধুত্বে ঘন ঘন কষ্ট পাওয়া, হুমকি, চুরি, অচেনা বড় কিশোর বা বড় মানুষ জড়িত থাকে, বা আপনার কাছে কিছু লুকাতে বলা হয়।"}'::jsonb, '{}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['friends', 'friendship', 'peer pressure', 'saying no', 'social skills']::text[], false, 'in_review'::lp_review_status, 7008),
  ('mc-bullying', 'article', 'scientific', 'shared', 'important', 'guideline', '🛑', '{"en":"Bullying: if your child is bullied, or is the bully","bn":"বুলিং: সন্তান যখন শিকার, বা নিজেই অন্যকে হেনস্তা করে"}'::jsonb, '{"en":"Bullying is repeated, deliberate hurting of someone weaker. It is never “just teasing”. Here is how to spot it and what to do on either side.","bn":"বুলিং মানে দুর্বল কাউকে ইচ্ছে করে বারবার কষ্ট দেওয়া। এটা কখনোই “একটু মজা” নয়। কীভাবে বুঝবেন আর দুই দিক থেকেই কী করবেন, জেনে নিন।"}'::jsonb, '{"en":"Bullying is when a child or group hurts another child on purpose, again and again, and the child being hurt finds it hard to defend themselves. It can be hitting or pushing, name-calling, mocking someone''s skin colour, weight, accent or religion, leaving someone out, spreading rumours, or doing any of this online. It harms mental health and learning, and it is never the child''s fault.\n\n## Signs your child may be bullied\n\n- Does not want to go to school, or has stomach-aches or headaches on school days\n- Comes home with torn clothes, lost things or unexplained bruises\n- Is hungry after school (lunch or tiffin money taken)\n- Becomes quiet, sad, angry or jumpy after using a phone\n- Sleeps badly or has nightmares\n- Has fewer friends, or eats alone\n\n## If your child is bullied\n\n1. Listen calmly and believe them. Say: “Thank you for telling me. This is not your fault.”\n2. Do not tell them to “just hit back” — it often makes things worse and can get them punished.\n3. Write down what happened, when and who was there; save screenshots of online bullying.\n4. Contact the class teacher or head teacher and ask what they will do. Follow up.\n5. Help your child stay near friends and supportive adults, and practise calm, confident replies: “Stop. I don''t like that,” then walk away.\n6. For online bullying, block and report the account on the platform.\n\nIf there are threats, serious violence or sexual harassment, contact the police (999). The national child helpline 1098 can give advice.\n\n## If your child is the bully\n\nIt is hard to hear, but it is a chance to help. Children who bully often have reasons: wanting to fit in, being bullied themselves, copying harsh treatment at home, or struggling with anger.\n\n- Stay calm and find out what happened\n- Make it clear that bullying is not acceptable in your family\n- Help them think about how the other child felt\n- Agree on a way to put it right, such as an apology and stopping\n- Look honestly at whether there is shouting or hitting at home they may be copying\n- Work with the school, and ask for counselling if it continues\n\n## Bystanders matter\n\nTeach your child that standing with a child being bullied, or telling an adult, is brave, not snitching.","bn":"বুলিং হলো যখন কোনো শিশু বা দল ইচ্ছে করে বারবার আরেকটি শিশুকে কষ্ট দেয়, আর যে কষ্ট পাচ্ছে সে নিজেকে রক্ষা করতে পারে না। এটা হতে পারে মারা বা ধাক্কা দেওয়া, বাজে নামে ডাকা, গায়ের রং, ওজন, কথার টান বা ধর্ম নিয়ে ঠাট্টা, দল থেকে বাদ দেওয়া, গুজব ছড়ানো — বা অনলাইনে এর যেকোনোটা। এতে মানসিক স্বাস্থ্য আর পড়াশোনা দুটোরই ক্ষতি হয়। আর এটা কখনোই শিশুর দোষ নয়।\n\n## সন্তান বুলিংয়ের শিকার হচ্ছে কি না, বুঝবেন যেভাবে\n\n- স্কুলে যেতে চায় না, বা স্কুলের দিনে পেটব্যথা-মাথাব্যথা হয়\n- ছেঁড়া জামা, হারানো জিনিস বা অজানা কালশিটে নিয়ে বাড়ি ফেরে\n- স্কুল থেকে ফিরে খুব ক্ষুধার্ত (টিফিন বা টিফিনের টাকা কেড়ে নেওয়া হয়)\n- ফোন ব্যবহারের পর চুপচাপ, মন খারাপ, রাগী বা ভীত হয়ে যায়\n- ঘুম খারাপ হয়, দুঃস্বপ্ন দেখে\n- বন্ধু কমে গেছে, বা একা একা খায়\n\n## সন্তান বুলিংয়ের শিকার হলে\n\n1. শান্তভাবে শুনুন, বিশ্বাস করুন। বলুন: “আমাকে বলার জন্য ধন্যবাদ। এতে তোমার কোনো দোষ নেই।”\n2. “তুমিও মেরে দাও” বলবেন না — এতে প্রায়ই পরিস্থিতি খারাপ হয়, উল্টো সে-ই শাস্তি পেতে পারে।\n3. কী হয়েছে, কবে, কে কে ছিল — লিখে রাখুন; অনলাইন বুলিংয়ের স্ক্রিনশট রেখে দিন।\n4. শ্রেণিশিক্ষক বা প্রধান শিক্ষকের সঙ্গে যোগাযোগ করুন, তাঁরা কী করবেন জিজ্ঞেস করুন। পরে আবার খোঁজ নিন।\n5. সন্তান যেন বন্ধু আর সহায়ক বড়দের কাছাকাছি থাকে, তা নিশ্চিত করুন। শান্ত, আত্মবিশ্বাসী জবাব অনুশীলন করান: “থামো। আমার এটা ভালো লাগছে না,” তারপর সরে যাওয়া।\n6. অনলাইন বুলিংয়ে অ্যাকাউন্টটি ব্লক করুন ও প্ল্যাটফর্মে রিপোর্ট করুন।\n\nহুমকি, গুরুতর মারধর বা যৌন হয়রানি হলে পুলিশে (৯৯৯) যোগাযোগ করুন। জাতীয় শিশু হেল্পলাইন ১০৯৮-এ ফোন করেও পরামর্শ নেওয়া যায়।\n\n## সন্তান নিজেই যদি অন্যকে হেনস্তা করে\n\nশুনতে কষ্ট লাগে, কিন্তু এটা সাহায্য করার একটা সুযোগ। যে শিশু অন্যকে হেনস্তা করে, তার পেছনে প্রায়ই কারণ থাকে: দলে টিকে থাকার ইচ্ছা, নিজেও হেনস্তার শিকার হওয়া, ঘরের কঠোর আচরণ নকল করা, বা রাগ সামলাতে না পারা।\n\n- শান্ত থাকুন, আগে জানুন কী হয়েছে\n- পরিষ্কার করে বলুন, আপনার পরিবারে বুলিং চলবে না\n- অন্য শিশুটির কেমন লেগেছে, তা ভাবতে সাহায্য করুন\n- ভুল শোধরানোর একটা উপায় ঠিক করুন — যেমন ক্ষমা চাওয়া আর বন্ধ করা\n- সততার সঙ্গে দেখুন, ঘরে এমন চিৎকার বা মারধর আছে কি না যা সে নকল করছে\n- স্কুলের সঙ্গে মিলে কাজ করুন; না থামলে কাউন্সেলিং নিন\n\n## পাশে দাঁড়ানো মানুষদের ভূমিকা\n\nসন্তানকে শেখান — হেনস্তার শিকার শিশুর পাশে দাঁড়ানো বা কোনো বড়কে জানানো সাহসের কাজ, চুগলি নয়।"}'::jsonb, '{"seek_help":{"en":["Threats, serious violence or sexual harassment — call 999","Your child is afraid to go to school or refuses for days","Signs of depression, self-harm or talk of not wanting to live — get help the same day","The school does not act after you report it"],"bn":["হুমকি, গুরুতর মারধর বা যৌন হয়রানি — ৯৯৯-এ ফোন করুন","সন্তান স্কুলে যেতে ভয় পাচ্ছে, বা কয়েক দিন ধরে যেতে চাইছে না","বিষণ্নতা, নিজের ক্ষতি বা বাঁচতে না চাওয়ার কথা — সেদিনই সাহায্য নিন","জানানোর পরও স্কুল কোনো ব্যবস্থা নিচ্ছে না"]}}'::jsonb, 4, 2557, 4748, '{}'::text[], 'any', ARRAY['bullying', 'cyberbullying', 'teasing', 'school safety', 'victim', 'bully']::text[], false, 'in_review'::lp_review_status, 7009),
  ('mc-pocket-money-saving', 'article', 'general', 'shared', 'educational', 'consensus', '🪙', '{"en":"Pocket money and saving","bn":"হাতখরচ আর সঞ্চয়"}'::jsonb, '{"en":"A small, regular amount of pocket money is a safe way for children to learn to plan, wait, save and share.","bn":"অল্প, নিয়মিত হাতখরচ শিশুর জন্য পরিকল্পনা করা, অপেক্ষা করা, জমানো আর ভাগ করে নেওয়া শেখার নিরাপদ উপায়।"}'::jsonb, '{"en":"Children who handle a little money early learn lessons that are much more expensive to learn as adults: things cost money, choices have trade-offs, and waiting can get you something better. Pocket money does not need to be large. What matters is that it is regular and that the child makes real choices with it.\n\n## Getting started\n\nMany families start around 7 or 8 years with a small weekly amount, raised a little each year. Agree clearly on what it is for, for example tiffin from the school canteen, stickers, or saving for a cricket bat. Give it on the same day each week.\n\n## Three jars\n\nA simple system that works well is three jars or envelopes:\n\n- **Spend**: for small things now\n- **Save**: for a bigger goal in a few weeks or months\n- **Share**: to give to someone in need or to buy a gift for a family member\n\nLet your child decide how to split it, for example half to spend, and the rest to save and share. Draw a picture of the savings goal and stick it on the jar.\n\n## Let them make small mistakes\n\nIf your child spends everything on the first day, do not top it up. Feeling the empty jar for a few days is a cheap and powerful lesson. Talk about it kindly: “What would you do differently next week?”\n\n## Keep a little notebook\n\nOlder children can write what came in and what went out. This is their first budget. Celebrate when they reach a savings goal.\n\n## Money and work\n\nSome families pay a little extra for bigger jobs, like washing the car, but not for everyday chores like making their bed — those are part of living in a family. Decide what feels right for your home and stay consistent.\n\n## Money and values\n\nTalk openly about how your family earns and spends. Explain why you buy some things and not others. Children notice when friends have more; help them see that a person''s worth is not measured by phones, shoes or brands.\n\n## Safety\n\nChildren should never be given a parent''s mobile banking PIN or card details, and should know never to share an OTP with anyone. Many banks in Bangladesh offer savings accounts for school students that a parent opens; ask your bank if you want a safe place for bigger savings.","bn":"যে শিশু ছোটবেলা থেকেই একটু একটু টাকা সামলায়, সে এমন কিছু শেখে যা বড় হয়ে শিখতে গেলে অনেক দাম দিতে হয়: সবকিছুর দাম আছে, একটা নিলে আরেকটা ছাড়তে হয়, আর অপেক্ষা করলে আরও ভালো কিছু পাওয়া যায়। হাতখরচ বেশি হওয়ার দরকার নেই। দরকার হলো নিয়মিত পাওয়া, আর সেটা দিয়ে শিশু নিজে সত্যিকারের সিদ্ধান্ত নেবে।\n\n## যেভাবে শুরু করবেন\n\nঅনেক পরিবার ৭ বা ৮ বছর বয়সে সপ্তাহে অল্প কিছু টাকা দিয়ে শুরু করে, প্রতিবছর একটু বাড়ায়। টাকাটা কীসের জন্য, তা পরিষ্কার করে ঠিক করুন — যেমন স্কুলের ক্যান্টিনে টিফিন, স্টিকার, বা ক্রিকেট ব্যাটের জন্য জমানো। প্রতি সপ্তাহে একই দিনে দিন।\n\n## তিনটি বয়াম\n\nসহজ আর কার্যকর একটা উপায় হলো তিনটি বয়াম বা খাম:\n\n- **খরচ**: এখনকার ছোটখাটো জিনিসের জন্য\n- **জমা**: কয়েক সপ্তাহ বা মাস পরের বড় কোনো লক্ষ্যের জন্য\n- **ভাগ**: কোনো অভাবী মানুষকে দেওয়া বা পরিবারের কারও জন্য উপহার কেনা\n\nকোন বয়ামে কত যাবে, সন্তানকেই ঠিক করতে দিন — যেমন অর্ধেক খরচ, বাকিটা জমা আর ভাগ। জমানোর লক্ষ্যের একটা ছবি এঁকে বয়ামে লাগিয়ে দিন।\n\n## ছোট ছোট ভুল করতে দিন\n\nসন্তান যদি প্রথম দিনেই সব খরচ করে ফেলে, আবার টাকা দেবেন না। কয়েক দিন খালি বয়াম দেখাটাই সস্তা কিন্তু শক্তিশালী শিক্ষা। নরমভাবে কথা বলুন: “পরের সপ্তাহে কী অন্যভাবে করবে?”\n\n## ছোট একটা খাতা\n\nবড় শিশুরা কত এল আর কত গেল, লিখে রাখতে পারে। এটাই তার প্রথম বাজেট। জমানোর লক্ষ্যে পৌঁছালে একসঙ্গে আনন্দ করুন।\n\n## টাকা আর কাজ\n\nকিছু পরিবার বড় কাজের জন্য — যেমন গাড়ি ধোয়া — একটু বাড়তি টাকা দেয়, কিন্তু নিজের বিছানা গোছানোর মতো রোজকার কাজের জন্য নয়; ওগুলো পরিবারে থাকারই অংশ। আপনার ঘরের জন্য যা ঠিক মনে হয় তা ঠিক করুন, আর সেটা মেনে চলুন।\n\n## টাকা আর মূল্যবোধ\n\nপরিবার কীভাবে আয় করে আর খরচ করে, তা নিয়ে খোলাখুলি কথা বলুন। কেন কিছু জিনিস কেনেন আর কিছু কেনেন না, বুঝিয়ে বলুন। বন্ধুদের বেশি আছে — শিশু এটা খেয়াল করে; তাকে বুঝতে সাহায্য করুন যে ফোন, জুতা বা ব্র্যান্ড দিয়ে মানুষের মূল্য মাপা যায় না।\n\n## নিরাপত্তা\n\nশিশুকে কখনো মা-বাবার মোবাইল ব্যাংকিংয়ের পিন বা কার্ডের তথ্য দেবেন না। তাকে শেখান, ওটিপি (OTP) কাউকেই বলা যাবে না। বাংলাদেশে অনেক ব্যাংক স্কুলশিক্ষার্থীদের জন্য সঞ্চয় হিসাব খোলার সুযোগ দেয়, যা মা-বাবা খুলে দেন; বড় অঙ্কের জমার জন্য নিরাপদ জায়গা চাইলে আপনার ব্যাংকে জিজ্ঞেস করুন।"}'::jsonb, '{}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['pocket money', 'saving', 'money', 'budget', 'allowance']::text[], false, 'in_review'::lp_review_status, 7010),
  ('mc-chores-responsibility', 'article', 'general', 'shared', 'educational', 'consensus', '🧹', '{"en":"Responsibility and chores","bn":"দায়িত্ববোধ আর ঘরের কাজ"}'::jsonb, '{"en":"Everyday jobs at home teach children that they are capable and that a family works as a team — for boys and girls alike.","bn":"ঘরের রোজকার কাজ শিশুকে শেখায় যে সে পারে, আর পরিবার মানে একটা দল — ছেলে-মেয়ে সবার জন্যই।"}'::jsonb, '{"en":"In many busy homes, especially where there is house help, children are told, “You just study.” But children who share housework learn skills they will need all their lives: planning, caring for others and finishing a job. They also feel more confident and more connected to the family.\n\n## Jobs for 7 to 9 years\n\n- Make their own bed and keep their things tidy\n- Pack their school bag and polish their shoes\n- Set and clear the table, wipe up spills\n- Fold clothes and put them away\n- Water plants, feed a pet or chickens\n\n## Jobs for 10 to 13 years\n\n- Wash dishes and sweep a room\n- Help prepare simple food, with an adult nearby for knives and the stove\n- Hang and fold the washing\n- Buy small things from a nearby shop, if the route is safe\n- Help a younger sibling with reading or getting ready, while an adult is at home\n\n## Same jobs for boys and girls\n\nIn many families girls do housework while boys are free to play. Give the same jobs to sons and daughters. A boy who can cook and clean becomes a man who shares the load at home. Fathers doing housework in front of their children teach this best of all.\n\n## Make it work\n\n- Start with one or two jobs and add more as they grow\n- Show how to do it step by step, then let them try\n- Accept “good enough” — do not redo their work in front of them\n- Use a simple chart on the wall and tick it off together\n- Thank them: “The table looks great. Thank you for helping the family.”\n\n## When they forget or refuse\n\nKeep reminders short and calm. Link jobs to routines, for example “Plates go to the sink before you leave the table.” Natural consequences help: if the cricket kit is not put away, it is not available tomorrow. Avoid hitting, shouting or using chores as punishment, which makes children hate the work.\n\n## Safety first\n\nChildren should not use a gas stove, sharp knives, electrical sockets or cleaning chemicals without an adult. Keep chemicals in their original bottles, locked or high up.\n\n## Children are not workers\n\nChores should be short and fit around school, play and rest. They should never replace schooling or be work that is heavy or dangerous.","bn":"অনেক ব্যস্ত ঘরে, বিশেষ করে যেখানে কাজের সহকারী আছে, শিশুকে বলা হয়, “তুমি শুধু পড়ো।” কিন্তু যে শিশু ঘরের কাজে হাত লাগায়, সে এমন দক্ষতা শেখে যা সারাজীবন লাগবে: পরিকল্পনা, অন্যের যত্ন নেওয়া আর একটা কাজ শেষ করা। সে নিজেকে আরও আত্মবিশ্বাসী ভাবে, পরিবারের সঙ্গে টানও বাড়ে।\n\n## ৭ থেকে ৯ বছরের কাজ\n\n- নিজের বিছানা গোছানো, নিজের জিনিস গুছিয়ে রাখা\n- স্কুলের ব্যাগ গোছানো, জুতা পরিষ্কার করা\n- খাবার টেবিল সাজানো ও পরিষ্কার করা, কিছু পড়ে গেলে মুছে ফেলা\n- জামাকাপড় ভাঁজ করে জায়গামতো রাখা\n- গাছে পানি দেওয়া, পোষা প্রাণী বা মুরগিকে খাবার দেওয়া\n\n## ১০ থেকে ১৩ বছরের কাজ\n\n- থালাবাসন ধোয়া, ঘর ঝাড়ু দেওয়া\n- সহজ রান্নায় সাহায্য — ছুরি আর চুলার কাছে একজন বড় মানুষ থাকবেন\n- কাপড় মেলে দেওয়া, শুকালে ভাঁজ করা\n- রাস্তা নিরাপদ হলে কাছের দোকান থেকে ছোটখাটো জিনিস কিনে আনা\n- বাসায় বড় কেউ থাকলে ছোট ভাইবোনকে পড়তে বা তৈরি হতে সাহায্য করা\n\n## ছেলে-মেয়ের একই কাজ\n\nঅনেক পরিবারে মেয়েরা ঘরের কাজ করে, আর ছেলেরা খেলতে চলে যায়। ছেলে আর মেয়েকে একই কাজ দিন। যে ছেলে রান্না আর পরিষ্কার করতে পারে, সে বড় হয়ে এমন পুরুষ হয় যে ঘরের দায়িত্ব ভাগ করে নেয়। সন্তানের সামনে বাবা ঘরের কাজ করলে এই শিক্ষাটা সবচেয়ে ভালোভাবে পৌঁছায়।\n\n## যেভাবে কাজে লাগাবেন\n\n- এক-দুটো কাজ দিয়ে শুরু করুন, বয়স বাড়লে আরও যোগ করুন\n- ধাপে ধাপে দেখিয়ে দিন, তারপর নিজে করতে দিন\n- “মোটামুটি ভালো” হলেই মেনে নিন — তার সামনে কাজটা আবার করবেন না\n- দেয়ালে সহজ একটা চার্ট লাগান, একসঙ্গে টিক দিন\n- ধন্যবাদ দিন: “টেবিলটা দারুণ লাগছে। পরিবারকে সাহায্য করার জন্য ধন্যবাদ।”\n\n## ভুলে গেলে বা করতে না চাইলে\n\nমনে করিয়ে দিন অল্প কথায়, শান্তভাবে। কাজগুলো রুটিনের সঙ্গে জুড়ে দিন, যেমন “টেবিল ছাড়ার আগে প্লেট বেসিনে যাবে।” স্বাভাবিক পরিণতি কাজে দেয়: ক্রিকেটের সরঞ্জাম গুছিয়ে না রাখলে কাল তা পাওয়া যাবে না। মারধর, চিৎকার বা শাস্তি হিসেবে ঘরের কাজ দেওয়া এড়িয়ে চলুন — এতে শিশু কাজটাকেই ঘৃণা করতে শেখে।\n\n## আগে নিরাপত্তা\n\nবড় কেউ পাশে না থাকলে শিশু গ্যাসের চুলা, ধারালো ছুরি, বৈদ্যুতিক সকেট বা পরিষ্কারের রাসায়নিক ব্যবহার করবে না। রাসায়নিক আসল বোতলেই রাখুন, তালা দিয়ে বা উঁচুতে।\n\n## শিশু শ্রমিক নয়\n\nঘরের কাজ হবে অল্প সময়ের, স্কুল, খেলা আর বিশ্রামের সঙ্গে মানিয়ে। এটা কখনো পড়াশোনার জায়গা নেবে না, ভারী বা বিপজ্জনক কাজও হবে না।"}'::jsonb, '{}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['chores', 'responsibility', 'housework', 'independence', 'gender equality']::text[], false, 'in_review'::lp_review_status, 7011),
  ('mc-first-phone', 'article', 'scientific', 'shared', 'important', 'consensus', '📱', '{"en":"The first phone: when, and with what rules","bn":"প্রথম ফোন: কখন, আর কোন নিয়মে"}'::jsonb, '{"en":"There is no perfect age for a first phone. Decide by your child''s needs and maturity, start simple, and agree on clear rules before you hand it over.","bn":"প্রথম ফোনের কোনো নিখুঁত বয়স নেই। সন্তানের প্রয়োজন আর পরিপক্বতা দেখে সিদ্ধান্ত নিন, সাধারণ ফোন দিয়ে শুরু করুন, আর হাতে দেওয়ার আগেই পরিষ্কার নিয়ম ঠিক করুন।"}'::jsonb, '{"en":"Many children in Bangladesh start using a parent''s phone for online classes, games and videos long before they get their own. Sooner or later the question comes: “When can I have my own phone?” No expert body sets a single right age. A phone is a powerful tool that brings both benefits and risks, so the decision is about readiness, not age alone.\n\n## Questions to ask yourself\n\n- Does my child really need a phone now, for example to travel alone or to contact us after coaching?\n- Do they follow rules about screen time today?\n- Do they tell me when something upsets them?\n- Can they look after their things and keep to time limits?\n- Am I ready to set it up, check on it and talk about it regularly?\n\n## Start simple\n\nIf the main need is safety and contact, a basic phone that only calls and sends messages may be enough. If you choose a smartphone, set it up together before handing it over:\n\n- Turn on the built-in parental controls and family settings\n- Allow app downloads only with your approval\n- Set daily time limits and a night-time lock\n- Keep the passwords; tell your child you may check the phone, and explain why\n\n## Agree on rules first\n\nWrite the rules down together and sign them, like a contract. Good starting rules are:\n\n- No phone in the bedroom at night; it charges in a shared room\n- No phones at meals, during homework or for about an hour before bed\n- Ask before downloading any app or game\n- No social media accounts before the platform''s minimum age, which is 13 for most\n- Never share your address, school, photos or passwords online\n- Tell a parent straight away if anything feels wrong — you will not lose the phone for telling\n\n## Your example counts\n\nChildren copy what they see. If parents scroll at the dinner table or in bed, rules for children feel unfair. Try family rules that everyone follows.\n\n## Keep talking\n\nReview the rules every few months. Give more freedom as your child shows they can handle it. Ask what they like doing online and sometimes do it with them.\n\n## When to worry\n\nTalk to your child, and get help if needed, if phone use is cutting into sleep, schoolwork, meals or friendships, if your child becomes secretive and upset, or if you find contact with unknown adults.","bn":"বাংলাদেশে অনেক শিশু নিজের ফোন পাওয়ার অনেক আগেই অনলাইন ক্লাস, গেম আর ভিডিওর জন্য মা-বাবার ফোন ব্যবহার শুরু করে। একসময় প্রশ্নটা আসেই: “আমি কবে নিজের ফোন পাব?” কোনো বিশেষজ্ঞ সংস্থা একটা নির্দিষ্ট সঠিক বয়স ঠিক করে দেয়নি। ফোন শক্তিশালী একটা যন্ত্র — উপকারও আছে, ঝুঁকিও আছে। তাই সিদ্ধান্তটা শুধু বয়স দেখে নয়, প্রস্তুতি দেখে নিতে হয়।\n\n## নিজেকে যা জিজ্ঞেস করবেন\n\n- সন্তানের কি এখনই ফোন সত্যিই দরকার — যেমন একা যাতায়াত বা কোচিং শেষে যোগাযোগের জন্য?\n- এখন কি সে স্ক্রিন টাইমের নিয়ম মানে?\n- কিছু নিয়ে মন খারাপ হলে কি আমাকে বলে?\n- নিজের জিনিসের যত্ন নিতে আর সময়ের সীমা মানতে পারে?\n- আমি কি ফোনটা সেট করে দিতে, মাঝে মাঝে দেখতে আর নিয়মিত কথা বলতে প্রস্তুত?\n\n## সাধারণ দিয়ে শুরু করুন\n\nমূল প্রয়োজন যদি নিরাপত্তা আর যোগাযোগ হয়, তাহলে শুধু কল আর মেসেজ করা যায় এমন সাধারণ ফোনই যথেষ্ট হতে পারে। স্মার্টফোন দিলে হাতে দেওয়ার আগে একসঙ্গে সেট করুন:\n\n- ফোনের নিজস্ব প্যারেন্টাল কন্ট্রোল আর ফ্যামিলি সেটিং চালু করুন\n- আপনার অনুমতি ছাড়া অ্যাপ ডাউনলোড বন্ধ রাখুন\n- দৈনিক সময়সীমা আর রাতের লক সেট করুন\n- পাসওয়ার্ড আপনার কাছে রাখুন; সন্তানকে বলুন আপনি মাঝে মাঝে ফোন দেখতে পারেন, আর কেন — তাও বুঝিয়ে বলুন\n\n## আগে নিয়ম ঠিক করুন\n\nএকসঙ্গে বসে নিয়মগুলো লিখুন, চুক্তির মতো দুজনে সই করুন। শুরুর জন্য ভালো কিছু নিয়ম:\n\n- রাতে শোবার ঘরে ফোন নয়; চার্জ হবে সবার ব্যবহারের ঘরে\n- খাওয়ার সময়, হোমওয়ার্কের সময় আর ঘুমের আগের প্রায় এক ঘণ্টা ফোন নয়\n- যেকোনো অ্যাপ বা গেম নামানোর আগে জিজ্ঞেস করতে হবে\n- প্ল্যাটফর্মের ন্যূনতম বয়সের আগে সোশ্যাল মিডিয়া অ্যাকাউন্ট নয় — বেশির ভাগের ক্ষেত্রে যা ১৩\n- অনলাইনে কখনো নিজের ঠিকানা, স্কুল, ছবি বা পাসওয়ার্ড দেওয়া যাবে না\n- কিছু খারাপ লাগলে সঙ্গে সঙ্গে মা-বাবাকে বলতে হবে — বলার জন্য ফোন কেড়ে নেওয়া হবে না\n\n## আপনার উদাহরণই আসল\n\nশিশু যা দেখে তা-ই নকল করে। মা-বাবা যদি খাওয়ার টেবিলে বা বিছানায় শুয়ে ফোন স্ক্রল করেন, শিশুর জন্য নিয়ম তখন অন্যায় মনে হয়। এমন পারিবারিক নিয়ম রাখুন, যা সবাই মানে।\n\n## কথা চালিয়ে যান\n\nকয়েক মাস পরপর নিয়মগুলো আবার দেখুন। সন্তান দায়িত্ব সামলাতে পারছে দেখলে একটু একটু করে স্বাধীনতা বাড়ান। অনলাইনে সে কী করতে ভালোবাসে জিজ্ঞেস করুন, মাঝে মাঝে তার সঙ্গে আপনিও করুন।\n\n## কখন চিন্তা করবেন\n\nফোনের কারণে যদি ঘুম, পড়াশোনা, খাওয়া বা বন্ধুত্বে ভাটা পড়ে, সন্তান যদি লুকোছাপা করে আর মন খারাপ করে থাকে, বা অচেনা বড় মানুষের সঙ্গে যোগাযোগের প্রমাণ পান — সন্তানের সঙ্গে কথা বলুন, দরকার হলে সাহায্য নিন।"}'::jsonb, '{}'::jsonb, 4, 2557, 4748, '{}'::text[], 'any', ARRAY['first phone', 'smartphone', 'parental controls', 'screen rules', 'mobile']::text[], false, 'in_review'::lp_review_status, 7012),
  ('mc-gaming-limits', 'article', 'scientific', 'shared', 'important', 'consensus', '🎮', '{"en":"Gaming: healthy limits and age ratings","bn":"গেমিং: সুস্থ সীমা আর বয়সভিত্তিক রেটিং"}'::jsonb, '{"en":"Games can be fun and social, but they are designed to keep children playing. Check age ratings, set clear limits and protect sleep, study and outdoor play.","bn":"গেম মজার, বন্ধুদের সঙ্গে খেলাও যায় — কিন্তু এগুলো বানানোই হয় যেন শিশু খেলতেই থাকে। বয়সের রেটিং দেখুন, পরিষ্কার সীমা ঠিক করুন, আর ঘুম, পড়া ও বাইরের খেলা রক্ষা করুন।"}'::jsonb, '{"en":"Video and mobile games are part of many children''s lives. Some games build problem-solving, teamwork and creativity. But many are designed with rewards, levels and daily bonuses that make it very hard to stop. Children''s self-control is still developing, so they need adults to set the limits.\n\n## Check the age rating\n\nEvery game in an app store shows an age rating, often from systems such as PEGI or ESRB. The rating tells you about violence, frightening scenes, bad language, gambling-like features and chatting with strangers. Many popular shooting and battle games are rated for teenagers, not for 8 or 10 year olds. Look at the rating and, better still, watch the game being played before you say yes.\n\n## Healthy limits\n\nThe American Academy of Pediatrics advises families of school-age children to set consistent limits so that screens do not take the place of sleep, physical activity, homework and family time. WHO advises children to get an average of at least 60 minutes of active play a day and to limit time sitting in front of screens for fun. In practice:\n\n- Agree on when gaming is allowed, for example after homework, and for how long\n- Use a timer and give a five-minute warning before time is up\n- No gaming in the bedroom at night, and none in the hour before sleep\n- Keep some screen-free days or times every week\n\n## Online play and money\n\n- Turn off chat with strangers or limit it to friends you know\n- Teach your child never to share personal information or photos in games\n- Block in-app purchases or require a password, so a child cannot spend money by accident\n- Explain that “free” coins, diamonds or skins offered through links or strangers are usually scams\n\n## Play together sometimes\n\nAsk your child to teach you their game. You will learn what it is like, and they will be more open about what happens online.\n\n## Signs gaming is becoming a problem\n\n- Losing control over how long they play\n- Gaming comes before sleep, meals, school and friends\n- Carrying on despite clear harm, such as falling marks or no sleep\n- Strong anger, crying or aggression when asked to stop\n- Lying or stealing money to play\n\nIf several of these last for months, talk with a doctor or a child mental health professional. WHO recognises gaming disorder as a health condition when gaming seriously takes over a person''s life.","bn":"ভিডিও আর মোবাইল গেম অনেক শিশুর জীবনের অংশ। কিছু গেম সমস্যা সমাধান, দলগত কাজ আর সৃজনশীলতা বাড়ায়। কিন্তু অনেক গেম পুরস্কার, লেভেল আর প্রতিদিনের বোনাস দিয়ে এমনভাবে বানানো যে থামা খুব কঠিন। শিশুর আত্মনিয়ন্ত্রণ এখনো তৈরি হচ্ছে, তাই সীমা ঠিক করে দিতে হবে বড়দেরই।\n\n## বয়সের রেটিং দেখুন\n\nঅ্যাপ স্টোরে প্রতিটি গেমের পাশে বয়সের রেটিং থাকে, প্রায়ই PEGI বা ESRB-এর মতো পদ্ধতি থেকে। রেটিং দেখে বোঝা যায় গেমে মারামারি, ভয়ের দৃশ্য, খারাপ ভাষা, জুয়ার মতো ফিচার বা অচেনা মানুষের সঙ্গে চ্যাট আছে কি না। জনপ্রিয় অনেক গোলাগুলি আর যুদ্ধের গেম কিশোরদের জন্য রেট করা, ৮ বা ১০ বছরের শিশুর জন্য নয়। হ্যাঁ বলার আগে রেটিং দেখুন — আরও ভালো হয় গেমটা কেউ খেলছে, তা বসে দেখলে।\n\n## সুস্থ সীমা\n\nআমেরিকান একাডেমি অব পেডিয়াট্রিক্স স্কুলপড়ুয়া শিশুর পরিবারকে এমন নিয়মিত সীমা ঠিক করতে বলে, যাতে স্ক্রিন ঘুম, শারীরিক খেলাধুলা, হোমওয়ার্ক আর পরিবারের সময়ের জায়গা না নেয়। বিশ্ব স্বাস্থ্য সংস্থা বলে, শিশুরা যেন গড়ে দিনে অন্তত ৬০ মিনিট সক্রিয় খেলাধুলা করে, আর বিনোদনের জন্য স্ক্রিনের সামনে বসে থাকার সময় কমায়। বাস্তবে:\n\n- কখন গেম খেলা যাবে — যেমন হোমওয়ার্কের পরে — আর কতক্ষণ, তা একসঙ্গে ঠিক করুন\n- টাইমার ব্যবহার করুন, সময় শেষ হওয়ার পাঁচ মিনিট আগে জানিয়ে দিন\n- রাতে শোবার ঘরে গেম নয়, ঘুমের আগের এক ঘণ্টাও নয়\n- প্রতি সপ্তাহে কিছু দিন বা কিছু সময় স্ক্রিন ছাড়া রাখুন\n\n## অনলাইন খেলা আর টাকা\n\n- অচেনা মানুষের সঙ্গে চ্যাট বন্ধ রাখুন, বা শুধু চেনা বন্ধুদের মধ্যে সীমিত করুন\n- শেখান, গেমে কখনো নিজের তথ্য বা ছবি দেওয়া যাবে না\n- ইন-অ্যাপ কেনাকাটা বন্ধ রাখুন বা পাসওয়ার্ড দিয়ে আটকে দিন, যাতে ভুল করে টাকা খরচ না হয়\n- বুঝিয়ে বলুন, লিংক বা অচেনা মানুষের দেওয়া “ফ্রি” কয়েন, ডায়মন্ড বা স্কিন বেশির ভাগই প্রতারণা\n\n## মাঝে মাঝে একসঙ্গে খেলুন\n\nসন্তানকে বলুন তার গেমটা আপনাকে শেখাতে। গেমটা কেমন, আপনি বুঝবেন, আর অনলাইনে কী হয় তা নিয়েও সে আপনার সঙ্গে বেশি খোলামেলা হবে।\n\n## গেমিং সমস্যা হয়ে উঠছে যেসব লক্ষণে\n\n- কতক্ষণ খেলবে, তার ওপর নিয়ন্ত্রণ নেই\n- ঘুম, খাওয়া, স্কুল আর বন্ধুর চেয়ে গেম আগে\n- স্পষ্ট ক্ষতি হচ্ছে — নম্বর কমছে, ঘুম নেই — তবু খেলে যাচ্ছে\n- থামতে বললে প্রচণ্ড রাগ, কান্না বা মারমুখী আচরণ\n- খেলার জন্য মিথ্যা বলা বা টাকা চুরি\n\nএর কয়েকটা যদি কয়েক মাস ধরে চলে, ডাক্তার বা শিশু মানসিক স্বাস্থ্য বিশেষজ্ঞের সঙ্গে কথা বলুন। গেম যখন কারও জীবনের বড় অংশ দখল করে নেয়, বিশ্ব স্বাস্থ্য সংস্থা তাকে “গেমিং ডিসঅর্ডার” নামে একটি স্বাস্থ্য সমস্যা হিসেবে স্বীকৃতি দেয়।"}'::jsonb, '{}'::jsonb, 4, 2557, 4748, '{}'::text[], 'any', ARRAY['gaming', 'video games', 'age rating', 'screen time', 'in-app purchases']::text[], false, 'in_review'::lp_review_status, 7013),
  ('mc-online-safety', 'article', 'scientific', 'shared', 'important', 'consensus', '🔐', '{"en":"Online safety: strangers, photos, scams and telling a parent","bn":"অনলাইন নিরাপত্তা: অচেনা মানুষ, ছবি, প্রতারণা আর মা-বাবাকে বলা"}'::jsonb, '{"en":"Teach a few clear rules, keep devices in shared spaces, and make sure your child knows they can always tell you — without being punished.","bn":"কয়েকটি পরিষ্কার নিয়ম শেখান, ডিভাইস রাখুন সবার চোখের সামনে, আর সন্তান যেন জানে — যা-ই হোক, আপনাকে বললে শাস্তি পাবে না।"}'::jsonb, '{"en":"The internet opens up learning, friendship and fun. It also brings risks children cannot always see: adults pretending to be children, photos that spread forever, scams and upsetting content. The most powerful protection is not a filter. It is a child who tells a parent when something feels wrong.\n\n## Five rules to teach\n\n1. **People online are not always who they say they are.** A “12-year-old friend” in a game may be an adult.\n2. **Keep private things private.** Never share your full name, address, school, phone number, location, or passwords.\n3. **Think before sending a photo.** Once sent, you cannot take it back. Never send photos of your body, and never send any photo to someone you have not met in real life.\n4. **Never meet an online friend** without a parent knowing and coming with you.\n5. **If it feels wrong, stop and tell.** Close the app, do not reply, and tell a parent or trusted adult.\n\n## Warning signs of grooming\n\nSome adults try to build trust with children online in order to abuse them. Teach your child that these are red flags:\n\n- Someone gives lots of compliments, gifts, game credits or money\n- Asks to keep the friendship secret, or to move to a private app\n- Asks for photos, or talks about bodies or sex\n- Threatens to share photos or tell parents unless the child does what they say\n\nIf this happens, your child has done nothing wrong. Save the messages, do not pay or send anything, block the account, and report it to the platform and to the police (999). The child helpline 1098 can also advise.\n\n## Scams\n\nTeach your child:\n\n- Never share an OTP, PIN or password, even if someone says they are from a bank, a mobile wallet or a game company\n- Free diamonds, coins, prizes and “you have won” messages are almost always scams\n- Do not click links from strangers or download apps outside the official store\n\n## Make telling safe\n\nMany children hide problems because they fear losing their phone. Promise: “If something goes wrong online, tell me. I will help you, and I will not take your phone away for telling.” Keep that promise.\n\n## At home\n\n- Keep phones, tablets and computers in shared rooms, not bedrooms\n- Use parental controls and safe search, but do not rely on them alone\n- Talk about online life as easily as you talk about school\n- Have a short online-safety chat every month, and when your child starts a new app or game","bn":"ইন্টারনেট শেখা, বন্ধুত্ব আর আনন্দের দরজা খুলে দেয়। আবার এমন ঝুঁকিও আনে যা শিশু সবসময় দেখতে পায় না: শিশু সেজে থাকা বড় মানুষ, চিরকাল ছড়িয়ে থাকা ছবি, প্রতারণা আর মন খারাপ করা কনটেন্ট। সবচেয়ে বড় সুরক্ষা কোনো ফিল্টার নয়। সবচেয়ে বড় সুরক্ষা হলো এমন একটা শিশু, যে কিছু খারাপ লাগলেই মা-বাবাকে বলে।\n\n## যে পাঁচটি নিয়ম শেখাবেন\n\n1. **অনলাইনে মানুষ যা বলে, সবসময় তা নয়।** গেমের “১২ বছরের বন্ধু” আসলে একজন বড় মানুষও হতে পারে।\n2. **ব্যক্তিগত জিনিস ব্যক্তিগতই থাকবে।** পুরো নাম, ঠিকানা, স্কুল, ফোন নম্বর, লোকেশন বা পাসওয়ার্ড কখনো দেবে না।\n3. **ছবি পাঠানোর আগে ভাবো।** একবার পাঠালে আর ফেরানো যায় না। নিজের শরীরের ছবি কখনো পাঠাবে না, আর বাস্তবে দেখা হয়নি এমন কাউকে কোনো ছবিই পাঠাবে না।\n4. **অনলাইনের বন্ধুর সঙ্গে কখনো দেখা করবে না**, যদি না মা-বাবা জানেন আর সঙ্গে যান।\n5. **খারাপ লাগলে থামো, আর বলো।** অ্যাপ বন্ধ করো, উত্তর দিয়ো না, মা-বাবা বা বিশ্বস্ত কোনো বড়কে বলো।\n\n## ফাঁদে ফেলার (গ্রুমিং) সতর্ক সংকেত\n\nকিছু বড় মানুষ শিশুর ক্ষতি করার উদ্দেশ্যে অনলাইনে তার আস্থা অর্জনের চেষ্টা করে। সন্তানকে শেখান, এগুলো বিপদের সংকেত:\n\n- কেউ অনেক প্রশংসা, উপহার, গেমের ক্রেডিট বা টাকা দিচ্ছে\n- বন্ধুত্বটা গোপন রাখতে বলছে, বা অন্য কোনো প্রাইভেট অ্যাপে যেতে বলছে\n- ছবি চাইছে, বা শরীর বা যৌনতা নিয়ে কথা বলছে\n- কথা না শুনলে ছবি ছড়িয়ে দেওয়া বা মা-বাবাকে বলে দেওয়ার হুমকি দিচ্ছে\n\nএমন হলে আপনার সন্তানের কোনো দোষ নেই। মেসেজগুলো সংরক্ষণ করুন, টাকা বা কিছুই পাঠাবেন না, অ্যাকাউন্টটি ব্লক করুন, আর প্ল্যাটফর্মে ও পুলিশে (৯৯৯) রিপোর্ট করুন। শিশু হেল্পলাইন ১০৯৮-এও পরামর্শ পাওয়া যায়।\n\n## প্রতারণা\n\nসন্তানকে শেখান:\n\n- কেউ ব্যাংক, মোবাইল ওয়ালেট বা গেম কোম্পানির লোক বললেও ওটিপি, পিন বা পাসওয়ার্ড কখনো বলবে না\n- ফ্রি ডায়মন্ড, কয়েন, পুরস্কার আর “আপনি জিতেছেন” ধরনের মেসেজ প্রায় সবসময়ই প্রতারণা\n- অচেনা কারও পাঠানো লিংকে ক্লিক করবে না, অফিশিয়াল স্টোরের বাইরে থেকে অ্যাপ নামাবে না\n\n## বলাটা যেন নিরাপদ হয়\n\nফোন কেড়ে নেওয়ার ভয়ে অনেক শিশু সমস্যা লুকিয়ে রাখে। কথা দিন: “অনলাইনে কিছু খারাপ হলে আমাকে বলবে। আমি সাহায্য করব, আর বলার জন্য তোমার ফোন কেড়ে নেব না।” আর সেই কথা রাখুন।\n\n## ঘরে যা করবেন\n\n- ফোন, ট্যাব আর কম্পিউটার রাখুন সবার ব্যবহারের ঘরে, শোবার ঘরে নয়\n- প্যারেন্টাল কন্ট্রোল আর সেফ সার্চ ব্যবহার করুন, কিন্তু শুধু এগুলোর ওপর ভরসা করবেন না\n- স্কুল নিয়ে যেমন সহজে কথা বলেন, অনলাইন জীবন নিয়েও তেমনি বলুন\n- প্রতি মাসে, আর সন্তান নতুন কোনো অ্যাপ বা গেম শুরু করলে, অনলাইন নিরাপত্তা নিয়ে ছোট একটা আলাপ করুন"}'::jsonb, '{"seek_help":{"en":["Someone online asks for photos, threatens your child or demands money — call 999 and report it to the platform","An adult tries to arrange a meeting","Your child becomes fearful, secretive or withdrawn after using a device"],"bn":["অনলাইনে কেউ ছবি চাইছে, হুমকি দিচ্ছে বা টাকা চাইছে — ৯৯৯-এ ফোন করুন ও প্ল্যাটফর্মে রিপোর্ট করুন","কোনো বড় মানুষ দেখা করার ব্যবস্থা করতে চাইছে","ডিভাইস ব্যবহারের পর সন্তান ভীত, লুকোছাপা করা বা চুপচাপ হয়ে যাচ্ছে"]}}'::jsonb, 4, 2557, 4748, '{}'::text[], 'any', ARRAY['online safety', 'strangers', 'grooming', 'scams', 'privacy', 'photos', 'otp']::text[], false, 'in_review'::lp_review_status, 7014),
  ('mc-social-media-age', 'article', 'scientific', 'shared', 'important', 'consensus', '🔞', '{"en":"Social media: why most platforms say 13+","bn":"সোশ্যাল মিডিয়া: বেশির ভাগ প্ল্যাটফর্ম কেন ১৩+ বলে"}'::jsonb, '{"en":"Most social media platforms do not allow accounts under 13. There are good reasons to wait, and ways to prepare your child before they join.","bn":"বেশির ভাগ সোশ্যাল মিডিয়া প্ল্যাটফর্ম ১৩ বছরের কম বয়সীদের অ্যাকাউন্ট খুলতে দেয় না। অপেক্ষা করার ভালো কারণ আছে, আর যোগ দেওয়ার আগে সন্তানকে প্রস্তুত করারও উপায় আছে।"}'::jsonb, '{"en":"Many children under 13 in Bangladesh already have a Facebook, TikTok or other account, often opened with a false birth year, sometimes with a parent''s help. Most major social media platforms set 13 as the minimum age in their own rules. This is partly because of child privacy laws, and partly because younger children are not ready for what happens there.\n\n## Why waiting makes sense\n\n- Children under 13 find it harder to judge who is safe to talk to, and adults with bad intentions use these platforms to reach children\n- Feeds are designed to keep users scrolling, which cuts into sleep, study and play\n- Likes and comments invite constant comparison about looks, possessions and popularity at an age when self-esteem is still forming\n- Cyberbullying spreads fast and follows children home\n- Content is not checked for children, and violent or sexual material can appear\n\n## Do not lie about age\n\nOpening an account with a false birth year teaches children that rules can be cheated. It also means the platform treats them as older, so fewer protections apply. If your child joins at 13, use the correct birth date.\n\n## Before 13: practise\n\n- Use apps made for children, with parental controls, on a shared device\n- Talk about what you see in your own feed: what is real, what is edited, what is an advert\n- Discuss kindness online: “Would you say this to someone''s face?”\n- Let your child message grandparents or cousins through a family group, with you nearby\n\n## When they do join\n\n- Set the account to private and review privacy settings together\n- Agree that you will know the password and may look at the account\n- Only accept friends they know in real life\n- No posting school uniforms, location, or anything they would not want a teacher to see\n- Keep the phone out of the bedroom at night\n- Talk about how social media makes them feel, and take breaks\n\n## When to worry\n\nTalk with your child, and seek help if needed, if social media use is linked with poor sleep, low mood, anxiety about appearance, bullying, or contact with adults they do not know.","bn":"বাংলাদেশে ১৩ বছরের কম বয়সী অনেক শিশুর এরই মধ্যে ফেসবুক, টিকটক বা অন্য অ্যাকাউন্ট আছে — প্রায়ই ভুল জন্মসাল দিয়ে খোলা, কখনো মা-বাবার সাহায্যেই। বেশির ভাগ বড় সোশ্যাল মিডিয়া প্ল্যাটফর্ম নিজেদের নিয়মেই ন্যূনতম বয়স ১৩ রেখেছে। এর কিছুটা কারণ শিশুর গোপনীয়তা রক্ষার আইন, আর কিছুটা কারণ — সেখানে যা ঘটে, তার জন্য ছোট শিশুরা প্রস্তুত নয়।\n\n## অপেক্ষা করা কেন যুক্তিসংগত\n\n- কার সঙ্গে কথা বলা নিরাপদ, ১৩-র কম বয়সী শিশুর পক্ষে তা বোঝা কঠিন; আর খারাপ উদ্দেশ্যের বড় মানুষেরা শিশুদের কাছে পৌঁছাতে এসব প্ল্যাটফর্মই ব্যবহার করে\n- ফিড এমনভাবে বানানো যে মানুষ স্ক্রল করতেই থাকে — এতে ঘুম, পড়া আর খেলার সময় কমে যায়\n- লাইক আর কমেন্ট চেহারা, জিনিসপত্র আর জনপ্রিয়তা নিয়ে অবিরাম তুলনার দিকে ঠেলে দেয়, ঠিক যে বয়সে আত্মসম্মানবোধ গড়ে উঠছে\n- সাইবার বুলিং দ্রুত ছড়ায়, ঘরে পর্যন্ত পিছু নেয়\n- কনটেন্ট শিশুদের কথা ভেবে যাচাই করা হয় না; সহিংস বা যৌন বিষয়ও সামনে চলে আসতে পারে\n\n## বয়স নিয়ে মিথ্যা নয়\n\nভুল জন্মসাল দিয়ে অ্যাকাউন্ট খুললে শিশু শেখে যে নিয়ম ফাঁকি দেওয়া যায়। তা ছাড়া প্ল্যাটফর্ম তাকে বড় ধরে নেয়, ফলে সুরক্ষাও কম পায়। ১৩ বছরে যোগ দিলে সঠিক জন্মতারিখ দিন।\n\n## ১৩-র আগে: অনুশীলন\n\n- সবার ব্যবহারের ডিভাইসে, প্যারেন্টাল কন্ট্রোলসহ শিশুদের জন্য বানানো অ্যাপ ব্যবহার করুন\n- নিজের ফিডে যা দেখেন তা নিয়ে কথা বলুন: কোনটা সত্যি, কোনটা এডিট করা, কোনটা বিজ্ঞাপন\n- অনলাইনে ভদ্রতা নিয়ে আলাপ করুন: “এ কথাটা কি কারও মুখের ওপর বলতে পারতে?”\n- আপনি পাশে থেকে সন্তানকে পারিবারিক গ্রুপে দাদা-দাদি, নানা-নানি বা কাজিনদের মেসেজ করতে দিন\n\n## যখন যোগ দেবে\n\n- অ্যাকাউন্ট প্রাইভেট করুন, প্রাইভেসি সেটিং একসঙ্গে দেখুন\n- ঠিক করে নিন, পাসওয়ার্ড আপনি জানবেন আর মাঝে মাঝে অ্যাকাউন্ট দেখতে পারবেন\n- শুধু বাস্তবে চেনা মানুষদেরই বন্ধু হিসেবে নেবে\n- স্কুলের ইউনিফর্ম, লোকেশন, বা শিক্ষক দেখলে লজ্জা পাবে এমন কিছু পোস্ট করবে না\n- রাতে ফোন শোবার ঘরের বাইরে থাকবে\n- সোশ্যাল মিডিয়া তার মনে কেমন প্রভাব ফেলছে, তা নিয়ে কথা বলুন; মাঝে মাঝে বিরতি নিন\n\n## কখন চিন্তা করবেন\n\nসোশ্যাল মিডিয়ার সঙ্গে যদি কম ঘুম, মন খারাপ, চেহারা নিয়ে দুশ্চিন্তা, বুলিং বা অচেনা বড় মানুষের সঙ্গে যোগাযোগ জড়িয়ে থাকে — সন্তানের সঙ্গে কথা বলুন, দরকার হলে সাহায্য নিন।"}'::jsonb, '{}'::jsonb, 3, 3287, 4748, '{}'::text[], 'any', ARRAY['social media', 'age limit', 'facebook', 'tiktok', 'youtube', '13']::text[], false, 'in_review'::lp_review_status, 7015),
  ('mc-sleep', 'article', 'scientific', 'shared', 'important', 'guideline', '😴', '{"en":"Sleep: 9 to 12 hours a night","bn":"ঘুম: রাতে ৯ থেকে ১২ ঘণ্টা"}'::jsonb, '{"en":"Children aged 6 to 12 need 9–12 hours of sleep. Good sleep helps memory, mood, growth and health — and screens are the biggest thief.","bn":"৬ থেকে ১২ বছরের শিশুর রাতে ৯–১২ ঘণ্টা ঘুম দরকার। ভালো ঘুম স্মৃতিশক্তি, মেজাজ, বৃদ্ধি আর স্বাস্থ্যের জন্য জরুরি — আর সবচেয়ে বড় ঘুম-চোর হলো স্ক্রিন।"}'::jsonb, '{"en":"Sleep is when the body grows and the brain stores what it learned during the day. Recommendations endorsed by the American Academy of Pediatrics say children aged 6 to 12 need 9 to 12 hours of sleep every 24 hours, and teenagers 13 to 18 need 8 to 10 hours. Many children in Bangladesh sleep much less because of late dinners, evening coaching, homework and screens, then wake early for school.\n\n## Signs of too little sleep\n\n- Hard to wake in the morning, or falls asleep in class or in the car\n- Irritable, tearful or hyperactive\n- Trouble concentrating and remembering\n- Catches up with very long sleeps at weekends\n\n## Build a bedtime routine\n\n- Work back from wake-up time. If school starts early and your child must be up at 6:30, aim for lights out by around 9 to 9:30\n- Keep the same bedtime and wake time every day, including holidays, as far as you can\n- A calm routine: bath or wash, brush teeth, read or talk quietly, then lights out\n- A cool, dark, quiet room; a fan and a mosquito net if needed\n\n## Screens and sleep\n\nScreens keep the brain alert, and the light from them delays sleepiness. Exciting games and videos make it worse. The American Academy of Pediatrics advises keeping screens out of the bedroom at night and switching them off well before bed.\n\n- Phones, tablets and laptops charge outside the bedroom\n- No screens in the hour before bed\n- Parents follow the same rule when they can\n\n## Food and drink\n\nAvoid tea, coffee, cola and energy drinks in the afternoon and evening; they contain caffeine. Energy drinks are not suitable for children at all. A heavy meal right before bed can also disturb sleep.\n\n## Move during the day\n\nChildren who are active during the day, ideally outdoors, fall asleep more easily.\n\n## When to see a doctor\n\n- Loud snoring most nights, gasping or pauses in breathing\n- Very restless sleep, frequent night waking or nightmares for weeks\n- Sleepwalking with risk of injury\n- Daytime sleepiness despite enough hours in bed\n- Worries or fears that keep your child awake night after night","bn":"ঘুমের সময়েই শরীর বাড়ে, আর মস্তিষ্ক সারাদিনে যা শিখেছে তা জমা করে রাখে। আমেরিকান একাডেমি অব পেডিয়াট্রিক্স যে সুপারিশ সমর্থন করে, তাতে বলা হয়েছে ৬ থেকে ১২ বছরের শিশুর ২৪ ঘণ্টায় ৯ থেকে ১২ ঘণ্টা ঘুম দরকার, আর ১৩ থেকে ১৮ বছরের কিশোর-কিশোরীর ৮ থেকে ১০ ঘণ্টা। বাংলাদেশে অনেক শিশু এর চেয়ে অনেক কম ঘুমায় — দেরিতে রাতের খাবার, সন্ধ্যার কোচিং, হোমওয়ার্ক আর স্ক্রিনের কারণে — অথচ স্কুলের জন্য উঠতে হয় ভোরে।\n\n## কম ঘুমের লক্ষণ\n\n- সকালে ঘুম থেকে তোলা কঠিন, ক্লাসে বা গাড়িতে ঘুমিয়ে পড়ে\n- খিটখিটে, কাঁদুনে, বা অতিরিক্ত চঞ্চল\n- মন দিতে আর মনে রাখতে কষ্ট\n- ছুটির দিনে অনেক লম্বা ঘুম দিয়ে পুষিয়ে নেয়\n\n## ঘুমের রুটিন তৈরি করুন\n\n- ঘুম থেকে ওঠার সময় ধরে পেছনে হিসাব করুন। স্কুল সকালে শুরু হলে আর সাড়ে ৬টায় উঠতে হলে রাত ৯টা থেকে সাড়ে ৯টার মধ্যে বাতি নেভানোর লক্ষ্য রাখুন\n- যতটা সম্ভব ছুটির দিনসহ প্রতিদিন একই সময়ে ঘুমানো আর ওঠা\n- শান্ত রুটিন: গোসল বা হাত-মুখ ধোয়া, দাঁত ব্রাশ, একটু পড়া বা আস্তে গল্প, তারপর বাতি নেভানো\n- ঠান্ডা, অন্ধকার, শান্ত ঘর; দরকার হলে ফ্যান আর মশারি\n\n## স্ক্রিন আর ঘুম\n\nস্ক্রিন মস্তিষ্ককে সজাগ রাখে, আর এর আলো ঘুম আসতে দেরি করায়। উত্তেজনার গেম আর ভিডিও আরও খারাপ। আমেরিকান একাডেমি অব পেডিয়াট্রিক্স রাতে শোবার ঘরে স্ক্রিন না রাখতে আর ঘুমের বেশ আগেই বন্ধ করতে পরামর্শ দেয়।\n\n- ফোন, ট্যাব আর ল্যাপটপ চার্জ হবে শোবার ঘরের বাইরে\n- ঘুমের আগের এক ঘণ্টা কোনো স্ক্রিন নয়\n- মা-বাবাও যতটা পারেন এই নিয়ম মানুন\n\n## খাবার আর পানীয়\n\nবিকেল আর সন্ধ্যায় চা, কফি, কোলা আর এনার্জি ড্রিংক এড়িয়ে চলুন — এগুলোতে ক্যাফেইন আছে। এনার্জি ড্রিংক শিশুদের জন্য একেবারেই উপযুক্ত নয়। ঘুমের ঠিক আগে ভারী খাবারও ঘুমে ব্যাঘাত ঘটাতে পারে।\n\n## দিনে নড়াচড়া\n\nযে শিশু দিনে সক্রিয় থাকে — সম্ভব হলে বাইরে খেলে — সে সহজে ঘুমিয়ে পড়ে।\n\n## কখন ডাক্তার দেখাবেন\n\n- বেশির ভাগ রাতে জোরে নাক ডাকা, হাঁসফাঁস করা বা শ্বাস থেমে থেমে যাওয়া\n- কয়েক সপ্তাহ ধরে খুব অস্থির ঘুম, বারবার জেগে ওঠা বা দুঃস্বপ্ন\n- ঘুমের মধ্যে হাঁটা, যাতে আঘাতের ঝুঁকি আছে\n- বিছানায় যথেষ্ট সময় থাকার পরও দিনে ঘুম ঘুম ভাব\n- দুশ্চিন্তা বা ভয়ে রাতের পর রাত ঘুম না আসা"}'::jsonb, '{}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['sleep', 'bedtime', '9-12 hours', 'screens', 'snoring', 'tiredness']::text[], false, 'in_review'::lp_review_status, 7016),
  ('mc-healthy-eating', 'article', 'scientific', 'shared', 'important', 'guideline', '🍱', '{"en":"Eating well, junk food and soft drinks","bn":"ভালো খাওয়া, জাঙ্ক ফুড আর কোমল পানীয়"}'::jsonb, '{"en":"Growing children need a variety of home foods every day. Keep fried snacks, sweets and soft drinks for small, occasional treats, and protect their teeth.","bn":"বাড়ন্ত শিশুর প্রতিদিন ঘরের নানা রকম খাবার দরকার। ভাজাপোড়া, মিষ্টি আর কোমল পানীয় থাকুক মাঝে মাঝে অল্প একটু শখের খাবার হিসেবে, আর দাঁতের যত্ন নিন।"}'::jsonb, '{"en":"Between 7 and 13, children grow steadily and then, near puberty, very fast. They need energy, protein, iron, calcium and vitamins for growth, learning and fighting infections. At the same time, chips, instant noodles, fried snacks, sweets and soft drinks are cheap, tasty and sold right outside school gates.\n\n## A balanced plate, the Bangladeshi way\n\nThe national dietary guidelines encourage a variety of foods every day. A good day might include:\n\n- Rice, ruti or other grains for energy, with whole grains when possible\n- Dal, beans, fish, egg, chicken or meat for protein\n- Plenty of vegetables and leafy greens, such as lal shak, palong shak or pumpkin\n- Seasonal fruit such as guava, banana, papaya, mango or amloki\n- Milk, yogurt or small fish eaten with bones, for calcium\n- Safe drinking water through the day\n\n## Breakfast and tiffin\n\nChildren who skip breakfast find it harder to concentrate. Even something simple works: ruti with egg, khichuri, or bread with banana. A home-packed tiffin, such as fruit, boiled egg, chira, peanuts or a sandwich, is healthier and cheaper than canteen chips and soft drinks.\n\n## Junk food and soft drinks\n\n- Soft drinks, packaged juices and sweet tea are high in sugar; water and milk are better daily drinks\n- Energy drinks contain caffeine and are not suitable for children\n- Chips, instant noodles and fried street snacks are high in salt and fat; keep them as occasional treats\n- Do not use sweets or fast food as rewards for good marks\n- Street food can carry germs; choose freshly cooked food and avoid uncovered or cut fruit sold by the road\n\n## Teeth\n\nSugar, especially sticky sweets and sugary drinks between meals, causes tooth decay. Brush twice a day with fluoride toothpaste, especially before bed, and see a dentist if a tooth hurts or has a dark spot or hole.\n\n## Iron for girls approaching puberty\n\nOnce periods start, girls lose iron every month. Iron-rich foods such as leafy greens, dal, fish, meat, liver and eggs, along with fruit rich in vitamin C, help prevent anaemia.\n\n## Eat together, without pressure\n\nFamily meals help children try new foods. Avoid forcing or bribing. Never tease a child about their weight; talk about health and strength instead.\n\n## When to see a doctor\n\nIf your child seems very tired and pale, is losing weight, is not growing as expected, eats very little or very large amounts in secret, or is worried a lot about their body shape, see a doctor.","bn":"৭ থেকে ১৩ বছর বয়সে শিশু নিয়মিত বাড়ে, আর বয়ঃসন্ধির কাছাকাছি এসে বাড়ে খুব দ্রুত। বৃদ্ধি, পড়াশোনা আর রোগ প্রতিরোধের জন্য তার শক্তি, আমিষ, আয়রন, ক্যালসিয়াম আর ভিটামিন দরকার। অথচ চিপস, ইনস্ট্যান্ট নুডলস, ভাজাপোড়া, মিষ্টি আর কোমল পানীয় সস্তা, মজার, আর স্কুলের গেটের বাইরেই বিক্রি হয়।\n\n## বাংলাদেশি ধাঁচে সুষম খাবার\n\nজাতীয় খাদ্য নির্দেশিকা প্রতিদিন নানা রকম খাবার খেতে উৎসাহ দেয়। একটা ভালো দিনে থাকতে পারে:\n\n- শক্তির জন্য ভাত, রুটি বা অন্য শস্য — সম্ভব হলে লাল চাল বা লাল আটা\n- আমিষের জন্য ডাল, শিম-বরবটি, মাছ, ডিম, মুরগি বা মাংস\n- প্রচুর সবজি আর শাক — যেমন লাল শাক, পালং শাক, মিষ্টিকুমড়া\n- মৌসুমি ফল — পেয়ারা, কলা, পেঁপে, আম বা আমলকী\n- ক্যালসিয়ামের জন্য দুধ, দই বা কাঁটাসহ খাওয়া যায় এমন ছোট মাছ\n- সারাদিন নিরাপদ খাবার পানি\n\n## সকালের নাশতা আর টিফিন\n\nযে শিশু সকালের নাশতা বাদ দেয়, তার মন দিতে কষ্ট হয়। সহজ কিছু হলেও চলে: ডিম দিয়ে রুটি, খিচুড়ি, বা কলা দিয়ে পাউরুটি। বাসা থেকে দেওয়া টিফিন — ফল, সেদ্ধ ডিম, চিড়া, বাদাম বা স্যান্ডউইচ — ক্যান্টিনের চিপস আর কোমল পানীয়ের চেয়ে স্বাস্থ্যকর, সস্তাও।\n\n## জাঙ্ক ফুড আর কোমল পানীয়\n\n- কোমল পানীয়, প্যাকেটের জুস আর মিষ্টি চায়ে অনেক চিনি; রোজকার পানীয় হিসেবে পানি আর দুধ ভালো\n- এনার্জি ড্রিংকে ক্যাফেইন থাকে, শিশুদের জন্য উপযুক্ত নয়\n- চিপস, ইনস্ট্যান্ট নুডলস আর রাস্তার ভাজাপোড়ায় লবণ আর তেল বেশি; এগুলো মাঝে মাঝের শখের খাবার হিসেবেই রাখুন\n- ভালো নম্বরের পুরস্কার হিসেবে মিষ্টি বা ফাস্ট ফুড দেবেন না\n- রাস্তার খাবারে জীবাণু থাকতে পারে; গরম গরম রান্না করা খাবার বেছে নিন, রাস্তার পাশে খোলা বা কাটা ফল এড়িয়ে চলুন\n\n## দাঁত\n\nচিনি — বিশেষ করে দুই খাবারের মাঝে আঠালো মিষ্টি আর চিনিযুক্ত পানীয় — দাঁতে পোকা ধরায়। দিনে দুবার ফ্লুরাইডযুক্ত টুথপেস্ট দিয়ে দাঁত ব্রাশ করুক, বিশেষ করে ঘুমানোর আগে। দাঁতে ব্যথা হলে বা কালো দাগ বা গর্ত দেখা দিলে দাঁতের ডাক্তার দেখান।\n\n## বয়ঃসন্ধির কাছাকাছি মেয়েদের আয়রন\n\nমাসিক শুরু হলে মেয়েরা প্রতি মাসে আয়রন হারায়। শাক, ডাল, মাছ, মাংস, কলিজা আর ডিমের মতো আয়রনসমৃদ্ধ খাবার, সঙ্গে ভিটামিন সি-যুক্ত ফল রক্তস্বল্পতা ঠেকাতে সাহায্য করে।\n\n## চাপ ছাড়া একসঙ্গে খাওয়া\n\nপরিবারের সঙ্গে খেলে শিশু নতুন খাবার চেখে দেখতে আগ্রহী হয়। জোর করে বা লোভ দেখিয়ে খাওয়াবেন না। ওজন নিয়ে কখনো খোঁটা দেবেন না; বরং স্বাস্থ্য আর শক্তির কথা বলুন।\n\n## কখন ডাক্তার দেখাবেন\n\nসন্তান যদি খুব ক্লান্ত আর ফ্যাকাশে থাকে, ওজন কমতে থাকে, প্রত্যাশামতো না বাড়ে, খুব কম খায় বা লুকিয়ে অনেক বেশি খায়, বা শরীরের গড়ন নিয়ে অনেক দুশ্চিন্তা করে — ডাক্তার দেখান।"}'::jsonb, '{}'::jsonb, 4, 2557, 4748, '{}'::text[], 'any', ARRAY['nutrition', 'junk food', 'soft drinks', 'tiffin', 'breakfast', 'teeth', 'sugar']::text[], false, 'in_review'::lp_review_status, 7017),
  ('mc-active-60-minutes', 'article', 'scientific', 'shared', 'important', 'guideline', '⚽', '{"en":"60 minutes of activity a day, and sport","bn":"দিনে ৬০ মিনিট নড়াচড়া, আর খেলাধুলা"}'::jsonb, '{"en":"WHO advises children aged 5–17 to be active for an average of at least 60 minutes a day. Here is how to fit it into a busy school week.","bn":"বিশ্ব স্বাস্থ্য সংস্থা ৫–১৭ বছরের শিশু-কিশোরদের দিনে গড়ে অন্তত ৬০ মিনিট সক্রিয় থাকার পরামর্শ দেয়। ব্যস্ত স্কুল-সপ্তাহে এটা কীভাবে রাখবেন, জেনে নিন।"}'::jsonb, '{"en":"Regular physical activity builds strong bones, muscles and heart, improves sleep and mood, and helps concentration at school. WHO guidelines for children and adolescents aged 5 to 17 recommend:\n\n- An average of at least 60 minutes a day of moderate to vigorous activity, mostly aerobic, across the week\n- Vigorous activities, and activities that strengthen muscles and bones, on at least 3 days a week\n- Limiting the time spent sitting, especially recreational screen time\n\nModerate means breathing faster but still able to talk. Vigorous means too out of breath to say more than a few words.\n\n## Ideas that work in Bangladesh\n\n- Football, cricket, badminton, volleyball\n- Traditional games such as kabaddi, gollachut, dariabandha or kanamachi\n- Skipping rope, cycling, running races, dancing\n- Swimming, which is also a life-saving skill\n- Climbing, jumping and push-ups for muscles and bones\n- Walking or cycling to school or coaching when the route is safe\n\nThe 60 minutes can be added up across the day: 20 minutes at school break, 30 minutes of play in the afternoon and a short walk in the evening.\n\n## Girls need it too\n\nIn many families girls are kept indoors as they grow older. Girls need the same activity for strong bones, healthy weight and confidence. Find safe places, such as a school field, a rooftop, a courtyard or a supervised club, and encourage sports that she enjoys.\n\n## When space is limited\n\nIn crowded cities, try a rooftop or a park at weekends, skipping or dancing indoors, and climbing the stairs instead of the lift. Turn off screens and put on music.\n\n## Learn to swim\n\nDrowning is a leading cause of child deaths in Bangladesh. Swimming lessons from a trained instructor, in a safe place with an adult watching, protect children. Even good swimmers should never swim alone, in fast rivers or during floods.\n\n## Play safe\n\n- Helmets for cycling, and teaching road safety\n- Water to drink, and rest in the shade on very hot days\n- No playing near ponds, rivers or building sites without an adult\n\n## Parents lead the way\n\nA weekly family walk, a badminton game in the lane, or a father teaching cricket on Friday afternoons all count. Children who see adults being active are more likely to stay active as teenagers.\n\n## Children with disabilities or health conditions\n\nThey benefit from activity too. Ask the doctor or therapist which activities are safe and adapt the game so everyone can join.","bn":"নিয়মিত শারীরিক সক্রিয়তা হাড়, পেশি আর হৃদ্‌যন্ত্র মজবুত করে, ঘুম আর মেজাজ ভালো রাখে, স্কুলে মন দিতেও সাহায্য করে। ৫ থেকে ১৭ বছরের শিশু-কিশোরদের জন্য বিশ্ব স্বাস্থ্য সংস্থার নির্দেশিকা বলে:\n\n- সপ্তাহজুড়ে দিনে গড়ে অন্তত ৬০ মিনিট মাঝারি থেকে জোরালো শারীরিক কাজ, যার বেশির ভাগ হবে দম বাড়ানো (অ্যারোবিক) ধরনের\n- সপ্তাহে অন্তত ৩ দিন জোরালো কাজ, আর পেশি ও হাড় মজবুত করার কাজ\n- বসে থাকার সময় কমানো — বিশেষ করে বিনোদনের জন্য স্ক্রিনের সামনে বসে থাকা\n\nমাঝারি মানে শ্বাস দ্রুত হবে, কিন্তু কথা বলা যাবে। জোরালো মানে এত হাঁপিয়ে যাবে যে দু-চারটার বেশি শব্দ বলা কঠিন।\n\n## বাংলাদেশে যা কাজে দেয়\n\n- ফুটবল, ক্রিকেট, ব্যাডমিন্টন, ভলিবল\n- কাবাডি, গোল্লাছুট, দাড়িয়াবান্ধা বা কানামাছির মতো দেশি খেলা\n- দড়িলাফ, সাইকেল চালানো, দৌড় প্রতিযোগিতা, নাচ\n- সাঁতার — যা জীবন বাঁচানোর দক্ষতাও\n- পেশি ও হাড়ের জন্য গাছে বা দড়িতে চড়া, লাফানো, বুকডন\n- রাস্তা নিরাপদ হলে হেঁটে বা সাইকেলে স্কুল বা কোচিংয়ে যাওয়া\n\n৬০ মিনিট সারাদিনে ভাগ করেও হতে পারে: স্কুলের বিরতিতে ২০ মিনিট, বিকেলে ৩০ মিনিট খেলা, আর সন্ধ্যায় একটু হাঁটা।\n\n## মেয়েদেরও দরকার\n\nঅনেক পরিবারে মেয়ে বড় হলে তাকে ঘরে আটকে রাখা হয়। মজবুত হাড়, স্বাস্থ্যকর ওজন আর আত্মবিশ্বাসের জন্য মেয়েদেরও সমান নড়াচড়া দরকার। নিরাপদ জায়গা খুঁজুন — স্কুলের মাঠ, ছাদ, উঠান বা তত্ত্বাবধানে চলা কোনো ক্লাব — আর তার পছন্দের খেলায় উৎসাহ দিন।\n\n## জায়গা কম হলে\n\nভিড়ের শহরে ছাদ বা ছুটির দিনে পার্ক, ঘরের ভেতরে দড়িলাফ বা নাচ, লিফটের বদলে সিঁড়ি — চেষ্টা করে দেখুন। স্ক্রিন বন্ধ করে গান চালিয়ে দিন।\n\n## সাঁতার শিখুক\n\nবাংলাদেশে শিশুমৃত্যুর অন্যতম প্রধান কারণ পানিতে ডোবা। প্রশিক্ষিত শিক্ষকের কাছে, নিরাপদ জায়গায়, বড় কারও নজরদারিতে সাঁতার শেখা শিশুকে রক্ষা করে। ভালো সাঁতারুও কখনো একা, স্রোতের নদীতে বা বন্যার সময় সাঁতার কাটবে না।\n\n## নিরাপদে খেলা\n\n- সাইকেলে হেলমেট, আর রাস্তা পারাপারের নিয়ম শেখানো\n- খুব গরমের দিনে পানি খাওয়া আর ছায়ায় বিশ্রাম\n- বড় কেউ ছাড়া পুকুর, নদী বা নির্মাণাধীন জায়গার কাছে খেলা নয়\n\n## মা-বাবাই পথ দেখান\n\nসপ্তাহে একদিন পরিবার মিলে হাঁটা, গলিতে ব্যাডমিন্টন, বা শুক্রবার বিকেলে বাবার কাছে ক্রিকেট শেখা — সবই গোনায় ধরা হয়। বড়দের সক্রিয় দেখলে শিশু কিশোর বয়সেও সক্রিয় থাকে।\n\n## প্রতিবন্ধিতা বা অসুস্থতা থাকা শিশু\n\nতাদের জন্যও নড়াচড়া উপকারী। কোন খেলা নিরাপদ, ডাক্তার বা থেরাপিস্টকে জিজ্ঞেস করুন, আর খেলাটা এমনভাবে বদলে নিন যাতে সবাই অংশ নিতে পারে।"}'::jsonb, '{}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['physical activity', 'sport', '60 minutes', 'exercise', 'swimming', 'outdoor play']::text[], false, 'in_review'::lp_review_status, 7018),
  ('mc-puberty-talk-early', 'article', 'scientific', 'shared', 'important', 'consensus', '🌿', '{"en":"Puberty is coming: talk early","bn":"বয়ঃসন্ধি আসছে: আগেভাগেই কথা বলুন"}'::jsonb, '{"en":"Children should hear about puberty from their parents before their bodies change. Start simple at 8 or 9, and keep the conversation going.","bn":"শরীর বদলানোর আগেই শিশুর উচিত বয়ঃসন্ধির কথা মা-বাবার কাছ থেকে জানা। ৮ বা ৯ বছরে সহজভাবে শুরু করুন, আর আলাপটা চালিয়ে যান।"}'::jsonb, '{"en":"Puberty is the time when a child''s body slowly becomes an adult body. In girls it usually starts between 8 and 13 years, and in boys between 9 and 14. In many Bangladeshi families this topic is never discussed, so children learn from friends, the internet or rumours — often wrongly — and may feel frightened or ashamed when changes begin.\n\n## Why talk early\n\nChildren cope much better with changes they expect. A girl who knows about periods before her first one is far less scared. A boy who knows about wet dreams knows he is not ill. Talking early also tells your child: “You can ask me anything.”\n\n## What changes for everyone\n\n- A growth spurt: arms, legs and feet grow fast, sometimes making children clumsy\n- Hair under the arms and around the private parts\n- More sweat and body odour, so a daily bath and clean clothes matter more\n- Oily skin and pimples\n- Stronger feelings, mood swings and wanting more privacy\n\nGirls'' changes include breast development and periods. Boys'' changes include growth of the testicles and penis, a deeper voice, facial hair and wet dreams. Children should learn about both sexes, not only their own, so they understand and respect each other.\n\n## How to start\n\n- Use correct, simple words for body parts\n- Use everyday moments: a TV advert for pads, a cousin''s voice breaking, buying deodorant\n- Keep it short and come back to it many times rather than one big talk\n- A child-friendly book from a doctor or school can help\n- If you do not know an answer, say “Let''s find out together”\n\nMothers and fathers can both talk to sons and daughters. Some children prefer the parent of the same sex; a trusted aunt, uncle or older cousin can also help, especially in single-parent families.\n\n## Your tone matters\n\nStay calm and matter-of-fact. Avoid teasing about breasts, voice or height, and stop relatives from doing it. Changes happen at different times for different children, and that is normal.\n\n## Privacy and safety\n\nRespect your child''s growing need for privacy: knock before entering, and let them dress alone. At the same time, remind them that no one has the right to touch their private parts or ask for photos, and that they can always tell you.\n\n## When to see a doctor\n\n- Signs of puberty before 8 in girls or before 9 in boys\n- No signs of puberty by 13 in girls or 14 in boys\n- No period by 15 in girls\n- Your child is very distressed about their body","bn":"বয়ঃসন্ধি হলো সেই সময়, যখন শিশুর শরীর ধীরে ধীরে বড় মানুষের শরীরে পরিণত হয়। মেয়েদের সাধারণত ৮ থেকে ১৩ বছরের মধ্যে, আর ছেলেদের ৯ থেকে ১৪ বছরের মধ্যে এটা শুরু হয়। বাংলাদেশের অনেক পরিবারে এ বিষয়ে কখনো কথাই হয় না। ফলে শিশু শেখে বন্ধু, ইন্টারনেট বা গুজব থেকে — প্রায়ই ভুল — আর পরিবর্তন শুরু হলে ভয় বা লজ্জা পায়।\n\n## কেন আগেভাগে কথা বলবেন\n\nযে পরিবর্তনের কথা আগে থেকে জানা থাকে, শিশু তা অনেক ভালোভাবে সামলাতে পারে। প্রথম মাসিকের আগেই যে মেয়ে এ সম্পর্কে জানে, সে অনেক কম ভয় পায়। যে ছেলে স্বপ্নদোষের কথা জানে, সে বোঝে সে অসুস্থ নয়। আগেভাগে কথা বললে সন্তান এটাও বোঝে: “যেকোনো কিছু আমি জিজ্ঞেস করতে পারি।”\n\n## সবার ক্ষেত্রে যা বদলায়\n\n- হঠাৎ লম্বা হওয়া: হাত, পা আর পায়ের পাতা দ্রুত বাড়ে, কখনো শিশু একটু আনাড়ি হয়ে যায়\n- বগলে আর গোপনাঙ্গের চারপাশে লোম\n- ঘাম আর গায়ের গন্ধ বাড়ে, তাই প্রতিদিন গোসল আর পরিষ্কার কাপড় আরও জরুরি\n- তৈলাক্ত ত্বক আর ব্রণ\n- তীব্র অনুভূতি, মেজাজের ওঠানামা, আর নিজের জন্য একটু আড়াল চাওয়া\n\nমেয়েদের পরিবর্তনের মধ্যে আছে স্তনের বৃদ্ধি আর মাসিক। ছেলেদের পরিবর্তনের মধ্যে আছে অণ্ডকোষ ও পুরুষাঙ্গের বৃদ্ধি, ভারী গলা, দাড়ি-গোঁফ আর স্বপ্নদোষ। শিশু শুধু নিজের নয়, দুই লিঙ্গের পরিবর্তন সম্পর্কেই জানুক — তাতে একে অপরকে বুঝবে, সম্মান করবে।\n\n## কীভাবে শুরু করবেন\n\n- শরীরের অঙ্গের সঠিক, সহজ নাম ব্যবহার করুন\n- রোজকার মুহূর্ত কাজে লাগান: টিভিতে প্যাডের বিজ্ঞাপন, কাজিনের গলা ভাঙা, ডিওডোরেন্ট কেনা\n- একবারে লম্বা আলোচনা না করে ছোট ছোট করে বারবার ফিরে আসুন\n- ডাক্তার বা স্কুলের দেওয়া শিশু-উপযোগী বই কাজে আসতে পারে\n- উত্তর না জানলে বলুন, “চলো, একসঙ্গে জেনে নিই”\n\nমা আর বাবা দুজনেই ছেলে-মেয়ে দুজনের সঙ্গে কথা বলতে পারেন। কিছু শিশু একই লিঙ্গের মা বা বাবার সঙ্গে বেশি স্বচ্ছন্দ; বিশ্বস্ত খালা-ফুপু, চাচা-মামা বা বড় কাজিনও সাহায্য করতে পারেন, বিশেষ করে একক অভিভাবকের পরিবারে।\n\n## আপনার বলার ধরন গুরুত্বপূর্ণ\n\nশান্ত আর স্বাভাবিক থাকুন। স্তন, গলার স্বর বা উচ্চতা নিয়ে ঠাট্টা করবেন না, আত্মীয়রা করলে থামান। একেক শিশুর পরিবর্তন একেক সময়ে আসে — এটাই স্বাভাবিক।\n\n## আড়াল আর নিরাপত্তা\n\nসন্তানের বাড়তে থাকা আড়ালের প্রয়োজনকে সম্মান করুন: ঘরে ঢোকার আগে দরজায় টোকা দিন, একা কাপড় বদলাতে দিন। একই সঙ্গে মনে করিয়ে দিন, তার গোপনাঙ্গে হাত দেওয়ার বা ছবি চাওয়ার অধিকার কারও নেই, আর যেকোনো কিছু সে সবসময় আপনাকে বলতে পারে।\n\n## কখন ডাক্তার দেখাবেন\n\n- মেয়েদের ৮ বছরের আগে বা ছেলেদের ৯ বছরের আগে বয়ঃসন্ধির লক্ষণ\n- মেয়েদের ১৩ বা ছেলেদের ১৪ বছরেও বয়ঃসন্ধির কোনো লক্ষণ নেই\n- মেয়েদের ১৫ বছরেও মাসিক শুরু হয়নি\n- নিজের শরীর নিয়ে সন্তান খুব বেশি কষ্টে আছে"}'::jsonb, '{}'::jsonb, 4, 2922, 4748, '{}'::text[], 'any', ARRAY['puberty', 'body changes', 'talking about puberty', 'growth spurt', 'hygiene']::text[], false, 'in_review'::lp_review_status, 7019),
  ('mc-first-period-prep', 'article', 'scientific', 'shared', 'important', 'consensus', '🌸', '{"en":"Preparing your daughter for her first period","bn":"মেয়েকে প্রথম মাসিকের জন্য প্রস্তুত করা"}'::jsonb, '{"en":"A girl who knows what a period is, has pads ready and knows she can talk to you will meet her first period calmly, not in fear.","bn":"মাসিক কী, তা যে মেয়ে জানে, যার কাছে প্যাড প্রস্তুত, আর যে জানে আপনাকে বলা যায় — সে প্রথম মাসিককে ভয়ে নয়, শান্তভাবে গ্রহণ করে।"}'::jsonb, '{"en":"A period (menstruation) is a normal, healthy sign that a girl''s body is growing up. Each month the lining of the womb builds up, and if there is no pregnancy it comes out as blood through the vagina over a few days. Many girls in Bangladesh get their first period without knowing what it is and think they are injured or ill. Telling your daughter before it happens is one of the kindest things you can do.\n\n## When it usually comes\n\nThe first period usually comes about two years after the breasts start to develop, most often between 10 and 15 years. A white or clear discharge in her pants in the months before is normal and a sign that her period may come soon. Talk with her by 9 years, or earlier if her breasts have started to grow.\n\n## What to explain\n\n- Bleeding usually lasts 2 to 7 days, and the amount is less than it looks\n- In the first year or two, periods are often irregular; that is normal\n- Some girls have cramps in the lower tummy or back, tiredness or mood changes\n- She can bathe, go to school, study, play and eat normally during her period\n\n## Pads and cloth\n\nShow her a pad and how to use it before she needs it.\n\n- Change a pad every 4 to 6 hours, or more often if it is heavy\n- Wrap the used pad in paper and put it in a bin; do not flush it\n- If using cloth, use clean cotton, wash it with soap and clean water, dry it fully in sunlight and store it in a clean, dry place\n- Wash the outer private area with clean water each day; no soap or anything else inside\n- Wash hands before and after changing\n\n## A school kit\n\nPack a small pouch with two pads, spare pants and a plastic bag. Tell her to go to a female teacher or the school nurse if her period starts at school.\n\n## Myths to avoid\n\nSome families tell girls not to bathe, not to eat fish, eggs or sour food, or to stay inside during periods. These beliefs are not supported by health science. Bathing keeps her clean and comfortable, and she needs nutritious food, especially iron-rich foods, because she loses iron each month.\n\n## Fathers can help\n\nA father who buys pads without embarrassment, or simply says “Tell me if you need anything,” teaches his daughter that her body is nothing to be ashamed of. Brothers should learn about periods too, so they respect their sisters.\n\n## Cramps\n\nA warm bottle on the tummy, rest and gentle movement can help. If pain is strong, ask a health worker before giving any medicine.\n\n## When to see a doctor\n\n- Soaking a pad every 1 to 2 hours, or bleeding for more than 7 days\n- Pain so bad she cannot go to school, or fainting and dizziness\n- No period by 15, or periods stop for months after starting\n- Periods starting before 8 years","bn":"মাসিক (menstruation) একটা স্বাভাবিক, সুস্থ লক্ষণ যে মেয়ের শরীর বড় হচ্ছে। প্রতি মাসে জরায়ুর ভেতরের আস্তরণ পুরু হয়; গর্ভধারণ না হলে কয়েক দিন ধরে সেটা রক্ত হিসেবে যোনিপথ দিয়ে বেরিয়ে আসে। বাংলাদেশে অনেক মেয়ের প্রথম মাসিক হয় কিছু না জেনেই — সে ভাবে আঘাত পেয়েছে বা অসুখ হয়েছে। আগেভাগে মেয়েকে জানিয়ে রাখা আপনার পক্ষে করা সবচেয়ে মমতার কাজগুলোর একটি।\n\n## সাধারণত কখন হয়\n\nস্তনের বৃদ্ধি শুরু হওয়ার প্রায় দুই বছর পর সাধারণত প্রথম মাসিক হয় — বেশির ভাগ ক্ষেত্রে ১০ থেকে ১৫ বছরের মধ্যে। এর কয়েক মাস আগে থেকে প্যান্টিতে সাদা বা স্বচ্ছ স্রাব দেখা স্বাভাবিক, আর এটা বোঝায় মাসিক শিগগিরই আসতে পারে। ৯ বছরের মধ্যে, বা স্তনের বৃদ্ধি শুরু হলে তারও আগে, মেয়ের সঙ্গে কথা বলুন।\n\n## যা বুঝিয়ে বলবেন\n\n- রক্তপাত সাধারণত ২ থেকে ৭ দিন থাকে; পরিমাণ যতটা মনে হয়, আসলে তার চেয়ে কম\n- প্রথম এক-দুই বছর মাসিক প্রায়ই অনিয়মিত হয়; এটা স্বাভাবিক\n- কারও কারও তলপেটে বা কোমরে ব্যথা, ক্লান্তি বা মেজাজের পরিবর্তন হয়\n- মাসিকের সময় সে গোসল করতে, স্কুলে যেতে, পড়তে, খেলতে আর স্বাভাবিকভাবে খেতে পারবে\n\n## প্যাড আর কাপড়\n\nদরকার হওয়ার আগেই একটা প্যাড দেখান, কীভাবে ব্যবহার করতে হয় বুঝিয়ে দিন।\n\n- ৪ থেকে ৬ ঘণ্টা পরপর প্যাড বদলাবে, রক্ত বেশি হলে আরও ঘন ঘন\n- ব্যবহার করা প্যাড কাগজে মুড়িয়ে ময়লার ঝুড়িতে ফেলবে; কমোডে ফেলবে না\n- কাপড় ব্যবহার করলে পরিষ্কার সুতি কাপড় নেবে, সাবান আর পরিষ্কার পানিতে ধোবে, রোদে পুরোপুরি শুকাবে, আর পরিষ্কার শুকনো জায়গায় রাখবে\n- প্রতিদিন গোপনাঙ্গের বাইরের অংশ পরিষ্কার পানি দিয়ে ধোবে; ভেতরে সাবান বা অন্য কিছু দেবে না\n- বদলানোর আগে ও পরে হাত ধোবে\n\n## স্কুলের জন্য ছোট ব্যাগ\n\nছোট একটা থলেতে দুটো প্যাড, একটা বাড়তি প্যান্টি আর একটা পলিথিন ব্যাগ দিয়ে দিন। বলে রাখুন, স্কুলে মাসিক শুরু হলে কোনো নারী শিক্ষক বা স্কুলের নার্সের কাছে যাবে।\n\n## যে ভুল ধারণা এড়াবেন\n\nকিছু পরিবারে মেয়েদের বলা হয় মাসিকের সময় গোসল না করতে, মাছ, ডিম বা টক না খেতে, বা ঘরে বন্দি থাকতে। স্বাস্থ্যবিজ্ঞান এসব ধারণা সমর্থন করে না। গোসল তাকে পরিষ্কার আর আরামে রাখে। আর প্রতি মাসে আয়রন হারায় বলে তার পুষ্টিকর খাবার — বিশেষ করে আয়রনসমৃদ্ধ খাবার — দরকার।\n\n## বাবাও সাহায্য করতে পারেন\n\nযে বাবা সংকোচ ছাড়া প্যাড কিনে আনেন, বা শুধু বলেন “কিছু লাগলে আমাকে বলো,” তিনি মেয়েকে শেখান যে নিজের শরীর নিয়ে লজ্জার কিছু নেই। ভাইদেরও মাসিক সম্পর্কে জানা উচিত, যাতে তারা বোনকে সম্মান করে।\n\n## পেটব্যথা\n\nতলপেটে গরম পানির বোতল, বিশ্রাম আর হালকা নড়াচড়া আরাম দিতে পারে। ব্যথা বেশি হলে কোনো ওষুধ দেওয়ার আগে স্বাস্থ্যকর্মীর পরামর্শ নিন।\n\n## কখন ডাক্তার দেখাবেন\n\n- ১ থেকে ২ ঘণ্টায় একটা প্যাড ভিজে যাচ্ছে, বা ৭ দিনের বেশি রক্তপাত\n- এত ব্যথা যে স্কুলে যেতে পারছে না, বা অজ্ঞান হয়ে যাওয়া, মাথা ঘোরা\n- ১৫ বছরেও মাসিক শুরু হয়নি, বা শুরু হওয়ার পর কয়েক মাস ধরে বন্ধ\n- ৮ বছরের আগেই মাসিক শুরু"}'::jsonb, '{"seek_help":{"en":["Soaking a pad every 1–2 hours, or bleeding for more than 7 days","Pain that stops her going to school, or fainting","No period by 15, or periods stop for several months","Any period or breast development before 8 years"],"bn":["১–২ ঘণ্টায় একটা প্যাড ভিজে যাওয়া, বা ৭ দিনের বেশি রক্তপাত","এমন ব্যথা যে স্কুলে যেতে পারছে না, বা অজ্ঞান হয়ে যাওয়া","১৫ বছরেও মাসিক হয়নি, বা কয়েক মাস ধরে বন্ধ","৮ বছরের আগে মাসিক বা স্তনের বৃদ্ধি"]}}'::jsonb, 4, 3287, 4748, '{}'::text[], 'female', ARRAY['period', 'menstruation', 'first period', 'pads', 'menstrual hygiene', 'girls']::text[], false, 'in_review'::lp_review_status, 7020),
  ('mc-boys-body-changes', 'article', 'scientific', 'shared', 'important', 'consensus', '🧑', '{"en":"For boys: body changes in puberty","bn":"ছেলেদের জন্য: বয়ঃসন্ধিতে শরীরের পরিবর্তন"}'::jsonb, '{"en":"Boys need to know what is coming — growth, voice change, hair, wet dreams — and that all of it is normal. Fathers can lead this talk.","bn":"ছেলেদের জানা দরকার কী আসছে — লম্বা হওয়া, গলা ভাঙা, লোম, স্বপ্নদোষ — আর এর সবটাই স্বাভাবিক। এই আলাপে বাবা নেতৃত্ব দিতে পারেন।"}'::jsonb, '{"en":"Boys often get less information about puberty than girls, because people assume they will “just figure it out”. In reality, many boys feel confused or ashamed about changes they do not understand. A calm talk from a father, mother or trusted adult makes a big difference.\n\n## When it starts\n\nPuberty in boys usually starts between 9 and 14 years. The first sign is usually that the testicles get bigger. Boys tend to start a little later than girls, so for a while many girls in the class may be taller. This is normal.\n\n## What happens\n\n- The testicles and penis grow\n- Hair grows around the private parts, under the arms, then on the face, chest and legs\n- A big growth spurt, often later in puberty; shoulders broaden and muscles grow\n- The voice “cracks” and then becomes deeper\n- More sweat and body odour\n- Oily skin and pimples\n- Erections can happen on their own, without any reason\n- Wet dreams: semen comes out during sleep. This is normal, not an illness and not something to feel guilty about\n- One or both breasts may swell or feel tender for a while; this is common and usually settles on its own\n\n## Hygiene\n\n- A bath every day, washing under the arms and the private area\n- Clean underwear and socks daily\n- Washing the face gently twice a day for pimples; avoid squeezing them\n- Deodorant if he wants it\n- Shaving, when he is ready, with his own razor\n\n## Feelings\n\nHormones can bring strong emotions, irritability and a need for privacy. Boys may start to feel attraction to others. Let him know these feelings are normal, and that he can talk to you. Teach respect: how he speaks about and treats girls matters.\n\n## Harmful messages\n\nBoys may see pornography or hear myths from friends and the internet that give wrong ideas about bodies, sex and relationships. Talk about it calmly before it happens: what he might see, why it is not real, and that he can tell you if he sees something upsetting.\n\n## Urgent: testicle pain\n\nSudden, severe pain or swelling in a testicle needs a hospital immediately, day or night. It can be a twisted testicle, which must be treated within hours. Teach your son to tell you straight away and not to hide it out of embarrassment.\n\n## When to see a doctor\n\n- Signs of puberty before 9 years\n- No signs of puberty by 14 years\n- Breast swelling that is large, painful or lasts a long time\n- A lump in a testicle, or worry about the size or shape of his body","bn":"বয়ঃসন্ধি নিয়ে ছেলেরা প্রায়ই মেয়েদের চেয়ে কম তথ্য পায়, কারণ সবাই ধরে নেয় সে “নিজেই বুঝে নেবে”। বাস্তবে অনেক ছেলে এমন পরিবর্তন নিয়ে বিভ্রান্ত বা লজ্জিত থাকে, যা সে বোঝে না। বাবা, মা বা বিশ্বস্ত কোনো বড় মানুষের শান্ত একটা আলাপ অনেক বড় পার্থক্য গড়ে দেয়।\n\n## কখন শুরু হয়\n\nছেলেদের বয়ঃসন্ধি সাধারণত ৯ থেকে ১৪ বছরের মধ্যে শুরু হয়। প্রথম লক্ষণ সাধারণত অণ্ডকোষ বড় হওয়া। ছেলেরা মেয়েদের চেয়ে একটু পরে শুরু করে, তাই কিছুদিন ক্লাসের অনেক মেয়েই হয়তো বেশি লম্বা থাকবে। এটা স্বাভাবিক।\n\n## কী কী ঘটে\n\n- অণ্ডকোষ আর পুরুষাঙ্গ বড় হয়\n- গোপনাঙ্গের চারপাশে, বগলে, তারপর মুখে, বুকে আর পায়ে লোম গজায়\n- হঠাৎ অনেক লম্বা হয়ে যাওয়া — প্রায়ই বয়ঃসন্ধির শেষের দিকে; কাঁধ চওড়া হয়, পেশি বাড়ে\n- গলা “ভেঙে” যায়, তারপর ভারী হয়\n- ঘাম আর গায়ের গন্ধ বাড়ে\n- তৈলাক্ত ত্বক আর ব্রণ\n- কোনো কারণ ছাড়াই আপনা-আপনি লিঙ্গ শক্ত হতে পারে\n- স্বপ্নদোষ: ঘুমের মধ্যে বীর্য বেরিয়ে আসা। এটা স্বাভাবিক, কোনো অসুখ নয়, এ নিয়ে অপরাধবোধেরও কিছু নেই\n- এক বা দুই দিকের স্তন কিছুদিন একটু ফুলে বা ব্যথা হতে পারে; এটা খুব সাধারণ, সাধারণত নিজে থেকেই ঠিক হয়ে যায়\n\n## পরিচ্ছন্নতা\n\n- প্রতিদিন গোসল, বগল আর গোপনাঙ্গ ভালো করে ধোয়া\n- প্রতিদিন পরিষ্কার আন্ডারওয়্যার আর মোজা\n- ব্রণের জন্য দিনে দুবার আলতো করে মুখ ধোয়া; ব্রণ খোঁটা নয়\n- চাইলে ডিওডোরেন্ট\n- প্রস্তুত হলে নিজের আলাদা রেজর দিয়ে শেভ করা\n\n## অনুভূতি\n\nহরমোনের কারণে তীব্র আবেগ, খিটখিটে মেজাজ আর আড়াল চাওয়া আসতে পারে। অন্যের প্রতি আকর্ষণ বোধ শুরু হতে পারে। তাকে জানান, এসব অনুভূতি স্বাভাবিক, আর সে আপনার সঙ্গে কথা বলতে পারে। সম্মান শেখান: মেয়েদের নিয়ে সে কীভাবে কথা বলে আর কেমন আচরণ করে, তা গুরুত্বপূর্ণ।\n\n## ক্ষতিকর বার্তা\n\nবন্ধু আর ইন্টারনেট থেকে ছেলেরা পর্নোগ্রাফি দেখতে পারে বা এমন গুজব শুনতে পারে, যা শরীর, যৌনতা আর সম্পর্ক নিয়ে ভুল ধারণা দেয়। ঘটার আগেই শান্তভাবে কথা বলুন: সে কী দেখতে পারে, কেন সেটা বাস্তব নয়, আর মন খারাপ করা কিছু দেখলে যে আপনাকে বলতে পারে।\n\n## জরুরি: অণ্ডকোষে ব্যথা\n\nঅণ্ডকোষে হঠাৎ তীব্র ব্যথা বা ফোলা হলে দিন-রাত যখনই হোক, সঙ্গে সঙ্গে হাসপাতালে যান। এটা অণ্ডকোষ পেঁচিয়ে যাওয়া হতে পারে, যার চিকিৎসা কয়েক ঘণ্টার মধ্যেই করতে হয়। ছেলেকে শেখান, লজ্জায় লুকিয়ে না রেখে সঙ্গে সঙ্গে আপনাকে জানাতে।\n\n## কখন ডাক্তার দেখাবেন\n\n- ৯ বছরের আগে বয়ঃসন্ধির লক্ষণ\n- ১৪ বছরেও বয়ঃসন্ধির কোনো লক্ষণ নেই\n- স্তন অনেক বড়, ব্যথাযুক্ত, বা অনেকদিন ধরে ফোলা\n- অণ্ডকোষে চাকা, বা শরীরের আকার-গড়ন নিয়ে দুশ্চিন্তা"}'::jsonb, '{"warning_signs":{"en":["Sudden, severe pain or swelling in a testicle — go to hospital now","A lump in a testicle"],"bn":["অণ্ডকোষে হঠাৎ তীব্র ব্যথা বা ফোলা — এখনই হাসপাতালে যান","অণ্ডকোষে চাকা"]}}'::jsonb, 4, 3652, 4748, '{}'::text[], 'male', ARRAY['boys', 'puberty', 'wet dreams', 'voice change', 'body odour', 'acne']::text[], false, 'in_review'::lp_review_status, 7021),
  ('mc-early-puberty-check', 'article', 'scientific', 'shared', 'important', 'consensus', '🩺', '{"en":"Very early puberty: when to see a doctor","bn":"অনেক আগে বয়ঃসন্ধি: কখন ডাক্তার দেখাবেন"}'::jsonb, '{"en":"Signs of puberty before 8 in girls or before 9 in boys should be checked by a doctor. Early checks can find a cause and protect growth.","bn":"মেয়েদের ৮ বছরের আগে বা ছেলেদের ৯ বছরের আগে বয়ঃসন্ধির লক্ষণ দেখা দিলে ডাক্তার দেখানো উচিত। আগেভাগে পরীক্ষা করলে কারণ খুঁজে পাওয়া যায়, বৃদ্ধিও রক্ষা পায়।"}'::jsonb, '{"en":"Puberty normally starts between 8 and 13 in girls and between 9 and 14 in boys. When it starts earlier than this, doctors call it early or precocious puberty. It is not common, but it is important to check, because sometimes there is a medical cause, and because very early puberty can affect a child''s final height and emotional well-being.\n\n## Signs to look for\n\nIn girls before 8 years:\n\n- Breast buds or breast growth\n- Pubic or underarm hair\n- A fast growth spurt, much taller than classmates\n- A period or vaginal bleeding\n\nIn boys before 9 years:\n\n- Growth of the testicles or penis\n- Pubic, underarm or facial hair\n- A deepening voice\n- A fast growth spurt\n\nIn both: adult-type body odour, pimples or oily skin at a young age may be part of it, especially together with other signs.\n\n## Why it matters\n\n- In some children, especially boys, there is an underlying cause that needs treatment\n- Bones may stop growing earlier, so the child may end up shorter than expected\n- A young child with an adult body may be teased or feel very different, and needs extra support and protection\n\n## What the doctor may do\n\nYour child''s doctor will ask about when changes began, measure height and weight, and examine the body gently with a parent present. They may order an X-ray of the hand to check bone age, blood tests for hormones, or a scan. They may refer you to a children''s hormone specialist (paediatric endocrinologist). For some children, treatment can pause puberty until a more suitable age.\n\n## Tell the doctor about\n\n- Any creams, oils or medicines in the house that contain hormones, which a child could touch or swallow\n- Any head injury, brain infection or other illness in the past\n- When the parents'' own puberty began\n\n## At home\n\n- Do not try home remedies or cut out foods on your own\n- Explain changes to your child simply and kindly, at their level\n- Protect them from teasing, and stay alert to body safety\n\n## Late puberty\n\nSee a doctor too if a girl has no breast development by 13, or no period by 15, or if a boy has no growth of the testicles by 14.","bn":"স্বাভাবিকভাবে মেয়েদের বয়ঃসন্ধি শুরু হয় ৮ থেকে ১৩ বছরে, আর ছেলেদের ৯ থেকে ১৪ বছরে। এর চেয়ে আগে শুরু হলে ডাক্তাররা একে বলেন আগাম বয়ঃসন্ধি (precocious puberty)। এটা খুব সাধারণ নয়, কিন্তু পরীক্ষা করানো জরুরি — কারণ কখনো কখনো এর পেছনে কোনো রোগ থাকে, আর অনেক আগে বয়ঃসন্ধি হলে শিশুর পূর্ণবয়স্ক উচ্চতা আর মানসিক সুস্থতার ওপর প্রভাব পড়তে পারে।\n\n## যে লক্ষণগুলো খেয়াল করবেন\n\nমেয়েদের ৮ বছরের আগে:\n\n- স্তনের কুঁড়ি বা স্তনের বৃদ্ধি\n- গোপনাঙ্গে বা বগলে লোম\n- হঠাৎ দ্রুত লম্বা হওয়া, সহপাঠীদের চেয়ে অনেক বেশি\n- মাসিক বা যোনিপথে রক্তপাত\n\nছেলেদের ৯ বছরের আগে:\n\n- অণ্ডকোষ বা পুরুষাঙ্গ বড় হওয়া\n- গোপনাঙ্গে, বগলে বা মুখে লোম\n- গলা ভারী হওয়া\n- হঠাৎ দ্রুত লম্বা হওয়া\n\nদুজনের ক্ষেত্রেই: অল্প বয়সে বড়দের মতো গায়ের গন্ধ, ব্রণ বা তৈলাক্ত ত্বকও এর অংশ হতে পারে, বিশেষ করে অন্য লক্ষণের সঙ্গে থাকলে।\n\n## কেন গুরুত্বপূর্ণ\n\n- কিছু শিশুর, বিশেষ করে ছেলেদের ক্ষেত্রে, পেছনে এমন কারণ থাকতে পারে যার চিকিৎসা দরকার\n- হাড়ের বৃদ্ধি আগেভাগে থেমে যেতে পারে, ফলে শিশু প্রত্যাশার চেয়ে খাটো হতে পারে\n- ছোট শিশুর শরীর বড়দের মতো হলে সে ঠাট্টার শিকার হতে পারে বা নিজেকে খুব আলাদা ভাবতে পারে — তার বাড়তি সহায়তা আর সুরক্ষা দরকার\n\n## ডাক্তার যা করতে পারেন\n\nপরিবর্তন কবে শুরু হয়েছে ডাক্তার জিজ্ঞেস করবেন, উচ্চতা আর ওজন মাপবেন, আর মা বা বাবার উপস্থিতিতে আলতোভাবে শরীর পরীক্ষা করবেন। হাড়ের বয়স দেখতে হাতের এক্স-রে, হরমোনের রক্ত পরীক্ষা বা স্ক্যান করতে দিতে পারেন। শিশুদের হরমোন বিশেষজ্ঞের (পেডিয়াট্রিক এন্ডোক্রাইনোলজিস্ট) কাছে পাঠাতে পারেন। কিছু শিশুর ক্ষেত্রে চিকিৎসা দিয়ে উপযুক্ত বয়স পর্যন্ত বয়ঃসন্ধি থামিয়ে রাখা যায়।\n\n## ডাক্তারকে যা জানাবেন\n\n- ঘরে হরমোনযুক্ত কোনো ক্রিম, তেল বা ওষুধ আছে কি না, যা শিশু ছুঁতে বা খেয়ে ফেলতে পারে\n- আগে কখনো মাথায় আঘাত, মস্তিষ্কের সংক্রমণ বা অন্য কোনো অসুখ হয়েছিল কি না\n- মা-বাবার নিজেদের বয়ঃসন্ধি কবে শুরু হয়েছিল\n\n## ঘরে যা করবেন\n\n- নিজে থেকে ঘরোয়া চিকিৎসা করবেন না, কোনো খাবারও বাদ দেবেন না\n- সন্তানের বয়স অনুযায়ী সহজ ভাষায়, মমতা দিয়ে পরিবর্তনগুলো বুঝিয়ে বলুন\n- ঠাট্টা থেকে রক্ষা করুন, আর শরীরের নিরাপত্তার ব্যাপারে সজাগ থাকুন\n\n## দেরিতে বয়ঃসন্ধি\n\nমেয়ের ১৩ বছরেও স্তনের বৃদ্ধি না হলে বা ১৫ বছরেও মাসিক না হলে, কিংবা ছেলের ১৪ বছরেও অণ্ডকোষ বড় না হলে — তখনও ডাক্তার দেখান।"}'::jsonb, '{"seek_help":{"en":["Any sign of puberty before 8 in a girl or before 9 in a boy","Vaginal bleeding in a young girl","Headaches, vision problems or vomiting together with early puberty signs — see a doctor promptly","No signs of puberty by 13 (girls) or 14 (boys)"],"bn":["মেয়েদের ৮ বা ছেলেদের ৯ বছরের আগে বয়ঃসন্ধির যেকোনো লক্ষণ","ছোট মেয়ের যোনিপথে রক্তপাত","আগাম বয়ঃসন্ধির লক্ষণের সঙ্গে মাথাব্যথা, চোখে দেখার সমস্যা বা বমি — দেরি না করে ডাক্তার দেখান","১৩ বছরেও (মেয়ে) বা ১৪ বছরেও (ছেলে) বয়ঃসন্ধির কোনো লক্ষণ নেই"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['early puberty', 'precocious puberty', 'late puberty', 'doctor', 'hormones']::text[], false, 'in_review'::lp_review_status, 7022),
  ('mc-body-safety', 'article', 'scientific', 'shared', 'important', 'guideline', '🛡️', '{"en":"Body safety and trusted adults for older children","bn":"বড় শিশুর শরীরের নিরাপত্তা আর বিশ্বস্ত বড় মানুষ"}'::jsonb, '{"en":"Abuse is most often by someone the child knows. Clear rules, trusted adults and a home where children can tell anything are the best protection.","bn":"শিশু নির্যাতন বেশির ভাগ সময় করে কোনো চেনা মানুষ। পরিষ্কার নিয়ম, বিশ্বস্ত বড় মানুষ, আর এমন একটা ঘর যেখানে শিশু যেকোনো কিছু বলতে পারে — এটাই সবচেয়ে বড় সুরক্ষা।"}'::jsonb, '{"en":"Children aged 7 to 13 spend more time away from parents: at school, coaching, a tutor''s home, a relative''s house, the mosque or a playground, and online. Most sexual abuse is by someone the child knows and trusts, not a stranger. Talking about body safety does not frighten children when it is done calmly. It gives them words and permission to speak up.\n\n## Rules to teach\n\n- Your body belongs to you. Private parts are the parts covered by underwear or a swimsuit\n- No one should touch your private parts, ask you to touch theirs, or show you pictures of private parts\n- No one should take photos or videos of your body, or ask you to send them\n- A doctor or nurse may need to examine you, but only with a parent present and to help you\n- If anyone breaks these rules, say “No”, get away, and tell a trusted adult — even if it is someone you know or love\n\n## Safe and unsafe secrets\n\nA surprise, like a birthday present, is fine because everyone finds out soon. A secret that makes you feel worried, scared or confused, or that someone says you must never tell, is an unsafe secret. Always tell a parent about unsafe secrets.\n\n## Trusted adults\n\nHelp your child name at least three trusted adults they could go to, both inside and outside the home: perhaps a parent, a grandmother, an aunt and a teacher. Explain that if one adult does not listen, they should tell another.\n\n## Everyday precautions\n\n- Home tutors teach with the door open or in a shared room\n- Know where your child is, who they are with and how they travel\n- Be cautious of any adult who seeks a lot of time alone with your child, gives special gifts or asks for secrecy\n- Let your child refuse hugs or kisses, even from relatives\n- Use correct names for body parts so your child can explain clearly\n\n## Signs that something may be wrong\n\nSudden fear of a person or place, nightmares, bed-wetting again, pain or bleeding in the private area, sexual knowledge or behaviour beyond their age, unexplained gifts or money, or withdrawing from family and friends.\n\n## If your child tells you\n\n1. Stay calm and listen. Your reaction decides whether they tell you more.\n2. Believe them and say: “Thank you for telling me. It is not your fault. I will help.”\n3. Do not question them again and again, and do not confront the person in front of the child.\n4. Keep the child away from the person.\n5. Get medical care. Call 999 if they are in danger, and the child helpline 1098 for advice and support.\n\n## Protect the child, not the family name\n\nFamilies sometimes stay quiet to avoid shame. Silence protects the abuser, not the child. Children recover best when the adults around them believe them and act.","bn":"৭ থেকে ১৩ বছরের শিশু মা-বাবার কাছ থেকে দূরে বেশি সময় কাটায়: স্কুল, কোচিং, প্রাইভেট শিক্ষকের বাসা, আত্মীয়ের বাড়ি, মসজিদ বা খেলার মাঠ — আর অনলাইনে। বেশির ভাগ যৌন নির্যাতন করে শিশুর চেনা-বিশ্বস্ত কেউ, অচেনা কেউ নয়। শান্তভাবে বললে শরীরের নিরাপত্তা নিয়ে কথা শিশুকে ভয় দেখায় না। বরং তাকে কথা বলার ভাষা আর অনুমতি দেয়।\n\n## যে নিয়মগুলো শেখাবেন\n\n- তোমার শরীর তোমার। গোপনাঙ্গ হলো শরীরের সেই অংশ, যা আন্ডারওয়্যার বা সাঁতারের পোশাকে ঢাকা থাকে\n- কেউ তোমার গোপনাঙ্গে হাত দেবে না, তার গোপনাঙ্গে হাত দিতে বলবে না, বা গোপনাঙ্গের ছবি দেখাবে না\n- কেউ তোমার শরীরের ছবি বা ভিডিও তুলবে না, বা পাঠাতে বলবে না\n- ডাক্তার বা নার্সের পরীক্ষা করার দরকার হতে পারে — কিন্তু শুধু মা বা বাবার উপস্থিতিতে, আর তোমার ভালোর জন্য\n- কেউ এই নিয়ম ভাঙলে “না” বলো, সরে যাও, আর বিশ্বস্ত কোনো বড়কে বলো — সে তোমার চেনা বা প্রিয় কেউ হলেও\n\n## নিরাপদ আর অনিরাপদ গোপন কথা\n\nজন্মদিনের উপহারের মতো চমক ঠিক আছে, কারণ কিছুদিন পরেই সবাই জানবে। যে গোপন কথা তোমাকে দুশ্চিন্তায়, ভয়ে বা বিভ্রান্তিতে ফেলে, বা যা কেউ বলে কখনো কাউকে বলা যাবে না — সেটা অনিরাপদ গোপন কথা। অনিরাপদ গোপন কথা সবসময় মা-বাবাকে বলবে।\n\n## বিশ্বস্ত বড় মানুষ\n\nঘরে আর ঘরের বাইরে অন্তত তিনজন বিশ্বস্ত বড় মানুষের নাম ঠিক করতে সন্তানকে সাহায্য করুন — যেমন মা বা বাবা, দাদি বা নানি, খালা বা ফুপু, আর একজন শিক্ষক। বুঝিয়ে বলুন, একজন না শুনলে আরেকজনকে বলতে হবে।\n\n## রোজকার সাবধানতা\n\n- বাসায় প্রাইভেট শিক্ষক পড়াবেন দরজা খোলা রেখে বা সবার ব্যবহারের ঘরে\n- সন্তান কোথায়, কার সঙ্গে আর কীভাবে যাতায়াত করছে, জেনে রাখুন\n- কোনো বড় মানুষ যদি সন্তানের সঙ্গে একা অনেক সময় কাটাতে চায়, বিশেষ উপহার দেয় বা গোপন রাখতে বলে — সতর্ক থাকুন\n- আত্মীয় হলেও জড়িয়ে ধরা বা চুমু খাওয়ায় সন্তান না বলতে পারবে\n- শরীরের অঙ্গের সঠিক নাম ব্যবহার করুন, যাতে সন্তান পরিষ্কার করে বোঝাতে পারে\n\n## কিছু ভুল হচ্ছে, এমন লক্ষণ\n\nহঠাৎ কোনো মানুষ বা জায়গাকে ভয় পাওয়া, দুঃস্বপ্ন, আবার বিছানা ভেজানো, গোপনাঙ্গে ব্যথা বা রক্ত, বয়সের তুলনায় যৌন বিষয়ে বেশি জানা বা সেরকম আচরণ, অজানা উপহার বা টাকা, অথবা পরিবার আর বন্ধুদের থেকে গুটিয়ে যাওয়া।\n\n## সন্তান যদি আপনাকে বলে\n\n1. শান্ত থাকুন, শুনুন। আপনার প্রতিক্রিয়াই ঠিক করবে সে আরও বলবে কি না।\n2. বিশ্বাস করুন, আর বলুন: “আমাকে বলার জন্য ধন্যবাদ। এতে তোমার কোনো দোষ নেই। আমি সাহায্য করব।”\n3. বারবার প্রশ্ন করবেন না, আর শিশুর সামনে ওই মানুষটির মুখোমুখি হবেন না।\n4. শিশুকে ওই মানুষটির কাছ থেকে দূরে রাখুন।\n5. চিকিৎসা নিন। শিশু বিপদে থাকলে ৯৯৯-এ, আর পরামর্শ ও সহায়তার জন্য শিশু হেল্পলাইন ১০৯৮-এ ফোন করুন।\n\n## পরিবারের সম্মান নয়, শিশুকে রক্ষা করুন\n\nলজ্জার ভয়ে পরিবার অনেক সময় চুপ থাকে। এই নীরবতা নির্যাতনকারীকে রক্ষা করে, শিশুকে নয়। চারপাশের বড়রা যখন বিশ্বাস করেন আর ব্যবস্থা নেন, তখনই শিশু সবচেয়ে ভালোভাবে সেরে ওঠে।"}'::jsonb, '{"seek_help":{"en":["Your child is in danger now — call 999","Your child tells you about abuse, or you strongly suspect it — get medical care and call 1098 for support","Pain, bleeding or injury in the private area"],"bn":["সন্তান এখনই বিপদে — ৯৯৯-এ ফোন করুন","সন্তান নির্যাতনের কথা বলেছে, বা আপনার জোরালো সন্দেহ — চিকিৎসা নিন আর সহায়তার জন্য ১০৯৮-এ ফোন করুন","গোপনাঙ্গে ব্যথা, রক্ত বা আঘাত"]}}'::jsonb, 4, 2557, 4748, '{}'::text[], 'any', ARRAY['body safety', 'abuse prevention', 'trusted adults', 'secrets', 'private parts', 'consent']::text[], false, 'in_review'::lp_review_status, 7023),
  ('mc-father-child-time', 'article', 'general', 'father', 'educational', 'research', '👨‍👧‍👦', '{"en":"Father–child time","bn":"বাবা আর সন্তানের একান্ত সময়"}'::jsonb, '{"en":"Children with involved fathers tend to do better at school and feel more secure. Small, regular time together matters more than big outings.","bn":"যে শিশুর বাবা তার জীবনে সক্রিয়ভাবে জড়িত, সে সাধারণত পড়াশোনায় ভালো করে আর বেশি নিরাপদ বোধ করে। বড় বেড়ানোর চেয়ে ছোট ছোট নিয়মিত সময়ই বেশি গুরুত্বপূর্ণ।"}'::jsonb, '{"en":"In many Bangladeshi families the father earns and the mother does the daily care. Fathers often leave early, come home late, and become the person children fear when they misbehave. But children need their fathers as warm, involved parents too. Research from many countries links involved fathering with better learning, fewer behaviour problems and stronger self-esteem in children.\n\n## Small time, every day\n\nYou do not need hours. Ten or fifteen minutes of full attention each day counts:\n\n- Ask about their day while you eat or walk together\n- Check the homework diary and sign it\n- Read with them or listen to them read before bed\n- Put your phone away while you talk\n\n## One-to-one time each week\n\nSet aside a regular time for each child alone, for example on a weekend afternoon. Let the child choose what to do:\n\n- A walk to the tea stall or the market\n- Cricket, football or badminton\n- Fixing a bicycle or a broken toy\n- Cooking a simple meal\n- A visit to a library, museum or park\n\n## Daughters need their fathers too\n\nFathers sometimes step back from daughters as they grow. Keep the closeness. A father who listens to his daughter, believes in her abilities and treats her mother with respect shapes how she expects to be treated all her life.\n\n## Sons learn how to be men from you\n\nBoys watch how their father handles anger, treats women and shares housework. Be the example you want them to follow. Talk to your son about puberty, feelings and respect, even if no one talked to you.\n\n## Discipline without fear\n\nAvoid being the parent who is called in only to punish. Hitting and harsh words damage trust. Set limits calmly, and share discipline with the mother.\n\n## Fathers who work away\n\nMany Bangladeshi fathers work in another city or abroad. You can still be close:\n\n- Regular video or phone calls at a fixed time\n- Ask specific questions: “Who did you play with today?”\n- Help with homework over video\n- Send voice messages, stories or drawings\n- Make the most of time at home, with less visiting and more being together\n\n## Single, separated and step-fathers\n\nWhatever the family situation, a steady, caring father figure matters. Grandfathers, uncles and older brothers can also fill this role.","bn":"বাংলাদেশের অনেক পরিবারে বাবা আয় করেন, আর রোজকার দেখাশোনা করেন মা। বাবা প্রায়ই সকালে বেরিয়ে যান, ফেরেন রাতে, আর দুষ্টুমি করলে শিশুরা ভয় পায় তাঁকেই। কিন্তু উষ্ণ, জড়িত একজন অভিভাবক হিসেবে শিশুর বাবাকেও দরকার। নানা দেশের গবেষণা বলছে, বাবার সক্রিয় অংশগ্রহণ শিশুর ভালো শেখা, কম আচরণগত সমস্যা আর মজবুত আত্মসম্মানবোধের সঙ্গে জড়িত।\n\n## অল্প সময়, প্রতিদিন\n\nঘণ্টার পর ঘণ্টা লাগবে না। প্রতিদিন দশ-পনেরো মিনিট পূর্ণ মনোযোগই যথেষ্ট:\n\n- খেতে খেতে বা একসঙ্গে হাঁটতে হাঁটতে তার দিনের গল্প শুনুন\n- হোমওয়ার্কের ডায়েরি দেখুন, সই করুন\n- ঘুমের আগে একসঙ্গে পড়ুন, বা সে পড়ছে তা শুনুন\n- কথা বলার সময় ফোন সরিয়ে রাখুন\n\n## সপ্তাহে একান্ত সময়\n\nপ্রতিটি সন্তানের জন্য আলাদা করে নিয়মিত একটা সময় রাখুন, যেমন ছুটির দিনের বিকেল। কী করবেন, সন্তানকেই বেছে নিতে দিন:\n\n- চায়ের দোকান বা বাজার পর্যন্ত হাঁটা\n- ক্রিকেট, ফুটবল বা ব্যাডমিন্টন\n- সাইকেল বা ভাঙা খেলনা সারানো\n- সহজ কিছু রান্না\n- লাইব্রেরি, জাদুঘর বা পার্কে যাওয়া\n\n## মেয়েরও বাবাকে দরকার\n\nমেয়ে বড় হলে অনেক বাবা একটু দূরে সরে যান। কাছাকাছি থাকুন। যে বাবা মেয়ের কথা শোনেন, তার সামর্থ্যে বিশ্বাস রাখেন আর তার মাকে সম্মান করেন — তিনিই ঠিক করে দেন, সারাজীবন সে অন্যের কাছ থেকে কেমন আচরণ আশা করবে।\n\n## ছেলে আপনার কাছ থেকেই পুরুষ হতে শেখে\n\nবাবা কীভাবে রাগ সামলান, নারীর সঙ্গে কেমন আচরণ করেন, ঘরের কাজে হাত লাগান কি না — ছেলে সব দেখে। যেমন হতে চান, নিজে তেমন উদাহরণ হোন। কেউ আপনার সঙ্গে না বললেও আপনি ছেলের সঙ্গে বয়ঃসন্ধি, অনুভূতি আর সম্মান নিয়ে কথা বলুন।\n\n## ভয় ছাড়া শাসন\n\nশুধু শাস্তি দেওয়ার জন্য ডাক পড়ে — এমন অভিভাবক হবেন না। মারধর আর কড়া কথা বিশ্বাস নষ্ট করে। শান্তভাবে সীমা ঠিক করুন, শাসনের দায়িত্ব মায়ের সঙ্গে ভাগ করে নিন।\n\n## দূরে কাজ করা বাবা\n\nবাংলাদেশের অনেক বাবা অন্য শহরে বা বিদেশে কাজ করেন। তবু কাছে থাকা যায়:\n\n- নির্দিষ্ট সময়ে নিয়মিত ভিডিও বা ফোন কল\n- নির্দিষ্ট প্রশ্ন করুন: “আজ কার সঙ্গে খেললে?”\n- ভিডিও কলে হোমওয়ার্কে সাহায্য করুন\n- ভয়েস মেসেজ, গল্প বা আঁকা ছবি পাঠান\n- বাড়িতে এলে সময়টা কাজে লাগান — বেড়ানো কম, একসঙ্গে থাকা বেশি\n\n## একক, আলাদা থাকা বা সৎবাবা\n\nপরিবারের অবস্থা যেমনই হোক, স্থির আর যত্নশীল একজন বাবার মতো মানুষ গুরুত্বপূর্ণ। দাদা-নানা, চাচা-মামা বা বড় ভাইও এই ভূমিকা নিতে পারেন।"}'::jsonb, '{}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['father', 'dad', 'one to one time', 'bonding', 'migrant father']::text[], false, 'in_review'::lp_review_status, 7024),
  ('mc-sibling-rivalry', 'article', 'scientific', 'shared', 'educational', 'consensus', '👫', '{"en":"Sibling rivalry and fairness","bn":"ভাইবোনের ঝগড়া আর ন্যায্যতা"}'::jsonb, '{"en":"Brothers and sisters fight; it is how they practise sharing and solving problems. Fairness means giving each child what they need, not always the same thing.","bn":"ভাইবোন ঝগড়া করবেই — এভাবেই তারা ভাগাভাগি আর সমস্যা মেটানো শেখে। ন্যায্যতা মানে সবসময় একই জিনিস দেওয়া নয়, প্রত্যেককে তার যা দরকার তা দেওয়া।"}'::jsonb, '{"en":"Arguments over the TV remote, the front seat or who got the bigger piece are part of family life. Sibling conflict is normal, and handled well it teaches children to negotiate, compromise and forgive. What parents can do is reduce the causes, coach rather than judge, and keep everyone safe.\n\n## Why siblings fight\n\n- Competing for parents'' attention and love\n- Different ages and needs: an older child wants privacy, a younger one wants to play\n- Feeling that rules or treats are unfair\n- Being tired, hungry or stressed\n- Copying how adults argue\n\n## Fair is not always equal\n\nA 12-year-old may stay up later than an 8-year-old; that is fair because their needs differ. Explain this: “Everyone gets what they need. When you are 12, you will stay up later too.” What children most need to feel is that they are loved equally.\n\n## Avoid comparisons and labels\n\n“Why can''t you be like your sister?” breeds resentment. So do labels like “the clever one” and “the naughty one”. Praise each child for their own efforts.\n\n## Boys and girls treated alike\n\nIn some homes sons get the bigger share of food, more freedom or fewer chores than daughters. Children notice, and it hurts. Treat sons and daughters with the same respect and give them the same responsibilities.\n\n## The eldest is still a child\n\nAn older child may be expected to always give in, look after the younger ones or set an example. Some helping is good, but the eldest also needs to be a child, have their own things and get your time.\n\n## When they fight\n\n- Stay calm; do not shout or hit, which teaches the opposite\n- For small squabbles, give them a chance to sort it out\n- If it gets heated, separate them to calm down first\n- Then help them solve it: each says what happened without interruption, and together they think of a fair solution\n- Avoid deciding who started it; focus on what to do now\n\n## Clear family rules\n\nNo hitting, no name-calling, and no breaking each other''s things. Agree on these rules together and apply them to everyone.\n\n## One-to-one time\n\nA little special time alone with each child, even 10 minutes, reduces competition for attention more than anything else.\n\n## When to worry\n\nGet help if one child is repeatedly hurting, threatening or humiliating another, if there is any sexual behaviour between siblings, or if one child is very frightened of another.","bn":"টিভির রিমোট, সামনের সিট বা কে বড় টুকরো পেল — এসব নিয়ে ঝগড়া পরিবারের জীবনেরই অংশ। ভাইবোনের ঝগড়া স্বাভাবিক, আর ঠিকমতো সামলালে এটাই শেখায় আলোচনা, ছাড় দেওয়া আর ক্ষমা করা। মা-বাবা যা করতে পারেন: কারণগুলো কমানো, বিচারক না হয়ে পথ দেখানো, আর সবাইকে নিরাপদ রাখা।\n\n## ভাইবোন কেন ঝগড়া করে\n\n- মা-বাবার মনোযোগ আর ভালোবাসা পাওয়ার প্রতিযোগিতা\n- আলাদা বয়স, আলাদা চাহিদা: বড়টা একা থাকতে চায়, ছোটটা খেলতে চায়\n- নিয়ম বা উপহার অন্যায্য মনে হওয়া\n- ক্লান্তি, ক্ষুধা বা চাপ\n- বড়রা কীভাবে ঝগড়া করেন, তা নকল করা\n\n## ন্যায্য মানে সবসময় সমান নয়\n\n১২ বছরের সন্তান ৮ বছরের সন্তানের চেয়ে দেরিতে ঘুমাতে পারে — এটা ন্যায্য, কারণ দুজনের চাহিদা আলাদা। বুঝিয়ে বলুন: “যার যা দরকার, সে তা-ই পায়। তুমি ১২ বছরের হলে তুমিও দেরিতে ঘুমাবে।” শিশুর সবচেয়ে বেশি দরকার এটা অনুভব করা যে সবাইকে সমান ভালোবাসা হয়।\n\n## তুলনা আর তকমা নয়\n\n“তুমি তোমার বোনের মতো হতে পারো না কেন?” — এ কথা মনে ক্ষোভ জমায়। “বুদ্ধিমানটা” আর “দুষ্টুটা” — এমন তকমাও তাই। প্রত্যেকের নিজের চেষ্টার প্রশংসা করুন।\n\n## ছেলে-মেয়ের সমান আচরণ\n\nকিছু ঘরে মেয়ের চেয়ে ছেলে বেশি খাবার, বেশি স্বাধীনতা পায়, ঘরের কাজ কম করে। শিশুরা এটা খেয়াল করে, আর কষ্ট পায়। ছেলে আর মেয়েকে সমান সম্মান দিন, সমান দায়িত্ব দিন।\n\n## বড়টাও তো শিশু\n\nবড় সন্তানের কাছে প্রায়ই আশা করা হয় সে সবসময় ছাড় দেবে, ছোটদের দেখবে, আদর্শ হবে। একটু সাহায্য ভালো, কিন্তু বড়টারও শিশু থাকার, নিজের জিনিস রাখার আর আপনার সময় পাওয়ার অধিকার আছে।\n\n## যখন ঝগড়া বাধে\n\n- শান্ত থাকুন; চিৎকার বা মারধর উল্টো শিক্ষা দেয়\n- ছোটখাটো খুনসুটিতে ওদের নিজেদের মিটিয়ে নেওয়ার সুযোগ দিন\n- উত্তেজনা বাড়লে আগে আলাদা করে শান্ত হতে দিন\n- তারপর সমাধানে সাহায্য করুন: একজনের কথার মাঝে আরেকজন বাধা দেবে না, তারপর দুজনে মিলে একটা ন্যায্য সমাধান ভাববে\n- কে শুরু করেছে তা বিচার না করে, এখন কী করা যায় সেদিকে মন দিন\n\n## পরিবারের পরিষ্কার নিয়ম\n\nমারামারি নয়, বাজে নামে ডাকা নয়, একে অপরের জিনিস ভাঙা নয়। নিয়মগুলো সবাই মিলে ঠিক করুন, আর সবার জন্য একইভাবে প্রয়োগ করুন।\n\n## প্রত্যেকের সঙ্গে একান্ত সময়\n\nপ্রতিটি সন্তানের সঙ্গে আলাদা করে একটু বিশেষ সময় — দশ মিনিট হলেও — মনোযোগ পাওয়ার প্রতিযোগিতা যেকোনো কিছুর চেয়ে বেশি কমায়।\n\n## কখন চিন্তা করবেন\n\nএক সন্তান যদি বারবার আরেকজনকে আঘাত, হুমকি বা অপমান করে, ভাইবোনের মধ্যে কোনো যৌন আচরণ দেখা যায়, বা একজন আরেকজনকে খুব ভয় পায় — সাহায্য নিন।"}'::jsonb, '{}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['siblings', 'sibling rivalry', 'fairness', 'fighting', 'jealousy', 'brothers and sisters']::text[], false, 'in_review'::lp_review_status, 7025),
  ('mc-checklist-digital-rules', 'checklist', 'general', 'family', 'routine', 'consensus', '📋', '{"en":"Family digital rules agreement","bn":"পরিবারের ডিজিটাল নিয়মের চুক্তি"}'::jsonb, '{"en":"Sit down together and agree on screen rules everyone follows — parents included. Write them down, sign them and review them every few months.","bn":"সবাই মিলে বসে এমন স্ক্রিন-নিয়ম ঠিক করুন, যা মা-বাবাসহ সবাই মানবে। লিখে ফেলুন, সই করুন, আর কয়েক মাস পরপর আবার দেখুন।"}'::jsonb, '{"en":"Children follow rules better when they help make them. Use this list at a family meeting. Pick the rules that suit your home, write them on paper in your child''s words, and have everyone sign — parents too. Stick it on the fridge or the wall near where devices charge. Review it every three to six months, or when your child gets a new device or app.","bn":"যে নিয়ম বানাতে শিশু নিজে অংশ নেয়, সেটা সে বেশি মানে। পারিবারিক বৈঠকে এই তালিকা ব্যবহার করুন। আপনার ঘরের সঙ্গে মানায় এমন নিয়মগুলো বেছে নিন, সন্তানের নিজের ভাষায় কাগজে লিখুন, আর সবাই সই করুন — মা-বাবাও। ফ্রিজে বা যেখানে ডিভাইস চার্জ হয় তার পাশের দেয়ালে লাগিয়ে দিন। তিন থেকে ছয় মাস পরপর, বা সন্তান নতুন ডিভাইস বা অ্যাপ পেলে, আবার দেখুন।"}'::jsonb, '{"items":{"en":["Screens off at meals — for everyone, parents included","Homework and chores come before games and videos","Agreed daily screen time for fun on school days and on holidays","No screens in the hour before bed","All phones and tablets charge outside bedrooms at night","Ask a parent before downloading any app or game, and check its age rating","No social media accounts before the platform''s minimum age (13 for most)","Parents know the passwords and may look at devices; we explain why","Never share full name, address, school, location, photos or passwords online","Never share an OTP or PIN with anyone","No chatting with or meeting people we have not met in real life","Be kind online: no mean comments, no sharing others'' photos without asking","If anything online feels wrong or scary, tell a parent — you will not be punished for telling","At least one screen-free time each week for the whole family","What happens if a rule is broken, agreed in advance","Date to review these rules together"],"bn":["খাওয়ার সময় স্ক্রিন বন্ধ — সবার জন্য, মা-বাবাসহ","গেম আর ভিডিওর আগে হোমওয়ার্ক আর ঘরের কাজ","স্কুলের দিন আর ছুটির দিনে বিনোদনের স্ক্রিন টাইম কতক্ষণ — ঠিক করা আছে","ঘুমের আগের এক ঘণ্টা কোনো স্ক্রিন নয়","রাতে সব ফোন আর ট্যাব শোবার ঘরের বাইরে চার্জ হবে","যেকোনো অ্যাপ বা গেম নামানোর আগে মা-বাবাকে জিজ্ঞেস করা আর বয়সের রেটিং দেখা","প্ল্যাটফর্মের ন্যূনতম বয়সের আগে সোশ্যাল মিডিয়া অ্যাকাউন্ট নয় (বেশির ভাগের ক্ষেত্রে ১৩)","মা-বাবা পাসওয়ার্ড জানবেন আর ডিভাইস দেখতে পারবেন; কেন, তা আমরা বুঝিয়ে বলব","অনলাইনে কখনো পুরো নাম, ঠিকানা, স্কুল, লোকেশন, ছবি বা পাসওয়ার্ড দেওয়া নয়","ওটিপি বা পিন কখনো কাউকে বলা নয়","বাস্তবে দেখা হয়নি এমন কারও সঙ্গে চ্যাট বা দেখা করা নয়","অনলাইনে ভদ্র থাকা: বাজে মন্তব্য নয়, অনুমতি ছাড়া অন্যের ছবি শেয়ার নয়","অনলাইনে কিছু খারাপ বা ভয়ের লাগলে মা-বাবাকে বলা — বলার জন্য শাস্তি হবে না","প্রতি সপ্তাহে পুরো পরিবারের জন্য অন্তত একটা স্ক্রিনমুক্ত সময়","নিয়ম ভাঙলে কী হবে, তা আগে থেকেই ঠিক করা","নিয়মগুলো আবার একসঙ্গে দেখার তারিখ"]}}'::jsonb, 2, 2557, 4748, '{}'::text[], 'any', ARRAY['family media plan', 'digital rules', 'screen rules', 'agreement', 'phone contract']::text[], false, 'in_review'::lp_review_status, 7026),
  ('mc-activity-budget-game', 'activity', 'general', 'family', 'educational', 'consensus', '🛒', '{"en":"Family budget game","bn":"পরিবারের বাজেট খেলা"}'::jsonb, '{"en":"Give your child a pretend (or real) budget to plan a week''s shopping or a family outing. Maths, planning and real-life money lessons in one game.","bn":"এক সপ্তাহের বাজার বা পরিবারের একটা বেড়ানোর পরিকল্পনার জন্য সন্তানকে একটা কাল্পনিক (বা সত্যিকারের) বাজেট দিন। অঙ্ক, পরিকল্পনা আর টাকার বাস্তব শিক্ষা — এক খেলাতেই।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Children rarely see how a family''s money is planned. Planning a small budget shows them that choices have trade-offs, builds maths skills and helps them understand why parents sometimes say no.","bn":"পরিবারের টাকা কীভাবে পরিকল্পনা করা হয়, শিশু তা খুব কমই দেখে। ছোট একটা বাজেট পরিকল্পনা করলে সে বোঝে — একটা নিলে আরেকটা ছাড়তে হয়। অঙ্কের দক্ষতা বাড়ে, আর মা-বাবা কেন মাঝে মাঝে না বলেন, সেটাও বোঝে।"},"items":{"en":["Paper and pencil, or a notebook","A recent shopping list or receipts, or a price list from the local shop","Play money or real notes and coins (optional)","A calculator for older children"],"bn":["কাগজ-পেনসিল বা একটা খাতা","সাম্প্রতিক বাজারের তালিকা বা রসিদ, বা পাড়ার দোকানের দামের তালিকা","খেলনা টাকা বা সত্যিকারের নোট-পয়সা (চাইলে)","বড় শিশুদের জন্য ক্যালকুলেটর"]},"steps":{"en":["Choose the challenge: a week of tiffin, ingredients for one family meal, or a picnic","Give a fixed amount and write it at the top of the page","Together, list what is needed and find or estimate the prices","Your child adds it up and checks whether it fits the budget","If it is over, they decide what to swap or drop — talk about needs and wants","For older children, add a twist: a price goes up, or an unexpected cost appears","If you can, go to the shop together and let them buy the items with the budget","Afterwards, talk about what went well and what they would change"],"bn":["চ্যালেঞ্জ বেছে নিন: এক সপ্তাহের টিফিন, পরিবারের এক বেলার খাবারের বাজার, বা একটা পিকনিক","নির্দিষ্ট একটা অঙ্ক দিন, পাতার ওপরে লিখে রাখুন","একসঙ্গে কী কী লাগবে তার তালিকা করুন, দাম খুঁজে বের করুন বা আন্দাজ করুন","সন্তান যোগ করে দেখবে বাজেটের মধ্যে হচ্ছে কি না","বেশি হলে কোনটা বদলাবে বা বাদ দেবে, সে-ই ঠিক করবে — দরকার আর শখের পার্থক্য নিয়ে কথা বলুন","বড় শিশুদের জন্য একটু মোড় যোগ করুন: কোনো জিনিসের দাম বেড়ে গেল, বা হঠাৎ একটা খরচ এল","সম্ভব হলে একসঙ্গে দোকানে যান, বাজেটের টাকায় তাকেই জিনিসগুলো কিনতে দিন","শেষে কী ভালো হলো আর কী বদলাতে চায়, তা নিয়ে কথা বলুন"]}}'::jsonb, 2, 2557, 4748, '{}'::text[], 'any', ARRAY['budget', 'money game', 'maths', 'shopping', 'family activity']::text[], false, 'in_review'::lp_review_status, 7027),
  ('mc-activity-family-meeting', 'activity', 'general', 'family', 'educational', 'consensus', '🗓️', '{"en":"Weekly family meeting","bn":"সাপ্তাহিক পারিবারিক বৈঠক"}'::jsonb, '{"en":"Twenty minutes once a week where everyone gets a turn to talk, plan the week and solve problems together.","bn":"সপ্তাহে একবার বিশ মিনিট — যেখানে সবাই কথা বলার সুযোগ পায়, সপ্তাহের পরিকল্পনা হয়, আর সবাই মিলে সমস্যার সমাধান খোঁজে।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"A regular family meeting gives children a voice, teaches them to listen and take turns, and solves small problems before they become big fights. It also gives busy families a time to plan together.","bn":"নিয়মিত পারিবারিক বৈঠক শিশুকে মত দেওয়ার সুযোগ দেয়, শোনা আর পালা করে কথা বলা শেখায়, আর ছোট সমস্যা বড় ঝগড়ায় পরিণত হওয়ার আগেই মিটিয়ে ফেলে। ব্যস্ত পরিবার একসঙ্গে পরিকল্পনা করার সময়ও পায়।"},"items":{"en":["A regular time, for example a weekend evening after a meal","A notebook for the family''s decisions","Something small to share — tea, fruit or a snack"],"bn":["নিয়মিত একটা সময় — যেমন ছুটির দিনে রাতের খাবারের পর","পরিবারের সিদ্ধান্ত লিখে রাখার জন্য একটা খাতা","ভাগ করে খাওয়ার মতো ছোট কিছু — চা, ফল বা নাশতা"]},"steps":{"en":["Sit together with TV and phones off","Start with appreciation: each person says one good thing someone in the family did this week","Look at the week ahead: exams, visits, who picks up whom","Each person may raise one problem; everyone suggests solutions and you agree on one to try","Rotate the jobs of leader and note-taker, so children get a turn","Plan one fun thing to do together this week","Keep it short — about 20 minutes — and end on a positive note","Next week, start by checking how last week''s solution worked"],"bn":["টিভি আর ফোন বন্ধ করে সবাই একসঙ্গে বসুন","প্রশংসা দিয়ে শুরু করুন: এ সপ্তাহে পরিবারের কেউ একটা ভালো কাজ করেছে — প্রত্যেকে একটা করে বলবে","সামনের সপ্তাহটা দেখুন: পরীক্ষা, বেড়াতে যাওয়া, কে কাকে আনবে","প্রত্যেকে একটা করে সমস্যার কথা তুলতে পারবে; সবাই সমাধান বলবে, আর একটা চেষ্টা করে দেখার ব্যাপারে একমত হবেন","সভাপতি আর লেখকের দায়িত্ব পালা করে দিন, যাতে শিশুরাও সুযোগ পায়","এ সপ্তাহে একসঙ্গে মজার একটা কিছু করার পরিকল্পনা করুন","ছোট রাখুন — বিশ মিনিটের মতো — আর ভালো কিছু দিয়ে শেষ করুন","পরের সপ্তাহে শুরুতেই দেখুন, আগের সপ্তাহের সমাধান কেমন কাজ করল"]}}'::jsonb, 2, 2557, 4748, '{}'::text[], 'any', ARRAY['family meeting', 'communication', 'planning', 'rules', 'weekly']::text[], false, 'in_review'::lp_review_status, 7028),
  ('mc-activity-cook-together', 'activity', 'general', 'family', 'educational', 'consensus', '🍳', '{"en":"Cook-a-meal-together day","bn":"একসঙ্গে রান্নার দিন"}'::jsonb, '{"en":"Once a week or once a month, your child helps plan and cook a family meal — with an adult beside them at the stove.","bn":"সপ্তাহে বা মাসে একবার সন্তান পরিবারের এক বেলার খাবারের পরিকল্পনা আর রান্নায় হাত লাগাবে — চুলার পাশে থাকবেন একজন বড় মানুষ।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Children who help cook are more willing to eat vegetables and try new foods. Cooking teaches measuring, following steps, hygiene and teamwork, and it is a life skill every boy and girl needs.","bn":"যে শিশু রান্নায় সাহায্য করে, সে সবজি খেতে আর নতুন খাবার চেখে দেখতে বেশি আগ্রহী হয়। রান্না শেখায় মাপজোখ, ধাপে ধাপে কাজ করা, পরিচ্ছন্নতা আর দলগত কাজ — আর এটা প্রতিটি ছেলে-মেয়ের দরকারি জীবন দক্ষতা।"},"items":{"en":["A simple recipe, for example khichuri, egg curry, dal, vegetable bhaji or fruit salad","Ingredients, with at least one vegetable","A child-safe knife or a peeler, and a chopping board","Soap and water for handwashing","An apron or old clothes"],"bn":["সহজ একটা রেসিপি — যেমন খিচুড়ি, ডিমের তরকারি, ডাল, সবজি ভাজি বা ফলের সালাদ","উপকরণ, অন্তত একটা সবজিসহ","শিশুর জন্য নিরাপদ ছুরি বা খোসা ছাড়ানোর যন্ত্র, আর কাটার বোর্ড","হাত ধোয়ার জন্য সাবান-পানি","অ্যাপ্রন বা পুরোনো জামা"]},"steps":{"en":["Let your child choose the dish from two or three healthy options","Make a shopping list together, and buy the ingredients if you can","Everyone washes hands with soap before starting","Give age-suitable jobs: washing vegetables, measuring rice and dal, peeling, mixing, setting the table","Older children can cut with a knife and stir at the stove, with an adult right beside them","Keep pot handles turned inward, and keep loose clothes and hair away from the flame","Serve the meal and let the cook be thanked by the whole family","Clean up together"],"bn":["দু-তিনটা স্বাস্থ্যকর পদ থেকে সন্তানকেই একটা বেছে নিতে দিন","একসঙ্গে বাজারের তালিকা করুন, সম্ভব হলে একসঙ্গে কিনে আনুন","শুরুর আগে সবাই সাবান দিয়ে হাত ধোবেন","বয়স অনুযায়ী কাজ দিন: সবজি ধোয়া, চাল-ডাল মাপা, খোসা ছাড়ানো, মেশানো, টেবিল সাজানো","বড় শিশুরা ছুরি দিয়ে কাটতে আর চুলায় নাড়তে পারে — একজন বড় মানুষ ঠিক পাশে থাকবেন","পাতিলের হাতল ভেতরের দিকে ঘুরিয়ে রাখুন, ঢিলা কাপড় আর চুল আগুন থেকে দূরে রাখুন","খাবার পরিবেশন করুন, আর পুরো পরিবার রাঁধুনিকে ধন্যবাদ দিক","সবাই মিলে পরিষ্কার করুন"]}}'::jsonb, 2, 2557, 4748, '{}'::text[], 'any', ARRAY['cooking', 'kitchen', 'healthy food', 'life skills', 'family activity']::text[], false, 'in_review'::lp_review_status, 7029),
  ('mc-activity-screen-free-hobby', 'activity', 'general', 'family', 'educational', 'consensus', '🎨', '{"en":"Screen-free hobby challenge","bn":"স্ক্রিন ছাড়া শখের চ্যালেঞ্জ"}'::jsonb, '{"en":"For two or four weeks, each family member picks a hobby without screens and practises it a few times a week. At the end, everyone shows what they made or learned.","bn":"দুই বা চার সপ্তাহ ধরে পরিবারের প্রত্যেকে স্ক্রিন ছাড়া একটা শখ বেছে নেবে, সপ্তাহে কয়েকবার চর্চা করবে। শেষে সবাই দেখাবে কী বানাল বা শিখল।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Hobbies build patience, creativity and confidence, and they fill time that would otherwise go to screens. A family challenge makes it fun rather than a punishment.","bn":"শখ ধৈর্য, সৃজনশীলতা আর আত্মবিশ্বাস বাড়ায়, আর যে সময়টা স্ক্রিনে যেত সেটা ভরিয়ে তোলে। পারিবারিক চ্যালেঞ্জ হিসেবে করলে এটা শাস্তি নয়, মজা মনে হয়।"},"items":{"en":["A chart on the wall to tick off practice sessions","Simple materials for the chosen hobbies, such as paper, colours, seeds, a ball, thread, a notebook","A date for the show-and-tell at the end"],"bn":["চর্চার দিন টিক দেওয়ার জন্য দেয়ালে একটা চার্ট","বেছে নেওয়া শখের সহজ উপকরণ — কাগজ, রং, বীজ, বল, সুতা, খাতা","শেষে সবাইকে দেখানোর একটা তারিখ"]},"steps":{"en":["Each person, parents too, picks one hobby: drawing, gardening on the balcony, paper crafts, sewing, calligraphy, a musical instrument, chess, carrom, cooking, writing stories or learning a new sport","Agree how often to practise, for example three times a week for 20–30 minutes","Put the chart on the wall and tick each session","Practise side by side when you can; it feels less lonely","If someone gets bored, help them find a new small goal rather than quitting","At the end, hold a family show-and-tell; everyone shows what they made or learned","Celebrate effort, not perfection, and decide whether to keep going"],"bn":["মা-বাবাসহ প্রত্যেকে একটা শখ বেছে নেবে: আঁকা, বারান্দায় বাগান, কাগজের কারুকাজ, সেলাই, হাতের সুন্দর লেখা, কোনো বাদ্যযন্ত্র, দাবা, ক্যারম, রান্না, গল্প লেখা বা নতুন কোনো খেলা","কতবার চর্চা হবে ঠিক করুন — যেমন সপ্তাহে তিনবার, ২০–৩০ মিনিট করে","দেয়ালে চার্ট লাগান, প্রতিবার চর্চার পর টিক দিন","সম্ভব হলে পাশাপাশি বসে চর্চা করুন — তাতে একা লাগে না","কেউ বিরক্ত হয়ে গেলে ছেড়ে না দিয়ে নতুন একটা ছোট লক্ষ্য খুঁজে দিন","শেষে পারিবারিক প্রদর্শনী করুন — সবাই দেখাবে কী বানাল বা শিখল","নিখুঁত হওয়া নয়, চেষ্টার উদ্‌যাপন করুন — আর ঠিক করুন চালিয়ে যাবেন কি না"]}}'::jsonb, 2, 2557, 4748, '{}'::text[], 'any', ARRAY['hobby', 'screen free', 'creativity', 'challenge', 'boredom']::text[], false, 'in_review'::lp_review_status, 7030),
  ('mc-sc-grades-drop', 'scenario', 'scientific', 'shared', 'important', 'consensus', '📉', '{"en":"My child''s grades suddenly dropped","bn":"সন্তানের নম্বর হঠাৎ কমে গেছে"}'::jsonb, '{"en":"A sudden drop in marks is usually a sign that something else has changed. Find the reason before you punish or add more tuition.","bn":"হঠাৎ নম্বর কমে যাওয়া সাধারণত বোঝায় অন্য কিছু বদলেছে। শাস্তি দেওয়া বা টিউশন বাড়ানোর আগে কারণটা খুঁজুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"When a child who was doing well suddenly does worse, the cause is rarely laziness. Something in their health, sleep, feelings, friendships, family or schoolwork has usually changed.","bn":"যে শিশু ভালো করছিল, সে হঠাৎ খারাপ করলে কারণ খুব কমই অলসতা। সাধারণত তার স্বাস্থ্য, ঘুম, মন, বন্ধুত্ব, পরিবার বা পড়াশোনায় কিছু একটা বদলেছে।"},"why":{"en":"Common causes include not seeing the board well, poor sleep or too much screen time, bullying, worry about a family problem, a harder class or new teacher, a learning difficulty that shows up as work gets harder, and the early emotional changes of puberty.","bn":"সাধারণ কারণের মধ্যে আছে বোর্ড ঠিকমতো দেখতে না পাওয়া, কম ঘুম বা অতিরিক্ত স্ক্রিন, বুলিং, পারিবারিক কোনো সমস্যা নিয়ে দুশ্চিন্তা, কঠিন ক্লাস বা নতুন শিক্ষক, পড়া কঠিন হতে থাকায় সামনে আসা শেখার কোনো সমস্যা, আর বয়ঃসন্ধির শুরুর আবেগীয় পরিবর্তন।"},"normal":{"en":"Marks go up and down a little from term to term, especially when moving to a new class. One weak exam is not a crisis. A big or lasting drop, or a drop together with changes in mood or behaviour, needs attention.","bn":"এক টার্ম থেকে আরেক টার্মে নম্বর একটু ওঠানামা করে, বিশেষ করে নতুন ক্লাসে উঠলে। একটা খারাপ পরীক্ষা মানেই বিপদ নয়। বড় বা টানা পতন, অথবা নম্বর কমার সঙ্গে মেজাজ বা আচরণের পরিবর্তন — এগুলোয় নজর দিতে হবে।"},"do_now":{"en":["Stay calm and do not punish or shame","Ask gently: “Your marks were different this time. What has been hard lately?”","Look at the papers together to see where the marks were lost","Check sleep, screen time and how tired your child is"],"bn":["শান্ত থাকুন, শাস্তি দেবেন না, লজ্জাও দেবেন না","নরমভাবে জিজ্ঞেস করুন: “এবার নম্বরটা অন্যরকম এসেছে। ইদানীং কী কঠিন লাগছে?”","খাতাগুলো একসঙ্গে দেখুন, কোথায় নম্বর কাটা গেছে","ঘুম, স্ক্রিন টাইম আর সন্তান কতটা ক্লান্ত, তা খেয়াল করুন"]},"steps":{"en":["Meet the class teacher and ask what they have noticed","Get an eye test, and a hearing check if needed","Ask about friends and bullying in a relaxed moment","Reset the routine: fixed homework time, phones out of the bedroom, enough sleep","Agree on one or two subjects to focus on, with small weekly goals","Check again with the teacher after a month"],"bn":["শ্রেণিশিক্ষকের সঙ্গে দেখা করুন, তিনি কী লক্ষ করেছেন জিজ্ঞেস করুন","চোখ পরীক্ষা করান, দরকার হলে কানও","হালকা মুহূর্তে বন্ধু আর বুলিং নিয়ে জিজ্ঞেস করুন","রুটিন আবার ঠিক করুন: নির্দিষ্ট পড়ার সময়, শোবার ঘরে ফোন নয়, যথেষ্ট ঘুম","এক-দুটো বিষয়ে মন দিন, প্রতি সপ্তাহের জন্য ছোট লক্ষ্য রাখুন","এক মাস পর শিক্ষকের সঙ্গে আবার কথা বলুন"]},"avoid":{"en":["Hitting, shouting or calling your child stupid","Comparing with cousins or classmates","Adding more tuition before you know the cause","Taking away all play and rest as punishment"],"bn":["মারধর, চিৎকার বা সন্তানকে বোকা বলা","কাজিন বা সহপাঠীর সঙ্গে তুলনা","কারণ না জেনেই টিউশন বাড়ানো","শাস্তি হিসেবে সব খেলা আর বিশ্রাম বন্ধ করে দেওয়া"]},"example":{"en":"Rafi, in class 5, came home with low maths marks for the first time. His mother sat with him and the paper. “I can''t see the board from the back,” he said. An eye test showed he needed glasses. His teacher moved him to the front, and his marks recovered within a term.","bn":"পঞ্চম শ্রেণির রাফি প্রথমবার অঙ্কে কম নম্বর নিয়ে বাড়ি ফিরল। মা খাতা নিয়ে তার পাশে বসলেন। রাফি বলল, “পেছন থেকে বোর্ড দেখতে পাই না।” চোখ পরীক্ষায় দেখা গেল তার চশমা লাগবে। শিক্ষক তাকে সামনে বসালেন, আর এক টার্মের মধ্যেই নম্বর আগের জায়গায় ফিরল।"},"seek_help":{"en":["Marks keep falling despite help for several months","Your child seems sad, withdrawn or anxious most days","The teacher suspects a learning or attention difficulty","Your child refuses to go to school"],"bn":["সাহায্য সত্ত্বেও কয়েক মাস ধরে নম্বর কমছেই","সন্তান বেশির ভাগ দিন মন খারাপ, চুপচাপ বা দুশ্চিন্তায় থাকে","শিক্ষক শেখা বা মনোযোগের সমস্যার সন্দেহ করছেন","সন্তান স্কুলে যেতে চায় না"]},"warning_signs":{"en":["Talk of hurting themselves or not wanting to live — get help the same day","Big changes in eating, sleep or weight","Signs of bullying or abuse"],"bn":["নিজের ক্ষতি বা বাঁচতে না চাওয়ার কথা — সেদিনই সাহায্য নিন","খাওয়া, ঘুম বা ওজনে বড় পরিবর্তন","বুলিং বা নির্যাতনের লক্ষণ"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['grades', 'marks', 'falling behind', 'school results', 'sudden change']::text[], false, 'in_review'::lp_review_status, 7031),
  ('mc-sc-refuses-homework', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🙅', '{"en":"My child refuses to do homework","bn":"সন্তান হোমওয়ার্ক করতে চায় না"}'::jsonb, '{"en":"Daily homework battles wear everyone out. Find out what is behind the refusal and build a routine with choices.","bn":"প্রতিদিন হোমওয়ার্ক নিয়ে যুদ্ধে সবাই ক্লান্ত হয়ে পড়ে। না করার পেছনে কী আছে খুঁজুন, আর পছন্দের সুযোগ রেখে একটা রুটিন বানান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Refusing homework is a message. Your child may be too tired, find the work too hard, feel overwhelmed by the amount, or simply prefer screens. Sometimes it is a way to get your attention.","bn":"হোমওয়ার্ক না করা আসলে একটা বার্তা। সন্তান হয়তো খুব ক্লান্ত, কাজটা খুব কঠিন লাগছে, পরিমাণ দেখে ঘাবড়ে যাচ্ছে, বা স্ক্রিনটাই বেশি টানছে। কখনো কখনো এটা আপনার মনোযোগ পাওয়ার উপায়ও।"},"why":{"en":"After school, coaching and travel, many children have little energy left. When a task looks impossible, avoiding it feels safer than failing. Fights make homework feel even worse, so the cycle repeats.","bn":"স্কুল, কোচিং আর যাতায়াতের পর অনেক শিশুর শক্তি আর থাকে না। কাজ অসম্ভব মনে হলে ব্যর্থ হওয়ার চেয়ে এড়িয়ে যাওয়াই নিরাপদ মনে হয়। ঝগড়ায় হোমওয়ার্ক আরও অপছন্দের হয়ে ওঠে, আর চক্রটা চলতেই থাকে।"},"normal":{"en":"Most children complain about homework sometimes, and some days go badly. It is a concern when refusal happens most days, comes with tears or panic, or is limited to one subject.","bn":"বেশির ভাগ শিশুই মাঝে মাঝে হোমওয়ার্ক নিয়ে গজগজ করে, কোনো কোনো দিন খারাপ যায়। চিন্তার বিষয় হলো যখন প্রায় প্রতিদিন না করে, সঙ্গে কান্না বা আতঙ্ক থাকে, বা শুধু একটা বিষয়ে এমন হয়।"},"do_now":{"en":["Take a break from the fight tonight; stay calm","Ask: “Which part feels hardest?”","Help them start with just the first question, sitting beside them","Give a small choice: “Maths first or English first?”"],"bn":["আজ রাতে ঝগড়া থেকে বিরতি নিন; শান্ত থাকুন","জিজ্ঞেস করুন: “কোন অংশটা সবচেয়ে কঠিন লাগছে?”","পাশে বসে শুধু প্রথম প্রশ্নটা দিয়ে শুরু করতে সাহায্য করুন","ছোট একটা পছন্দ দিন: “আগে অঙ্ক, না ইংরেজি?”"]},"steps":{"en":["Agree on a fixed homework time after a snack and a short break","Break work into small pieces with short breaks","Screens come after homework, not before","Praise effort and finishing, not only correct answers","Talk to the teacher if the amount or difficulty seems too much","Review your child''s whole timetable; drop an extra class if there is no time to rest"],"bn":["নাশতা আর একটু বিশ্রামের পর হোমওয়ার্কের নির্দিষ্ট সময় ঠিক করুন","কাজ ছোট ছোট ভাগে করুন, মাঝে ছোট বিরতি","স্ক্রিন হোমওয়ার্কের পরে, আগে নয়","শুধু সঠিক উত্তর নয়, চেষ্টা আর শেষ করার প্রশংসা করুন","পরিমাণ বা কাঠিন্য বেশি মনে হলে শিক্ষকের সঙ্গে কথা বলুন","সন্তানের পুরো রুটিন দেখুন; বিশ্রামের সময় না থাকলে একটা বাড়তি ক্লাস বাদ দিন"]},"avoid":{"en":["Doing the homework for them","Hitting, threats or long lectures","Bribing with phone time every day","Calling your child lazy"],"bn":["নিজে হোমওয়ার্ক করে দেওয়া","মারধর, হুমকি বা লম্বা বক্তৃতা","প্রতিদিন ফোনের লোভ দেখানো","সন্তানকে অলস বলা"]},"example":{"en":"Every evening Nusrat, 9, cried over her English. Her father noticed she was fine with maths. He sat with her and saw she could not read the questions easily. He told her teacher, who gave her simpler reading practice, and the evening fights became much shorter.","bn":"৯ বছরের নুসরাত প্রতি সন্ধ্যায় ইংরেজি নিয়ে কাঁদত। বাবা খেয়াল করলেন, অঙ্কে তার কোনো সমস্যা নেই। পাশে বসে দেখলেন, প্রশ্নগুলোই সে সহজে পড়তে পারছে না। শিক্ষককে জানালেন, তিনি সহজ পড়ার অনুশীলন দিলেন — সন্ধ্যার ঝগড়া অনেক কমে গেল।"},"seek_help":{"en":["Refusal continues for weeks despite a calm routine","Your child panics, cries or has stomach-aches over schoolwork","You suspect difficulty with reading, writing, numbers or attention"],"bn":["শান্ত রুটিন সত্ত্বেও কয়েক সপ্তাহ ধরে না করা চলছে","পড়ার কথা উঠলেই আতঙ্ক, কান্না বা পেটব্যথা","পড়া, লেখা, অঙ্ক বা মনোযোগে সমস্যার সন্দেহ"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['homework', 'refusal', 'motivation', 'routine', 'power struggle']::text[], false, 'in_review'::lp_review_status, 7032),
  ('mc-sc-being-bullied', 'scenario', 'scientific', 'shared', 'important', 'guideline', '😟', '{"en":"My child is being bullied","bn":"সন্তান বুলিংয়ের শিকার হচ্ছে"}'::jsonb, '{"en":"Believe your child, keep them safe, and work with the school until it stops. It is never your child''s fault.","bn":"সন্তানকে বিশ্বাস করুন, নিরাপদ রাখুন, আর বন্ধ না হওয়া পর্যন্ত স্কুলের সঙ্গে মিলে কাজ করুন। এটা কখনোই আপনার সন্তানের দোষ নয়।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Bullying is repeated, deliberate hurting by someone with more power: hitting, insults, mocking looks or religion, leaving out, rumours or online harassment. Children often hide it out of shame or fear it will get worse.","bn":"বুলিং হলো বেশি ক্ষমতার কারও বারবার ইচ্ছে করে কষ্ট দেওয়া: মারা, অপমান, চেহারা বা ধর্ম নিয়ে ঠাট্টা, দল থেকে বাদ দেওয়া, গুজব বা অনলাইনে হয়রানি। লজ্জায় বা পরিস্থিতি আরও খারাপ হওয়ার ভয়ে শিশুরা প্রায়ই এটা লুকিয়ে রাখে।"},"why":{"en":"Children who bully often target someone who seems different or alone. Bullying hurts self-esteem, sleep, learning and mental health, so adults must act.","bn":"যারা বুলিং করে, তারা প্রায়ই এমন কাউকে বেছে নেয় যে আলাদা বা একা। বুলিং আত্মসম্মান, ঘুম, পড়াশোনা আর মানসিক স্বাস্থ্যের ক্ষতি করে — তাই বড়দের ব্যবস্থা নিতেই হবে।"},"normal":{"en":"Occasional arguments and one-off teasing between equals are a normal part of friendship. Bullying is different: it is repeated, one-sided and meant to hurt.","bn":"সমানে সমানে মাঝে মাঝে ঝগড়া বা একবারের খোঁচা বন্ধুত্বের স্বাভাবিক অংশ। বুলিং আলাদা: এটা বারবার ঘটে, একতরফা, আর কষ্ট দেওয়ার জন্যই করা হয়।"},"do_now":{"en":["Listen calmly and thank your child for telling you","Say clearly: “This is not your fault. We will sort it out together.”","Write down what happened, when, where and who was there","Save screenshots if it happened online, then block and report"],"bn":["শান্তভাবে শুনুন, বলার জন্য ধন্যবাদ দিন","পরিষ্কার করে বলুন: “এতে তোমার কোনো দোষ নেই। আমরা একসঙ্গে সমাধান করব।”","কী হয়েছে, কবে, কোথায় আর কে ছিল — লিখে রাখুন","অনলাইনে হলে স্ক্রিনশট রাখুন, তারপর ব্লক ও রিপোর্ট করুন"]},"steps":{"en":["Meet the class teacher or head teacher and ask what they will do","Agree on a safe adult your child can go to at school","Help your child stay near friends at break and on the way home","Practise a calm, firm reply: “Stop. I don''t like it,” then walk away to an adult","Build confidence outside school through a hobby, sport or club","Follow up with the school every week until it has stopped"],"bn":["শ্রেণিশিক্ষক বা প্রধান শিক্ষকের সঙ্গে দেখা করুন, তাঁরা কী করবেন জিজ্ঞেস করুন","স্কুলে সন্তান কোন নিরাপদ বড়র কাছে যাবে, ঠিক করুন","বিরতিতে আর বাড়ি ফেরার পথে সন্তান যেন বন্ধুদের কাছাকাছি থাকে","শান্ত, দৃঢ় জবাব অনুশীলন করান: “থামো। আমার ভালো লাগছে না,” তারপর কোনো বড়র কাছে চলে যাওয়া","শখ, খেলা বা ক্লাবের মাধ্যমে স্কুলের বাইরে আত্মবিশ্বাস বাড়ান","বন্ধ না হওয়া পর্যন্ত প্রতি সপ্তাহে স্কুলের কাছে খোঁজ নিন"]},"avoid":{"en":["Telling your child to hit back","Saying “just ignore it” or “toughen up”","Confronting the other child or their parents angrily","Taking away your child''s phone because they were bullied online"],"bn":["সন্তানকে পাল্টা মারতে বলা","“পাত্তা দিয়ো না” বা “শক্ত হও” বলা","অন্য শিশু বা তার মা-বাবার সঙ্গে রেগে ঝগড়া করা","অনলাইনে বুলিংয়ের শিকার হয়েছে বলে সন্তানের ফোন কেড়ে নেওয়া"]},"example":{"en":"Ayan, 11, stopped eating his tiffin. His mother found out older boys were taking it and calling him names. She wrote down the details and met the head teacher, who moved the break supervision near Ayan''s class. She checked in every Friday until it stopped.","bn":"১১ বছরের আয়ান টিফিন খাওয়া বন্ধ করে দিল। মা জানতে পারলেন, উঁচু ক্লাসের ছেলেরা তার টিফিন কেড়ে নেয় আর বাজে নামে ডাকে। তিনি সব লিখে প্রধান শিক্ষকের সঙ্গে দেখা করলেন; বিরতির সময় আয়ানের ক্লাসের কাছে শিক্ষকের নজরদারি বাড়ানো হলো। বন্ধ না হওয়া পর্যন্ত মা প্রতি শুক্রবার খোঁজ নিলেন।"},"seek_help":{"en":["Threats, serious violence or sexual harassment — call 999","The school does not act, or bullying continues","Your child refuses school, sleeps badly or seems low for weeks","Call the child helpline 1098 for advice"],"bn":["হুমকি, গুরুতর মারধর বা যৌন হয়রানি — ৯৯৯-এ ফোন করুন","স্কুল ব্যবস্থা নিচ্ছে না, বা বুলিং চলছেই","কয়েক সপ্তাহ ধরে সন্তান স্কুলে যেতে চায় না, ঘুম খারাপ বা মন খারাপ","পরামর্শের জন্য শিশু হেল্পলাইন ১০৯৮-এ ফোন করুন"]},"warning_signs":{"en":["Injuries, or talk of self-harm or not wanting to live — get help the same day"],"bn":["আঘাত, বা নিজের ক্ষতি বা বাঁচতে না চাওয়ার কথা — সেদিনই সাহায্য নিন"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['bullying', 'teasing', 'school', 'cyberbullying', 'victim']::text[], false, 'in_review'::lp_review_status, 7033),
  ('mc-sc-gaming-angry', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🎮', '{"en":"My child games all day and gets angry when I stop it","bn":"সন্তান সারাদিন গেম খেলে, থামাতে গেলে রেগে যায়"}'::jsonb, '{"en":"Games are built to be hard to put down. Clear limits agreed in advance, warnings and a routine work better than snatching the device.","bn":"গেম বানানোই হয় যাতে ছাড়া কঠিন হয়। হঠাৎ ডিভাইস কেড়ে নেওয়ার চেয়ে আগে থেকে ঠিক করা সীমা, আগাম সতর্কবার্তা আর রুটিন বেশি কাজে দেয়।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Being stopped in the middle of a match feels like losing. Your child''s anger is partly the game''s design and partly a brain that is still learning self-control.","bn":"খেলার মাঝখানে থামানো মানে তার কাছে হেরে যাওয়া। সন্তানের রাগের কিছুটা গেমের নকশার জন্য, আর কিছুটা কারণ তার মস্তিষ্ক এখনো আত্মনিয়ন্ত্রণ শিখছে।"},"why":{"en":"Rewards, levels, streaks and team play keep children hooked. Without clear rules, gaming slowly pushes out sleep, homework, outdoor play and family time.","bn":"পুরস্কার, লেভেল, ধারাবাহিক বোনাস আর দল বেঁধে খেলা শিশুকে আটকে রাখে। পরিষ্কার নিয়ম না থাকলে গেম ধীরে ধীরে ঘুম, হোমওয়ার্ক, বাইরের খেলা আর পরিবারের সময় সরিয়ে দেয়।"},"normal":{"en":"Some grumbling when time is up is normal. It is a concern when gaming takes over most free time for months, or anger turns into hitting, breaking things or stealing money to play.","bn":"সময় শেষ হলে একটু গজগজ করা স্বাভাবিক। চিন্তার বিষয় হলো যখন কয়েক মাস ধরে অবসরের বেশির ভাগ সময় গেমে যায়, বা রাগ থেকে মারা, জিনিস ভাঙা বা খেলার জন্য টাকা চুরি শুরু হয়।"},"do_now":{"en":["Stay calm; do not grab the device in anger","Give a warning: “Five minutes, then finish this round”","Name the feeling: “I know it''s hard to stop when you''re winning”","Once calm, plan a family talk about gaming rules"],"bn":["শান্ত থাকুন; রেগে ডিভাইস ছিনিয়ে নেবেন না","আগে জানিয়ে দিন: “পাঁচ মিনিট, তারপর এই রাউন্ড শেষ”","অনুভূতির নাম দিন: “জিতছ যখন, তখন থামা কঠিন — বুঝি”","শান্ত হলে গেমের নিয়ম নিয়ে পারিবারিক আলাপের পরিকল্পনা করুন"]},"steps":{"en":["Agree together when and how long gaming is allowed on school days and holidays","Use a timer and parental controls so the device, not you, ends the session","Gaming only after homework, never in the bedroom or the hour before bed","Agree on a clear consequence for not stopping, such as no gaming the next day","Check age ratings and turn off chat with strangers","Fill the gap: sport, outdoor play, a hobby or time with you"],"bn":["স্কুলের দিন আর ছুটির দিনে কখন আর কতক্ষণ গেম চলবে, একসঙ্গে ঠিক করুন","টাইমার আর প্যারেন্টাল কন্ট্রোল ব্যবহার করুন, যাতে আপনি নন, ডিভাইসই খেলা শেষ করে","শুধু হোমওয়ার্কের পরে গেম; শোবার ঘরে বা ঘুমের আগের এক ঘণ্টায় কখনো নয়","সময়মতো না থামালে কী হবে, তা পরিষ্কার করে ঠিক করুন — যেমন পরের দিন গেম বন্ধ","বয়সের রেটিং দেখুন, অচেনা মানুষের সঙ্গে চ্যাট বন্ধ করুন","ফাঁকা সময়টা ভরিয়ে দিন: খেলাধুলা, বাইরে খেলা, শখ বা আপনার সঙ্গে সময়"]},"avoid":{"en":["Snatching or breaking the device","Hitting or shouting","Using games as a babysitter for hours","Rules that change every day"],"bn":["ডিভাইস ছিনিয়ে নেওয়া বা ভেঙে ফেলা","মারধর বা চিৎকার","ঘণ্টার পর ঘণ্টা গেমকে আয়া বানানো","প্রতিদিন বদলে যাওয়া নিয়ম"]},"example":{"en":"Tanvir, 12, shouted every night when told to stop. His parents sat with him and agreed: one hour after homework, a ten-minute warning, and the phone charges in the living room at 9 pm. The first week was hard, but by the third week he was putting it down himself.","bn":"১২ বছরের তানভীর থামতে বললেই প্রতি রাতে চিৎকার করত। মা-বাবা তার সঙ্গে বসে ঠিক করলেন: হোমওয়ার্কের পর এক ঘণ্টা, দশ মিনিট আগে সতর্কবার্তা, আর রাত ৯টায় ফোন বসার ঘরে চার্জে যাবে। প্রথম সপ্তাহ কঠিন গেল, কিন্তু তৃতীয় সপ্তাহে সে নিজেই ফোন রেখে দিচ্ছিল।"},"seek_help":{"en":["Gaming has taken over sleep, school, meals and friends for months","Aggression, threats or stealing money to play","Your child seems low or anxious when not gaming"],"bn":["কয়েক মাস ধরে গেম ঘুম, স্কুল, খাওয়া আর বন্ধুদের জায়গা দখল করেছে","খেলার জন্য মারমুখী আচরণ, হুমকি বা টাকা চুরি","গেম না খেললে সন্তান মন খারাপ বা অস্থির থাকে"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['gaming', 'anger', 'screen time', 'tantrum', 'limits']::text[], false, 'in_review'::lp_review_status, 7034),
  ('mc-sc-lying-phone', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🤥', '{"en":"My child lied about using the phone","bn":"সন্তান ফোন ব্যবহার নিয়ে মিথ্যা বলেছে"}'::jsonb, '{"en":"Children lie to avoid trouble. Respond in a way that makes honesty easier next time, and find out what they were doing.","bn":"ঝামেলা এড়াতেই শিশুরা মিথ্যা বলে। এমনভাবে সাড়া দিন যাতে পরের বার সত্যি বলা সহজ হয়, আর জেনে নিন সে আসলে কী করছিল।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Using the phone secretly at night or saying “I was studying” when they were gaming is common at this age. The lie is usually about avoiding punishment, not about not loving you.","bn":"রাতে লুকিয়ে ফোন চালানো, বা গেম খেলে বলা “পড়ছিলাম” — এ বয়সে এটা খুবই সাধারণ। মিথ্যাটা সাধারণত শাস্তি এড়ানোর জন্য, আপনাকে ভালো না বাসার জন্য নয়।"},"why":{"en":"If the punishment for the truth is very harsh, lying feels like the smart choice. The pull of games and videos is strong, and rules that feel unfair invite sneaking.","bn":"সত্যি বললে যদি খুব কঠিন শাস্তি হয়, তাহলে মিথ্যা বলাটাই বুদ্ধিমানের কাজ মনে হয়। গেম আর ভিডিওর টান প্রবল, আর অন্যায্য মনে হওয়া নিয়ম লুকোচুরিকে উসকে দেয়।"},"normal":{"en":"Most children tell lies sometimes while they are learning about honesty. It needs more attention when lying is frequent, or when secret phone use hides contact with strangers or upsetting content.","bn":"সততা শেখার পথে বেশির ভাগ শিশু মাঝে মাঝে মিথ্যা বলে। বেশি নজর দিতে হবে যখন মিথ্যা ঘন ঘন হয়, বা লুকিয়ে ফোন চালানোর আড়ালে অচেনা মানুষের সঙ্গে যোগাযোগ বা খারাপ কনটেন্ট থাকে।"},"do_now":{"en":["Take a breath; talk when you are both calm","Say what you know without trapping them: “I saw the phone was used at midnight.”","Ask what they were doing, and listen","Thank them if they tell the truth now"],"bn":["একটা লম্বা শ্বাস নিন; দুজনেই শান্ত হলে কথা বলুন","ফাঁদে না ফেলে যা জানেন তা বলুন: “দেখলাম রাত ১২টায় ফোন চালানো হয়েছে।”","সে কী করছিল জিজ্ঞেস করুন, আর শুনুন","এখন সত্যি বললে ধন্যবাদ দিন"]},"steps":{"en":["Separate the two issues: the rule that was broken, and the lie","Apply a fair, pre-agreed consequence, such as losing phone time for a day","Explain that trust is rebuilt step by step with honesty","Review the phone rules together; are they realistic?","Move charging out of the bedroom and use night-time locks","Make sure nothing worrying happened online"],"bn":["দুটো বিষয় আলাদা করুন: যে নিয়ম ভেঙেছে, আর মিথ্যা","আগে থেকে ঠিক করা ন্যায্য পরিণতি প্রয়োগ করুন — যেমন একদিন ফোন বন্ধ","বুঝিয়ে বলুন, সত্যি বলার মধ্য দিয়েই ধাপে ধাপে বিশ্বাস ফিরে আসে","ফোনের নিয়মগুলো একসঙ্গে আবার দেখুন — এগুলো কি বাস্তবসম্মত?","চার্জিং শোবার ঘরের বাইরে নিন, রাতের লক ব্যবহার করুন","অনলাইনে চিন্তার কিছু ঘটেনি তো, নিশ্চিত হোন"]},"avoid":{"en":["Hitting, humiliating or calling them a liar in front of others","Very long or harsh punishments that make the next lie more likely","Setting traps to catch them lying","Breaking your own family screen rules"],"bn":["মারধর, অপমান, বা অন্যদের সামনে মিথ্যুক বলা","খুব লম্বা বা কঠিন শাস্তি, যাতে পরের মিথ্যার সম্ভাবনা বাড়ে","মিথ্যা ধরার জন্য ফাঁদ পাতা","পরিবারের স্ক্রিন-নিয়ম নিজেই ভাঙা"]},"example":{"en":"Mitu, 10, said she had been asleep, but her mother saw videos watched late at night. In the morning her mother said calmly, “I know you were watching. I''m not angry that you told me now, but the tablet stays in our room tonight.” The next time, Mitu admitted it herself.","bn":"১০ বছরের মিতু বলল সে ঘুমিয়ে ছিল, কিন্তু মা দেখলেন অনেক রাতে ভিডিও দেখা হয়েছে। সকালে মা শান্তভাবে বললেন, “জানি তুমি দেখছিলে। এখন বলেছ বলে আমি রাগ করছি না, কিন্তু আজ রাতে ট্যাবটা আমাদের ঘরে থাকবে।” পরের বার মিতু নিজেই স্বীকার করল।"},"seek_help":{"en":["You find contact with unknown adults, requests for photos or threats — report and call 999","Lying becomes constant along with stealing or big behaviour changes","Your child seems anxious or low and very secretive"],"bn":["অচেনা বড় মানুষের সঙ্গে যোগাযোগ, ছবি চাওয়া বা হুমকির প্রমাণ — রিপোর্ট করুন ও ৯৯৯-এ ফোন করুন","মিথ্যার সঙ্গে চুরি বা আচরণে বড় পরিবর্তন নিয়মিত হয়ে উঠছে","সন্তান দুশ্চিন্তায় বা মন খারাপ, আর খুব লুকোছাপা করছে"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['lying', 'phone', 'trust', 'secret use', 'honesty']::text[], false, 'in_review'::lp_review_status, 7035),
  ('mc-sc-everyone-has-phone', 'scenario', 'general', 'shared', 'routine', 'consensus', '📵', '{"en":"“Everyone has a phone except me”","bn":"“আমার ছাড়া সবার ফোন আছে”"}'::jsonb, '{"en":"Take the feeling seriously, check the facts, and decide based on your child''s needs and readiness — not on pressure.","bn":"অনুভূতিটাকে গুরুত্ব দিন, আসল অবস্থা যাচাই করুন, আর চাপে নয় — সন্তানের প্রয়োজন আর প্রস্তুতি দেখে সিদ্ধান্ত নিন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your child may genuinely feel left out of chats, games and jokes. At the same time, “everyone” often means a few friends. Both the feeling and the facts matter.","bn":"চ্যাট, গেম আর মজার আলাপ থেকে সন্তান সত্যিই বাদ পড়া বোধ করতে পারে। আবার “সবাই” বলতে প্রায়ই বোঝায় কয়েকজন বন্ধু। অনুভূতি আর আসল অবস্থা — দুটোই গুরুত্বপূর্ণ।"},"why":{"en":"Belonging matters a lot between 9 and 13. Phones have become part of how friends connect, so not having one can feel like being outside the group.","bn":"৯ থেকে ১৩ বছর বয়সে দলের অংশ হওয়াটা খুব গুরুত্বপূর্ণ। বন্ধুদের যোগাযোগের একটা বড় মাধ্যম এখন ফোন, তাই ফোন না থাকলে নিজেকে দলের বাইরে মনে হতে পারে।"},"normal":{"en":"Asking, even begging, for a phone is very common. Families decide at different ages, and there is no single right age.","bn":"ফোন চাওয়া, এমনকি বায়না ধরা খুবই সাধারণ। একেক পরিবার একেক বয়সে সিদ্ধান্ত নেয়, আর কোনো একটা নির্দিষ্ট সঠিক বয়স নেই।"},"do_now":{"en":["Listen without mocking: “It sounds hard to be left out of the group chat.”","Ask what they want the phone for","Do not decide in the heat of an argument; say you will think about it"],"bn":["ঠাট্টা না করে শুনুন: “গ্রুপ চ্যাট থেকে বাদ পড়াটা কষ্টের, বুঝতে পারছি।”","ফোন দিয়ে কী করতে চায়, জিজ্ঞেস করুন","তর্কের উত্তেজনায় সিদ্ধান্ত নেবেন না; বলুন আপনি ভেবে দেখবেন"]},"steps":{"en":["Talk to other parents; you may find many share your worries","Think about real needs, such as travelling alone or contacting you after coaching","If the answer is “not yet”, explain your reasons and when you will review it","Offer alternatives: a basic phone for calls, or supervised use of a family device to stay in touch with friends","If the answer is “yes”, agree on written rules and set up parental controls first","Help your child keep friendships through play, visits and clubs"],"bn":["অন্য মা-বাবাদের সঙ্গে কথা বলুন; দেখবেন অনেকেরই একই দুশ্চিন্তা","আসল প্রয়োজন ভাবুন — যেমন একা যাতায়াত বা কোচিং শেষে আপনার সঙ্গে যোগাযোগ","উত্তর “এখনো না” হলে কারণ বুঝিয়ে বলুন, আর কবে আবার ভাববেন তা জানিয়ে দিন","বিকল্প দিন: শুধু কলের জন্য সাধারণ ফোন, বা বন্ধুদের সঙ্গে যোগাযোগের জন্য তত্ত্বাবধানে পরিবারের ডিভাইস","উত্তর “হ্যাঁ” হলে আগে লিখিত নিয়ম ঠিক করুন আর প্যারেন্টাল কন্ট্রোল চালু করুন","খেলা, বেড়ানো আর ক্লাবের মাধ্যমে সন্তানকে বন্ধুত্ব ধরে রাখতে সাহায্য করুন"]},"avoid":{"en":["Mocking or dismissing the feeling","Giving in just to stop the nagging","Giving a smartphone with no rules or controls","Promising a phone as a reward for exam results without thinking about readiness"],"bn":["অনুভূতিকে ঠাট্টা বা উড়িয়ে দেওয়া","শুধু বায়না থামাতে রাজি হয়ে যাওয়া","কোনো নিয়ম বা নিয়ন্ত্রণ ছাড়া স্মার্টফোন দেওয়া","প্রস্তুতির কথা না ভেবে পরীক্ষার ফলের পুরস্কার হিসেবে ফোনের প্রতিশ্রুতি"]},"example":{"en":"Sara, 10, said she was the only one in class without a phone. Her father asked three other parents and learned only a few children had one. He told Sara, “Not yet. We will talk again after your next birthday. Until then you can message your friends from my phone in the evening.” Sara was disappointed, but felt heard.","bn":"১০ বছরের সারা বলল, ক্লাসে শুধু তারই ফোন নেই। বাবা আরও তিনজন অভিভাবকের সঙ্গে কথা বলে জানলেন, অল্প কয়েকজনেরই ফোন আছে। তিনি সারাকে বললেন, “এখনো না। তোমার পরের জন্মদিনের পর আবার কথা বলব। ততদিন সন্ধ্যায় আমার ফোন থেকে বন্ধুদের মেসেজ করতে পারো।” সারা মন খারাপ করল, কিন্তু বুঝল তার কথা শোনা হয়েছে।"},"seek_help":{"en":["Your child is being excluded or bullied for not having a phone — talk to the school","Your child is very isolated or sad for weeks"],"bn":["ফোন না থাকায় সন্তানকে বাদ দেওয়া বা হেনস্তা করা হচ্ছে — স্কুলের সঙ্গে কথা বলুন","কয়েক সপ্তাহ ধরে সন্তান খুব একা বা মন খারাপ"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['first phone', 'peer pressure', 'everyone has one', 'saying no', 'smartphone']::text[], false, 'in_review'::lp_review_status, 7036),
  ('mc-sc-anger-outbursts', 'scenario', 'scientific', 'shared', 'important', 'consensus', '😡', '{"en":"My child has anger outbursts","bn":"সন্তান হঠাৎ হঠাৎ প্রচণ্ড রেগে যায়"}'::jsonb, '{"en":"Keep everyone safe, stay calm yourself, and teach anger skills when the storm has passed.","bn":"সবাইকে নিরাপদ রাখুন, নিজে শান্ত থাকুন, আর ঝড় থামলে রাগ সামলানোর কৌশল শেখান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Shouting, slamming doors, throwing things or hitting a sibling usually means your child is overwhelmed and does not yet have better ways to cope. Anger often covers another feeling: hurt, embarrassment, jealousy or worry.","bn":"চিৎকার, দরজা আছড়ানো, জিনিস ছোড়া বা ভাইবোনকে মারা সাধারণত বোঝায় সন্তান সামলাতে পারছে না, আর এর চেয়ে ভালো উপায় এখনো শেখেনি। রাগের নিচে প্রায়ই অন্য অনুভূতি লুকিয়ে থাকে: কষ্ট, লজ্জা, হিংসা বা দুশ্চিন্তা।"},"why":{"en":"Tiredness, hunger, school stress, too much screen time, conflict at home and copying how adults react all make outbursts more likely. Harsh punishment and hitting tend to increase anger, not reduce it.","bn":"ক্লান্তি, ক্ষুধা, স্কুলের চাপ, অতিরিক্ত স্ক্রিন, ঘরের অশান্তি, আর বড়রা কীভাবে প্রতিক্রিয়া দেখান তা নকল করা — সবই রাগের বিস্ফোরণ বাড়ায়। কঠোর শাস্তি আর মারধর রাগ কমায় না, বরং বাড়ায়।"},"normal":{"en":"Occasional angry outbursts are normal at this age, especially when tired or treated unfairly. It is a concern when they happen most days, last a long time, or involve hurting people.","bn":"এ বয়সে মাঝে মাঝে রেগে ফেটে পড়া স্বাভাবিক, বিশেষ করে ক্লান্ত থাকলে বা অন্যায় আচরণের শিকার হলে। চিন্তার বিষয় হলো যখন প্রায় প্রতিদিন হয়, অনেকক্ষণ চলে, বা কাউকে আঘাত করে।"},"do_now":{"en":["Make sure everyone is safe; move younger siblings away","Keep your voice low and few words: “I''m here. Let''s calm down first.”","Do not argue or lecture in the middle of the outburst","Give space in a safe spot until your child calms"],"bn":["সবাই নিরাপদ কি না নিশ্চিত করুন; ছোট ভাইবোনকে সরিয়ে নিন","গলা নিচু রাখুন, কথা কম: “আমি আছি। আগে শান্ত হই।”","রাগের মাঝখানে তর্ক বা উপদেশ নয়","শান্ত না হওয়া পর্যন্ত নিরাপদ জায়গায় একটু একা থাকতে দিন"]},"steps":{"en":["Once calm, talk about what happened and what they felt underneath","Practise calm-down skills on good days: slow breathing, counting, a calm corner","Agree on clear family rules: angry is okay, hitting and breaking are not","Help them repair: an apology, fixing or replacing what was broken","Look for patterns: time of day, hunger, screens, school days","Praise times they handled anger well"],"bn":["শান্ত হলে কী হয়েছিল আর ভেতরে কী অনুভব করছিল, তা নিয়ে কথা বলুন","ভালো দিনে শান্ত হওয়ার কৌশল অনুশীলন করুন: ধীরে শ্বাস, গোনা, শান্ত কোণ","পরিবারের পরিষ্কার নিয়ম ঠিক করুন: রাগ করা চলবে, মারা আর ভাঙা চলবে না","ভুল শোধরাতে সাহায্য করুন: দুঃখিত বলা, যা ভেঙেছে তা ঠিক করা বা বদলে দেওয়া","ধরন খুঁজুন: দিনের কোন সময়, ক্ষুধা, স্ক্রিন, স্কুলের দিন","রাগ ভালোভাবে সামলালে প্রশংসা করুন"]},"avoid":{"en":["Hitting, shouting back or threatening","Giving in to demands to stop the outburst","Shaming them in front of relatives","Ignoring a pattern that is getting worse"],"bn":["মারধর, পাল্টা চিৎকার বা হুমকি","রাগ থামাতে দাবি মেনে নেওয়া","আত্মীয়দের সামনে লজ্জা দেওয়া","খারাপ হতে থাকা ধরনকে উপেক্ষা করা"]},"example":{"en":"When Imran, 8, lost at carrom he threw the striker. His mother said quietly, “You''re really upset. Go to the calm corner, and I''ll come in a minute.” Later they practised slow breathing together and Imran said sorry to his cousin. Over the weeks the outbursts became shorter.","bn":"ক্যারমে হেরে ৮ বছরের ইমরান স্ট্রাইকার ছুড়ে মারল। মা আস্তে বললেন, “তুমি খুব কষ্ট পেয়েছ। শান্ত কোণে যাও, আমি এক মিনিটে আসছি।” পরে দুজনে মিলে ধীরে শ্বাস নেওয়ার অনুশীলন করল, আর ইমরান কাজিনের কাছে দুঃখিত বলল। কয়েক সপ্তাহে রাগের ঝড় ছোট হয়ে এল।"},"seek_help":{"en":["Outbursts happen most days for several weeks","Your child hurts people, animals or themselves","Anger comes with sadness, poor sleep or problems at school","You find it hard to stay calm and fear you might hurt your child — ask for support"],"bn":["কয়েক সপ্তাহ ধরে প্রায় প্রতিদিন রাগের বিস্ফোরণ","সন্তান মানুষ, পশুপাখি বা নিজেকে আঘাত করছে","রাগের সঙ্গে মন খারাপ, কম ঘুম বা স্কুলে সমস্যা","আপনি শান্ত থাকতে পারছেন না, সন্তানকে আঘাত করে ফেলার ভয় পাচ্ছেন — সহায়তা চান"]},"warning_signs":{"en":["Self-harm, or talk of not wanting to live — get help the same day","Serious violence that puts someone in danger — call 999"],"bn":["নিজের ক্ষতি, বা বাঁচতে না চাওয়ার কথা — সেদিনই সাহায্য নিন","গুরুতর সহিংসতা যাতে কেউ বিপদে পড়ে — ৯৯৯-এ ফোন করুন"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['anger', 'outbursts', 'tantrums', 'shouting', 'hitting', 'calm down']::text[], false, 'in_review'::lp_review_status, 7037),
  ('mc-sc-caught-cheating', 'scenario', 'general', 'shared', 'routine', 'consensus', '📝', '{"en":"My child was caught cheating","bn":"সন্তান নকল করতে গিয়ে ধরা পড়েছে"}'::jsonb, '{"en":"Cheating is often a sign of pressure or fear of failing. Hold your child accountable, and look at why it happened.","bn":"নকল প্রায়ই চাপ বা ফেল করার ভয়ের লক্ষণ। সন্তানকে দায় নিতে শেখান, আর কেন এমন হলো তা খুঁজে দেখুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Copying in an exam, copying homework or looking at answers online is a mistake that many children make at least once. How you respond decides whether your child learns honesty or just learns not to get caught.","bn":"পরীক্ষায় দেখে লেখা, অন্যের হোমওয়ার্ক টুকে নেওয়া বা অনলাইনে উত্তর দেখা — অনেক শিশু অন্তত একবার এই ভুল করে। আপনার প্রতিক্রিয়াই ঠিক করবে, সন্তান সততা শিখবে, নাকি শুধু ধরা না পড়ার কৌশল শিখবে।"},"why":{"en":"Children cheat when they feel the result matters more than learning, fear punishment or shame for low marks, do not understand the work, or see friends cheating without consequences.","bn":"শিশু নকল করে যখন মনে করে শেখার চেয়ে ফলাফল বেশি জরুরি, কম নম্বরের জন্য শাস্তি বা লজ্জার ভয় পায়, পড়াটা বোঝে না, বা দেখে বন্ধুরা নকল করেও পার পেয়ে যাচ্ছে।"},"normal":{"en":"A single incident is a learning moment, not proof of bad character. Repeated cheating needs a closer look at pressure and learning.","bn":"একবারের ঘটনা শেখার সুযোগ, খারাপ চরিত্রের প্রমাণ নয়। বারবার নকল করলে চাপ আর শেখার সমস্যা ভালো করে দেখতে হবে।"},"do_now":{"en":["Stay calm and hear your child''s side first","Ask: “What made you feel you needed to copy?”","Make it clear that cheating is not okay, and that you still love them"],"bn":["শান্ত থাকুন, আগে সন্তানের কথা শুনুন","জিজ্ঞেস করুন: “কেন মনে হলো নকল করতে হবে?”","পরিষ্কার করে বলুন নকল করা ঠিক নয় — আর আপনি তবুও তাকে ভালোবাসেন"]},"steps":{"en":["Support the school''s consequence rather than fighting it","Help your child take responsibility, for example apologising to the teacher","Find out if they understand the subject; get help where they are stuck","Reduce pressure: talk about learning and effort rather than rank","Talk about honesty as a family value, with examples from your own life","Praise honest work, even when the marks are lower"],"bn":["স্কুলের দেওয়া পরিণতির বিরোধিতা না করে সমর্থন করুন","সন্তানকে দায় নিতে সাহায্য করুন — যেমন শিক্ষকের কাছে ক্ষমা চাওয়া","বিষয়টা সে বোঝে কি না দেখুন; যেখানে আটকে আছে সেখানে সাহায্য নিন","চাপ কমান: রোল নম্বর নয়, শেখা আর চেষ্টার কথা বলুন","নিজের জীবনের উদাহরণ দিয়ে সততাকে পরিবারের মূল্যবোধ হিসেবে আলোচনা করুন","নম্বর কম এলেও সৎভাবে করা কাজের প্রশংসা করুন"]},"avoid":{"en":["Hitting or humiliating your child","Blaming the teacher or the friend to protect your child","Saying “Everyone does it”","Making marks the only thing you praise"],"bn":["সন্তানকে মারা বা অপমান করা","সন্তানকে বাঁচাতে শিক্ষক বা বন্ধুর ঘাড়ে দোষ চাপানো","“সবাই তো করে” বলা","শুধু নম্বরেরই প্রশংসা করা"]},"example":{"en":"Farhan, 12, was caught with notes in a class test. His father was angry but waited until evening. Farhan admitted he had not understood the chapter and was scared of a low mark. Together they told the teacher, and his father arranged help with that chapter. “I''d rather see a low mark than a dishonest one,” he said.","bn":"১২ বছরের ফারহান ক্লাস টেস্টে চিরকুটসহ ধরা পড়ল। বাবা রেগে গেলেও সন্ধ্যা পর্যন্ত অপেক্ষা করলেন। ফারহান স্বীকার করল, অধ্যায়টা সে বোঝেনি আর কম নম্বরের ভয় পাচ্ছিল। দুজনে মিলে শিক্ষককে জানাল, আর বাবা ওই অধ্যায়ে সাহায্যের ব্যবস্থা করলেন। বললেন, “অসৎ নম্বরের চেয়ে কম নম্বর দেখাই আমার কাছে ভালো।”"},"seek_help":{"en":["Cheating keeps happening despite support","Your child seems very anxious about marks, or has headaches and stomach-aches before tests","You suspect a learning difficulty"],"bn":["সহায়তা সত্ত্বেও বারবার নকল","নম্বর নিয়ে সন্তান খুব দুশ্চিন্তায়, বা পরীক্ষার আগে মাথাব্যথা-পেটব্যথা","শেখার কোনো সমস্যার সন্দেহ"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['cheating', 'honesty', 'exam', 'copying', 'integrity']::text[], false, 'in_review'::lp_review_status, 7038),
  ('mc-sc-left-out', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '😔', '{"en":"My child is left out by their friend group","bn":"বন্ধুদের দল সন্তানকে বাদ দিচ্ছে"}'::jsonb, '{"en":"Being left out hurts deeply. Listen, help your child widen their circle, and watch for signs of bullying.","bn":"বাদ পড়ার কষ্ট গভীর। মন দিয়ে শুনুন, সন্তানকে বন্ধুর গণ্ডি বাড়াতে সাহায্য করুন, আর বুলিংয়ের লক্ষণ খেয়াল রাখুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Friend groups shift often between 8 and 13. Your child may suddenly not be invited, find no seat at lunch, or be left out of a group chat. It can feel like the end of the world to them.","bn":"৮ থেকে ১৩ বছর বয়সে বন্ধুদের দল প্রায়ই বদলায়। সন্তান হঠাৎ দাওয়াত পাচ্ছে না, টিফিনে বসার জায়গা পাচ্ছে না, বা গ্রুপ চ্যাট থেকে বাদ পড়ছে। তার কাছে মনে হতে পারে পৃথিবী শেষ।"},"why":{"en":"Children are learning how friendships work, and groups often include some by leaving others out. Sometimes it is a passing change; sometimes it is deliberate exclusion, which is a form of bullying.","bn":"বন্ধুত্ব কীভাবে কাজ করে, শিশুরা তা শিখছে; আর অনেক দল কাউকে বাদ দিয়েই নিজেদের এক রাখে। কখনো এটা সাময়িক পরিবর্তন; কখনো ইচ্ছে করে বাদ দেওয়া — যা বুলিংয়েরই একটা রূপ।"},"normal":{"en":"Most children go through times of feeling left out, and friendships often mend or new ones form. Long-lasting loneliness, or exclusion with mocking and cruelty, needs more help.","bn":"বেশির ভাগ শিশুই কখনো না কখনো বাদ পড়ার অনুভূতির মধ্য দিয়ে যায়; বন্ধুত্ব প্রায়ই জোড়া লাগে, বা নতুন বন্ধু হয়। দীর্ঘদিনের একাকিত্ব, বা ঠাট্টা ও নিষ্ঠুরতাসহ বাদ দেওয়া হলে বেশি সাহায্য দরকার।"},"do_now":{"en":["Listen and name the feeling: “That really hurts.”","Avoid rushing to fix it or blaming the other children","Ask gently what happened and how long it has been going on"],"bn":["শুনুন, অনুভূতির নাম দিন: “এটা সত্যিই খুব কষ্টের।”","তাড়াহুড়া করে সমাধান করতে বা অন্য শিশুদের দোষ দিতে যাবেন না","নরমভাবে জিজ্ঞেস করুন কী হয়েছে, আর কতদিন ধরে চলছে"]},"steps":{"en":["Help your child think of one or two other classmates who might be friendly","Invite a classmate home or to the park","Encourage a club, sport, art class or other group outside school","Practise how to join in and start a conversation","Talk with the teacher, who may help with seating or group work","Keep home a warm place: special time with you every day"],"bn":["সহপাঠীদের মধ্যে আর কে কে বন্ধুসুলভ হতে পারে, এক-দুজনের কথা ভাবতে সাহায্য করুন","কোনো সহপাঠীকে বাসায় বা পার্কে আসতে বলুন","স্কুলের বাইরে কোনো ক্লাব, খেলা, আঁকার ক্লাস বা অন্য দলে যোগ দিতে উৎসাহ দিন","কীভাবে খেলায় যোগ দিতে আর কথা শুরু করতে হয়, অনুশীলন করুন","শিক্ষকের সঙ্গে কথা বলুন — তিনি বসার জায়গা বা দলগত কাজে সাহায্য করতে পারেন","ঘরটাকে উষ্ণ রাখুন: প্রতিদিন আপনার সঙ্গে বিশেষ একটু সময়"]},"avoid":{"en":["Saying “Just find new friends” or “It doesn''t matter”","Calling the other children''s parents in anger","Pushing your child to be popular","Letting screens replace real-life friendships"],"bn":["“নতুন বন্ধু বানাও” বা “এতে কিছু হয় না” বলা","রেগে অন্য শিশুদের মা-বাবাকে ফোন করা","সবার প্রিয় হতে সন্তানকে চাপ দেওয়া","বাস্তবের বন্ধুত্বের জায়গা স্ক্রিনকে নিতে দেওয়া"]},"example":{"en":"Lamia, 11, came home in tears because her group had made a new chat without her. Her mother listened, then asked who else in class she liked. Lamia mentioned a quiet girl who loved drawing. They invited her over on Friday, and the two joined the school art club together.","bn":"১১ বছরের লামিয়া কাঁদতে কাঁদতে বাড়ি ফিরল — তার দল তাকে বাদ দিয়ে নতুন চ্যাট খুলেছে। মা শুনলেন, তারপর জিজ্ঞেস করলেন ক্লাসে আর কাকে তার ভালো লাগে। লামিয়া এক চুপচাপ মেয়ের কথা বলল, যে আঁকতে ভালোবাসে। শুক্রবার তাকে বাসায় ডাকা হলো, আর দুজনে মিলে স্কুলের আঁকার ক্লাবে যোগ দিল।"},"seek_help":{"en":["Exclusion comes with mocking, threats or online cruelty — treat it as bullying and tell the school","Your child is lonely and sad for weeks, or refuses school","Your child finds it very hard to make or keep any friends over a long time"],"bn":["বাদ দেওয়ার সঙ্গে ঠাট্টা, হুমকি বা অনলাইনে নিষ্ঠুরতা — একে বুলিং হিসেবে দেখুন, স্কুলকে জানান","কয়েক সপ্তাহ ধরে সন্তান একা আর মন খারাপ, বা স্কুলে যেতে চায় না","দীর্ঘদিন ধরে কোনো বন্ধু বানাতে বা ধরে রাখতে খুব কষ্ট হচ্ছে"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['left out', 'friends', 'exclusion', 'loneliness', 'friendship group']::text[], false, 'in_review'::lp_review_status, 7039),
  ('mc-sc-scared-sleep-alone', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🌙', '{"en":"My child is scared to sleep alone and worries a lot","bn":"সন্তান একা ঘুমাতে ভয় পায়, অনেক দুশ্চিন্তা করে"}'::jsonb, '{"en":"Fears and worries are common at this age. Take them seriously, keep a calm routine, and help your child face fears in small steps.","bn":"এ বয়সে ভয় আর দুশ্চিন্তা খুবই সাধারণ। গুরুত্ব দিয়ে শুনুন, শান্ত রুটিন রাখুন, আর ছোট ছোট ধাপে ভয়ের মোকাবিলা করতে সাহায্য করুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"School-age children may fear the dark, thieves, ghosts, a parent dying or something from the news. Worry often comes out at bedtime, when the house is quiet. In many Bangladeshi homes children share a bed or room, so “sleeping alone” may simply mean falling asleep without a parent beside them.","bn":"স্কুলপড়ুয়া শিশু অন্ধকার, চোর, ভূত, মা-বাবার মৃত্যু বা খবরে দেখা কিছু নিয়ে ভয় পেতে পারে। ঘর যখন চুপচাপ, সেই ঘুমের সময়েই দুশ্চিন্তা বেশি মাথাচাড়া দেয়। বাংলাদেশের অনেক ঘরে শিশুরা বিছানা বা ঘর ভাগ করে ঘুমায়, তাই “একা ঘুমানো” মানে হয়তো শুধু মা-বাবা পাশে না থাকলেও ঘুমিয়ে পড়া।"},"why":{"en":"As children understand more about the world, they also understand more about danger. Scary videos, ghost stories from cousins, family stress or a recent change such as a move or a death can increase fears.","bn":"শিশু পৃথিবী সম্পর্কে যত বোঝে, বিপদ সম্পর্কেও তত বোঝে। ভয়ের ভিডিও, কাজিনদের ভূতের গল্প, পরিবারের চাপ, বা বাসা বদল কিংবা কারও মৃত্যুর মতো সাম্প্রতিক পরিবর্তন ভয় বাড়াতে পারে।"},"normal":{"en":"Night-time fears and some worrying are a normal part of development and usually fade with support. It is more serious when worry is constant, affects school and play, or causes frequent physical symptoms.","bn":"রাতের ভয় আর কিছুটা দুশ্চিন্তা বেড়ে ওঠার স্বাভাবিক অংশ, সাহায্য পেলে সাধারণত কমে যায়। বেশি গুরুতর হলো যখন দুশ্চিন্তা সারাক্ষণ থাকে, স্কুল আর খেলায় প্রভাব ফেলে, বা ঘন ঘন শরীরে উপসর্গ দেখা দেয়।"},"do_now":{"en":["Listen without laughing: “Tell me what scares you.”","Reassure calmly about what you do to keep the house safe","Stay a few minutes, then say when you will check back: “I''ll come and see you in five minutes.”","Keep a small night light if it helps"],"bn":["না হেসে শুনুন: “বলো তো, কীসে ভয় লাগছে?”","ঘর নিরাপদ রাখতে আপনি কী করেন, শান্তভাবে বুঝিয়ে বলুন","কয়েক মিনিট পাশে থাকুন, তারপর বলুন কখন আবার দেখতে আসবেন: “পাঁচ মিনিট পর এসে দেখে যাব।”","দরকার হলে ছোট একটা রাতবাতি জ্বালিয়ে রাখুন"]},"steps":{"en":["Keep a calm, predictable bedtime routine","Have a short “worry time” earlier in the evening to talk about worries, not at lights out","Teach slow breathing or imagining a favourite calm place","Move step by step: sit by the bed, then by the door, then check back from outside","Praise brave steps, however small","Avoid scary videos, games and stories, especially in the evening"],"bn":["শান্ত, নিয়মিত ঘুমের রুটিন রাখুন","বাতি নেভানোর সময় নয়, সন্ধ্যায় আগেভাগে ছোট একটা “দুশ্চিন্তার সময়” রাখুন — তখন দুশ্চিন্তা নিয়ে কথা হবে","ধীরে শ্বাস নেওয়া, বা প্রিয় কোনো শান্ত জায়গার কথা কল্পনা করা শেখান","ধাপে ধাপে এগোন: প্রথমে বিছানার পাশে বসা, তারপর দরজার কাছে, তারপর বাইরে থেকে খোঁজ নেওয়া","সাহসের ধাপ যত ছোটই হোক, প্রশংসা করুন","ভয়ের ভিডিও, গেম আর গল্প এড়িয়ে চলুন, বিশেষ করে সন্ধ্যায়"]},"avoid":{"en":["Mocking: “Big boys aren''t scared”","Scaring children into obedience with ghosts, police or “the jinn will take you”","Long debates about whether the fear is real","Letting worries go on for months without help"],"bn":["ঠাট্টা: “বড় ছেলেরা ভয় পায় না”","কথা শোনাতে ভূত, পুলিশ বা “জিনে ধরবে” বলে ভয় দেখানো","ভয়টা সত্যি কি না, তা নিয়ে লম্বা তর্ক","কয়েক মাস ধরে দুশ্চিন্তা চলতে দেওয়া, সাহায্য না নেওয়া"]},"example":{"en":"After a robbery in their building, Nabila, 9, could not sleep unless her mother lay beside her. Her parents showed her the new lock, kept a night light on, and every few nights her mother sat a little further from the bed. Within a month, Nabila was falling asleep on her own.","bn":"তাদের ভবনে চুরি হওয়ার পর ৯ বছরের নাবিলা মা পাশে না শুলে ঘুমাতে পারত না। মা-বাবা তাকে নতুন তালাটা দেখালেন, রাতবাতি জ্বালিয়ে রাখলেন, আর কয়েক রাত পরপর মা বিছানা থেকে একটু দূরে গিয়ে বসতেন। এক মাসের মধ্যে নাবিলা নিজেই ঘুমিয়ে পড়তে লাগল।"},"seek_help":{"en":["Worry stops your child from going to school, playing or sleeping for several weeks","Frequent panic, crying, or repeated checking and rituals","Fears began after a frightening event, abuse or a loss"],"bn":["কয়েক সপ্তাহ ধরে দুশ্চিন্তার কারণে স্কুল, খেলা বা ঘুম বন্ধ","ঘন ঘন আতঙ্ক, কান্না, বা বারবার পরীক্ষা করা ও একই কাজ বারবার করা","ভয়ের শুরু কোনো ভয়ংকর ঘটনা, নির্যাতন বা প্রিয়জন হারানোর পর"]},"warning_signs":{"en":["Loud snoring or pauses in breathing during sleep","Frequent headaches or stomach-aches with the worry","Talk of self-harm or not wanting to live — get help the same day"],"bn":["ঘুমের মধ্যে জোরে নাক ডাকা বা শ্বাস থেমে থেমে যাওয়া","দুশ্চিন্তার সঙ্গে ঘন ঘন মাথাব্যথা বা পেটব্যথা","নিজের ক্ষতি বা বাঁচতে না চাওয়ার কথা — সেদিনই সাহায্য নিন"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['fear', 'sleeping alone', 'worry', 'anxiety', 'nightmares', 'dark']::text[], false, 'in_review'::lp_review_status, 7040),
  ('mc-sc-upsetting-online', 'scenario', 'scientific', 'shared', 'important', 'consensus', '⚠️', '{"en":"My child saw something upsetting online","bn":"সন্তান অনলাইনে মন খারাপ করার মতো কিছু দেখেছে"}'::jsonb, '{"en":"Stay calm, thank your child for telling you, and help them make sense of what they saw. Do not punish them for telling.","bn":"শান্ত থাকুন, বলার জন্য সন্তানকে ধন্যবাদ দিন, আর যা দেখেছে তা বুঝতে সাহায্য করুন। বলার জন্য শাস্তি দেবেন না।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Children can come across violent videos, accidents, cruelty, frightening challenges or sexual images, often by accident through autoplay, ads, links in games or friends'' phones. It can leave them scared, confused or ashamed.","bn":"শিশুরা সহিংস ভিডিও, দুর্ঘটনা, নিষ্ঠুরতা, ভয়ের চ্যালেঞ্জ বা যৌন ছবির সামনে পড়তে পারে — প্রায়ই অনিচ্ছায়, অটোপ্লে, বিজ্ঞাপন, গেমের লিংক বা বন্ধুর ফোনের মাধ্যমে। এতে সে ভয়, বিভ্রান্তি বা লজ্জায় পড়ে যেতে পারে।"},"why":{"en":"Platforms recommend more of whatever gets attention, and shocking content spreads fast. Children do not yet have the experience to put what they see into context.","bn":"যা বেশি নজর কাড়ে, প্ল্যাটফর্ম সেটাই বেশি দেখায়, আর চমকে দেওয়া কনটেন্ট দ্রুত ছড়ায়। যা দেখছে তা সঠিক প্রেক্ষাপটে বোঝার অভিজ্ঞতা শিশুর এখনো হয়নি।"},"normal":{"en":"Feeling upset, having a bad dream or asking many questions for a few days afterwards is a normal reaction. Most children settle with support.","bn":"এরপর কয়েক দিন মন খারাপ থাকা, খারাপ স্বপ্ন দেখা বা অনেক প্রশ্ন করা স্বাভাবিক প্রতিক্রিয়া। সাহায্য পেলে বেশির ভাগ শিশু ঠিক হয়ে যায়।"},"do_now":{"en":["Stay calm; your reaction teaches them whether it is safe to tell you","Say: “Thank you for telling me. You are not in trouble.”","Ask what they saw and how it made them feel, without pushing for every detail","Close or block the content; take a screenshot first if it involves a threat or abuse"],"bn":["শান্ত থাকুন; আপনার প্রতিক্রিয়াই শেখাবে আপনাকে বলা নিরাপদ কি না","বলুন: “আমাকে বলার জন্য ধন্যবাদ। তুমি কোনো বিপদে নেই।”","সে কী দেখেছে আর কেমন লেগেছে, জিজ্ঞেস করুন — সব খুঁটিনাটি জানতে চাপ দেবেন না","কনটেন্টটা বন্ধ বা ব্লক করুন; হুমকি বা নির্যাতন জড়িত থাকলে আগে স্ক্রিনশট রাখুন"]},"steps":{"en":["Explain in simple words what happened and that it is not their fault","For sexual content, explain calmly that this is not how real relationships are, and remind them of body-safety rules","For violence or disasters, reassure them about their own safety and the people who help","Report the content on the platform","Check settings: turn off autoplay, use safe search and parental controls","Check in again over the next few days"],"bn":["সহজ ভাষায় বুঝিয়ে বলুন কী হয়েছে, আর এতে তার কোনো দোষ নেই","যৌন কনটেন্ট হলে শান্তভাবে বলুন, বাস্তবের সম্পর্ক এমন নয়; শরীরের নিরাপত্তার নিয়মগুলো মনে করিয়ে দিন","সহিংসতা বা দুর্যোগ হলে তার নিজের নিরাপত্তা আর যাঁরা সাহায্য করেন তাঁদের কথা বলে আশ্বস্ত করুন","প্ল্যাটফর্মে কনটেন্টটা রিপোর্ট করুন","সেটিং দেখুন: অটোপ্লে বন্ধ করুন, সেফ সার্চ আর প্যারেন্টাল কন্ট্রোল চালু করুন","পরের কয়েক দিন আবার খোঁজ নিন"]},"avoid":{"en":["Taking the phone away as a punishment for telling you","Showing shock or disgust at your child","Making them watch it again to “understand”","Sharing or forwarding the content, even to warn others"],"bn":["আপনাকে বলার শাস্তি হিসেবে ফোন কেড়ে নেওয়া","সন্তানের প্রতি চমকে ওঠা বা ঘৃণা দেখানো","“বোঝানোর” জন্য আবার দেখতে বাধ্য করা","অন্যদের সতর্ক করতে হলেও কনটেন্টটা শেয়ার বা ফরোয়ার্ড করা"]},"example":{"en":"Arif, 10, came to his father pale after a video of a road accident autoplayed. His father turned off autoplay, held him, and said, “That was frightening. You did the right thing telling me.” They talked about how drivers and doctors help, and Arif slept with the light on that night.","bn":"সড়ক দুর্ঘটনার একটা ভিডিও অটোপ্লে হওয়ার পর ১০ বছরের আরিফ ফ্যাকাশে মুখে বাবার কাছে এল। বাবা অটোপ্লে বন্ধ করলেন, তাকে জড়িয়ে ধরে বললেন, “ভয়ের জিনিস দেখেছ। আমাকে বলে ঠিক কাজ করেছ।” তাঁরা চালক আর ডাক্তাররা কীভাবে সাহায্য করেন, তা নিয়ে কথা বললেন। সে রাতে আরিফ বাতি জ্বালিয়ে ঘুমাল।"},"seek_help":{"en":["Someone sent the content on purpose, asked for photos or made threats — report it and call 999","Content showing a child being abused — report it to the police; do not share it","Nightmares, fear or changed behaviour last more than a few weeks"],"bn":["কেউ ইচ্ছে করে পাঠিয়েছে, ছবি চেয়েছে বা হুমকি দিয়েছে — রিপোর্ট করুন ও ৯৯৯-এ ফোন করুন","কোনো শিশুর ওপর নির্যাতনের কনটেন্ট — পুলিশকে জানান; শেয়ার করবেন না","দুঃস্বপ্ন, ভয় বা আচরণের পরিবর্তন কয়েক সপ্তাহের বেশি চলছে"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['upsetting content', 'online', 'violence', 'pornography', 'scary video', 'report']::text[], false, 'in_review'::lp_review_status, 7041),
  ('mc-sc-stomach-ache-school', 'scenario', 'scientific', 'shared', 'important', 'consensus', '🤕', '{"en":"My child gets stomach-aches before school","bn":"স্কুলে যাওয়ার আগে সন্তানের পেটব্যথা হয়"}'::jsonb, '{"en":"Worry can cause real pain. Rule out illness with a doctor, then find out what is worrying your child about school.","bn":"দুশ্চিন্তা থেকেও সত্যিকারের ব্যথা হয়। আগে ডাক্তার দেখিয়ে অসুখ বাদ দিন, তারপর খুঁজে দেখুন স্কুল নিয়ে সন্তানের কী দুশ্চিন্তা।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your child complains of tummy pain on school mornings, but is often fine on holidays or once allowed to stay home. The pain is real — not “acting” — but the cause may be worry rather than illness.","bn":"স্কুলের দিনের সকালে সন্তান পেটব্যথার কথা বলে, অথচ ছুটির দিনে বা বাসায় থাকতে দিলে প্রায়ই ঠিক থাকে। ব্যথাটা সত্যি — “নাটক” নয় — তবে কারণ অসুখ না হয়ে দুশ্চিন্তাও হতে পারে।"},"why":{"en":"The gut and brain are closely linked; stress can cause cramps, nausea or loose stools. Common worries include tests, a strict teacher, bullying, friendship trouble, being away from a parent, or problems at home. Constipation, skipped breakfast and hunger can also cause morning pain.","bn":"পেট আর মস্তিষ্ক ঘনিষ্ঠভাবে যুক্ত; চাপ থেকে পেট মোচড়ানো, বমিভাব বা পাতলা পায়খানা হতে পারে। সাধারণ দুশ্চিন্তার মধ্যে আছে পরীক্ষা, কড়া শিক্ষক, বুলিং, বন্ধুত্বের সমস্যা, মা-বাবা থেকে দূরে থাকা, বা ঘরের সমস্যা। কোষ্ঠকাঠিন্য, নাশতা বাদ দেওয়া আর ক্ষুধা থেকেও সকালে ব্যথা হতে পারে।"},"normal":{"en":"Occasional tummy aches before a big test are common. Pain most school days for weeks, or missing school because of it, needs a doctor''s check and a closer look at worries.","bn":"বড় পরীক্ষার আগে মাঝে মাঝে পেটব্যথা সাধারণ। কয়েক সপ্তাহ ধরে প্রায় প্রতি স্কুলের দিনে ব্যথা, বা এর জন্য স্কুল কামাই হলে ডাক্তার দেখানো আর দুশ্চিন্তার দিকটা ভালো করে দেখা দরকার।"},"do_now":{"en":["Believe the pain and comfort your child","Check for danger signs; if there are none, offer the toilet, water, a light breakfast and some rest","If well enough, go to school — even late — to avoid the avoidance becoming a habit","Later, ask calmly: “Is anything at school worrying you?”"],"bn":["ব্যথাটা বিশ্বাস করুন, সন্তানকে সান্ত্বনা দিন","বিপদচিহ্ন আছে কি না দেখুন; না থাকলে টয়লেটে যেতে বলুন, পানি, হালকা নাশতা আর একটু বিশ্রাম দিন","মোটামুটি ভালো থাকলে দেরিতে হলেও স্কুলে পাঠান, যাতে এড়িয়ে যাওয়াটা অভ্যাস না হয়","পরে শান্তভাবে জিজ্ঞেস করুন: “স্কুলে কি কিছু নিয়ে দুশ্চিন্তা হচ্ছে?”"]},"steps":{"en":["See a doctor to rule out illness, constipation or infection","Keep a simple diary: when the pain comes, what happened that day","Talk with the teacher about tests, friendships and bullying","Make mornings calmer: wake earlier, breakfast, no rushing","Teach slow breathing for when the worry starts","Work with the school on a plan if your child has been missing days"],"bn":["অসুখ, কোষ্ঠকাঠিন্য বা সংক্রমণ বাদ দিতে ডাক্তার দেখান","সহজ একটা ডায়েরি রাখুন: ব্যথা কখন আসে, সেদিন কী হয়েছিল","পরীক্ষা, বন্ধুত্ব আর বুলিং নিয়ে শিক্ষকের সঙ্গে কথা বলুন","সকাল শান্ত করুন: একটু আগে ওঠা, নাশতা, তাড়াহুড়া নয়","দুশ্চিন্তা শুরু হলে ধীরে শ্বাস নেওয়া শেখান","সন্তান কয়েক দিন কামাই করে থাকলে স্কুলের সঙ্গে মিলে পরিকল্পনা করুন"]},"avoid":{"en":["Saying “You''re faking it”","Letting your child stay home with screens every time — it makes school harder to return to","Giving medicines without a doctor''s advice","Ignoring pain that has danger signs"],"bn":["“তুমি ভান করছ” বলা","প্রতিবার বাসায় রেখে স্ক্রিন দেওয়া — এতে স্কুলে ফেরা আরও কঠিন হয়","ডাক্তারের পরামর্শ ছাড়া ওষুধ দেওয়া","বিপদচিহ্নসহ ব্যথা উপেক্ষা করা"]},"example":{"en":"Every Sunday morning Tahmid, 8, had tummy pain. The doctor found nothing wrong. His father noticed Sunday was spelling test day. With the teacher, they practised spellings a little each evening, and his father walked him to school on Sundays. The pain faded over a few weeks.","bn":"প্রতি রবিবার সকালে ৮ বছরের তাহমিদের পেটব্যথা হতো। ডাক্তার কোনো সমস্যা পেলেন না। বাবা খেয়াল করলেন, রবিবার বানান পরীক্ষার দিন। শিক্ষকের সঙ্গে মিলে প্রতি সন্ধ্যায় একটু একটু বানান অনুশীলন শুরু হলো, আর রবিবার বাবা তাকে হেঁটে স্কুলে পৌঁছে দিতেন। কয়েক সপ্তাহে ব্যথা মিলিয়ে গেল।"},"seek_help":{"en":["Pain most school days for more than two weeks","Your child is missing school because of the pain","Signs of bullying, abuse or strong anxiety"],"bn":["দুই সপ্তাহের বেশি ধরে প্রায় প্রতি স্কুলের দিনে ব্যথা","ব্যথার কারণে সন্তান স্কুল কামাই করছে","বুলিং, নির্যাতন বা তীব্র দুশ্চিন্তার লক্ষণ"]},"warning_signs":{"en":["Severe pain, or pain that wakes your child at night","Pain that moves to the lower right side of the tummy, or a hard, swollen tummy","Repeated vomiting, or green vomit","Fever, blood in the stool, or weight loss","Pain with burning when passing urine"],"bn":["তীব্র ব্যথা, বা ব্যথায় রাতে ঘুম ভেঙে যায়","ব্যথা পেটের ডান দিকের নিচে সরে যায়, বা পেট শক্ত ও ফোলা","বারবার বমি, বা সবুজ বমি","জ্বর, পায়খানায় রক্ত, বা ওজন কমে যাওয়া","প্রস্রাবের সময় জ্বালাপোড়াসহ ব্যথা"]}}'::jsonb, 3, 2557, 4748, '{}'::text[], 'any', ARRAY['stomach ache', 'school refusal', 'anxiety', 'tummy pain', 'worry']::text[], false, 'in_review'::lp_review_status, 7042)
