INSERT INTO lp_task_templates (key, title, description, why, benefit, steps, safety_note, task_type, frequency, assignee, subject, min_day, max_day, estimated_minutes, xp, emoji, category_key, resource_slug, source_key, sex, review_status, sort_order) VALUES
  ('mc_homework_checkin', '{"en":"Homework check-in","bn":"হোমওয়ার্কের খোঁজ নিন"}'::jsonb, '{"en":"Spend a few minutes looking at today''s homework with your child — not doing it for them.","bn":"আজকের হোমওয়ার্ক সন্তানের সঙ্গে কয়েক মিনিট দেখুন — করে দেবেন না।"}'::jsonb, '{"en":"A short, calm daily check helps children plan their work and shows that you care about their learning, without turning homework into a fight.","bn":"প্রতিদিন অল্প সময়ের শান্ত খোঁজ সন্তানকে কাজের পরিকল্পনা করতে সাহায্য করে, আর বোঝায় তার পড়াশোনা নিয়ে আপনি ভাবেন — ঝগড়া ছাড়াই।"}'::jsonb, '{"en":"Better study habits and earlier warning if something is hard.","bn":"পড়ার ভালো অভ্যাস, আর কিছু কঠিন লাগলে আগেভাগে টের পাওয়া।"}'::jsonb, '[{"en":"Ask what homework there is today and when it is due","bn":"আজ কী হোমওয়ার্ক আছে আর কবে জমা, জিজ্ঞেস করুন"},{"en":"Help write a short list and pick the first task","bn":"ছোট একটা তালিকা করতে সাহায্য করুন, প্রথম কাজটা বেছে নিন"},{"en":"Check the school diary and sign if needed","bn":"স্কুলের ডায়েরি দেখুন, দরকার হলে সই করুন"},{"en":"Praise one bit of effort","bn":"চেষ্টার একটা জায়গার প্রশংসা করুন"}]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'shared', 'child', 2557, 4748, 10, 5, '📝', 'academics', 'mc-homework-routine', 'unicef_parenting', 'any', 'in_review'::lp_review_status, 7101),
  ('mc_family_meeting', '{"en":"Hold a family meeting","bn":"পারিবারিক বৈঠক করুন"}'::jsonb, '{"en":"Twenty minutes with everyone together to share appreciation, plan the week and solve one problem.","bn":"সবাই মিলে বিশ মিনিট — প্রশংসা, সপ্তাহের পরিকল্পনা আর একটা সমস্যার সমাধান।"}'::jsonb, '{"en":"Children who have a say in family decisions learn to listen, negotiate and take responsibility, and small problems are solved before they grow.","bn":"পরিবারের সিদ্ধান্তে যে শিশুর মতামত থাকে, সে শুনতে, আলোচনা করতে আর দায়িত্ব নিতে শেখে; ছোট সমস্যা বড় হওয়ার আগেই মিটে যায়।"}'::jsonb, '{"en":"Fewer fights and a family that plans together.","bn":"ঝগড়া কম, আর একসঙ্গে পরিকল্পনা করা একটা পরিবার।"}'::jsonb, '[{"en":"Phones and TV off","bn":"ফোন আর টিভি বন্ধ"},{"en":"Everyone says one good thing about someone''s week","bn":"প্রত্যেকে কারও সপ্তাহের একটা ভালো দিক বলবে"},{"en":"Plan the coming week","bn":"আসছে সপ্তাহের পরিকল্পনা"},{"en":"Solve one problem together and plan one fun thing","bn":"একসঙ্গে একটা সমস্যার সমাধান, আর একটা মজার কিছুর পরিকল্পনা"}]'::jsonb, '{}'::jsonb, 'family', 'weekly', 'shared', 'family', 2557, 4748, 20, 15, '🗓️', 'positive_discipline', 'mc-activity-family-meeting', 'cdc_positive_parenting', 'any', 'in_review'::lp_review_status, 7102),
  ('mc_save_pocket_money', '{"en":"Save part of the pocket money","bn":"হাতখরচের একটা অংশ জমান"}'::jsonb, '{"en":"When pocket money is given, your child puts some into the save jar and notes it down.","bn":"হাতখরচ পেলে সন্তান একটা অংশ জমার বয়ামে রাখবে, আর খাতায় লিখে রাখবে।"}'::jsonb, '{"en":"Saving a little each week teaches children to plan, wait for something they want and handle money responsibly.","bn":"প্রতি সপ্তাহে একটু একটু জমালে শিশু পরিকল্পনা করতে, পছন্দের জিনিসের জন্য অপেক্ষা করতে আর দায়িত্ব নিয়ে টাকা সামলাতে শেখে।"}'::jsonb, '{"en":"A savings habit and the pride of reaching a goal.","bn":"জমানোর অভ্যাস, আর লক্ষ্যে পৌঁছানোর গর্ব।"}'::jsonb, '[]'::jsonb, '{"en":"Never share mobile banking PINs or OTPs with children.","bn":"শিশুর সঙ্গে কখনো মোবাইল ব্যাংকিংয়ের পিন বা ওটিপি শেয়ার করবেন না।"}'::jsonb, 'recommended', 'weekly', 'any', 'child', 2557, 4748, 5, 10, '🪙', 'life_skills', 'mc-pocket-money-saving', 'unicef_parenting', 'any', 'in_review'::lp_review_status, 7103),
  ('mc_phones_out_of_bedroom', '{"en":"Phones out of the bedroom tonight","bn":"আজ রাতে ফোন শোবার ঘরের বাইরে"}'::jsonb, '{"en":"All phones and tablets go to charge in a shared room at bedtime — parents'' phones too, if you can.","bn":"ঘুমের সময় সব ফোন আর ট্যাব সবার ব্যবহারের ঘরে চার্জে যাবে — পারলে মা-বাবার ফোনও।"}'::jsonb, '{"en":"Screens in the bedroom delay sleep and cut into the 9–12 hours school-age children need. Keeping them out also reduces late-night contact with strangers.","bn":"শোবার ঘরে স্ক্রিন থাকলে ঘুম দেরিতে আসে, আর স্কুলপড়ুয়া শিশুর দরকারি ৯–১২ ঘণ্টা ঘুম কমে যায়। বাইরে রাখলে গভীর রাতে অচেনা মানুষের সঙ্গে যোগাযোগের ঝুঁকিও কমে।"}'::jsonb, '{"en":"Better sleep, mood and concentration.","bn":"ভালো ঘুম, ভালো মেজাজ আর মনোযোগ।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'recommended', 'daily', 'shared', 'family', 2557, 4748, 2, 5, '🔌', 'sleep', 'mc-sleep', 'aap_media', 'any', 'in_review'::lp_review_status, 7104),
  ('mc_online_safety_talk', '{"en":"Have an online-safety talk","bn":"অনলাইন নিরাপত্তা নিয়ে কথা বলুন"}'::jsonb, '{"en":"A short, relaxed chat about what your child does online and what to do if something feels wrong.","bn":"সন্তান অনলাইনে কী করে, আর কিছু খারাপ লাগলে কী করবে — তা নিয়ে ছোট, হালকা একটা আলাপ।"}'::jsonb, '{"en":"Children are safest online when they know the rules and feel sure they can tell a parent without being punished.","bn":"শিশু অনলাইনে সবচেয়ে নিরাপদ থাকে, যখন সে নিয়মগুলো জানে আর নিশ্চিত থাকে যে মা-বাবাকে বললে শাস্তি হবে না।"}'::jsonb, '{"en":"Problems come to you early, before they grow.","bn":"সমস্যা বড় হওয়ার আগেই আপনার কাছে পৌঁছায়।"}'::jsonb, '[{"en":"Ask which apps and games they used this month","bn":"এ মাসে কোন কোন অ্যাপ আর গেম ব্যবহার করেছে, জিজ্ঞেস করুন"},{"en":"Pick one rule to revisit: strangers, photos, scams or passwords","bn":"একটা নিয়ম আবার আলোচনা করুন: অচেনা মানুষ, ছবি, প্রতারণা বা পাসওয়ার্ড"},{"en":"Ask: “Has anything online made you feel uncomfortable?”","bn":"জিজ্ঞেস করুন: “অনলাইনে কিছু কি তোমার খারাপ লেগেছে?”"},{"en":"Repeat your promise: telling will not get them punished","bn":"আবার কথা দিন: বললে শাস্তি হবে না"}]'::jsonb, '{}'::jsonb, 'learn', 'monthly', 'shared', 'child', 2557, 4748, 15, 15, '🔐', 'digital_life', 'mc-online-safety', 'unicef_parenting', 'any', 'in_review'::lp_review_status, 7105),
  ('mc_sport_session', '{"en":"A sport or active session","bn":"খেলাধুলা বা সক্রিয় একটা সেশন"}'::jsonb, '{"en":"A longer session of sport or vigorous play this week — football, cricket, badminton, swimming lessons, skipping or dancing.","bn":"এ সপ্তাহে একটু লম্বা সময় খেলাধুলা বা জোরালো খেলা — ফুটবল, ক্রিকেট, ব্যাডমিন্টন, সাঁতার শেখা, দড়িলাফ বা নাচ।"}'::jsonb, '{"en":"WHO advises children aged 5–17 to average at least 60 minutes of activity a day, with vigorous and muscle- and bone-strengthening activity on at least 3 days a week.","bn":"বিশ্ব স্বাস্থ্য সংস্থা ৫–১৭ বছরের শিশু-কিশোরদের দিনে গড়ে অন্তত ৬০ মিনিট সক্রিয় থাকার, আর সপ্তাহে অন্তত ৩ দিন জোরালো এবং পেশি ও হাড় মজবুত করার কাজ করার পরামর্শ দেয়।"}'::jsonb, '{"en":"Stronger bones and muscles, better sleep and mood.","bn":"মজবুত হাড় ও পেশি, ভালো ঘুম আর মেজাজ।"}'::jsonb, '[]'::jsonb, '{"en":"Swimming only with a trained adult watching; never alone or in fast rivers.","bn":"সাঁতার শুধু প্রশিক্ষিত কোনো বড়র নজরদারিতে; কখনো একা বা স্রোতের নদীতে নয়।"}'::jsonb, 'recommended', 'weekly', 'any', 'child', 2557, 4748, 45, 10, '⚽', 'physical_activity', 'mc-active-60-minutes', 'who_activity_5_17', 'any', 'in_review'::lp_review_status, 7106),
  ('mc_ask_about_friends', '{"en":"Ask about friends","bn":"বন্ধুদের কথা জিজ্ঞেস করুন"}'::jsonb, '{"en":"In a relaxed moment — a walk, a meal or the ride home — ask about your child''s friends.","bn":"হালকা কোনো মুহূর্তে — হাঁটতে হাঁটতে, খেতে খেতে বা বাড়ি ফেরার পথে — সন্তানের বন্ধুদের কথা জিজ্ঞেস করুন।"}'::jsonb, '{"en":"Knowing your child''s friends helps you notice early if they are left out, bullied or under pressure.","bn":"সন্তানের বন্ধুদের চিনলে সে বাদ পড়ছে, বুলিংয়ের শিকার হচ্ছে বা চাপে আছে কি না — আগেভাগে টের পাওয়া যায়।"}'::jsonb, '{"en":"A child who talks to you about their social life.","bn":"এমন একটা সন্তান, যে বন্ধুদের জগৎ নিয়ে আপনার সঙ্গে কথা বলে।"}'::jsonb, '[{"en":"“Who did you sit with or play with this week?”","bn":"“এ সপ্তাহে কার সঙ্গে বসেছ বা খেলেছ?”"},{"en":"“What was the best and the hardest moment with friends?”","bn":"“বন্ধুদের সঙ্গে সবচেয়ে ভালো আর সবচেয়ে কঠিন মুহূর্ত কোনটা?”"},{"en":"Listen more than you talk","bn":"বলার চেয়ে বেশি শুনুন"}]'::jsonb, '{}'::jsonb, 'observe', 'weekly', 'shared', 'child', 2557, 4748, 10, 10, '🤝', 'social_skills', 'mc-friendship-peer-pressure', 'unicef_parenting', 'any', 'in_review'::lp_review_status, 7107),
  ('mc_puberty_talk', '{"en":"Have the puberty talk","bn":"বয়ঃসন্ধি নিয়ে কথা বলুন"}'::jsonb, '{"en":"Between 9 and 11, talk calmly with your child about the body changes ahead — before they begin.","bn":"৯ থেকে ১১ বছরের মধ্যে, পরিবর্তন শুরু হওয়ার আগেই, সামনে শরীরে কী কী বদলাবে তা নিয়ে সন্তানের সঙ্গে শান্তভাবে কথা বলুন।"}'::jsonb, '{"en":"Children who know what to expect cope much better with periods, wet dreams and other changes, and are more likely to come to you with questions.","bn":"যে শিশু আগে থেকে জানে কী আসছে, সে মাসিক, স্বপ্নদোষ আর অন্য পরিবর্তন অনেক ভালোভাবে সামলাতে পারে, আর প্রশ্ন নিয়ে আপনার কাছেই আসে।"}'::jsonb, '{"en":"Less fear and shame, and an open door for the teenage years.","bn":"কম ভয় আর লজ্জা, আর কৈশোরের জন্য খোলা একটা দরজা।"}'::jsonb, '[{"en":"Read the puberty guide first so you feel ready","bn":"প্রস্তুত বোধ করতে আগে বয়ঃসন্ধির গাইডটা পড়ে নিন"},{"en":"Choose a quiet, private moment","bn":"শান্ত, নিরিবিলি একটা মুহূর্ত বেছে নিন"},{"en":"Explain the changes for both girls and boys, using correct words","bn":"সঠিক শব্দ ব্যবহার করে ছেলে-মেয়ে দুজনেরই পরিবর্তন বুঝিয়ে বলুন"},{"en":"End with: “You can ask me anything, any time.”","bn":"শেষে বলুন: “যেকোনো সময় যেকোনো কিছু আমাকে জিজ্ঞেস করতে পারো।”"}]'::jsonb, '{}'::jsonb, 'must_do', 'once', 'shared', 'child', 3287, 4018, 20, 30, '🌿', 'puberty', 'mc-puberty-talk-early', 'who_adolescent_health', 'any', 'in_review'::lp_review_status, 7108),
  ('mc_period_kit', '{"en":"Pack a first-period kit with your daughter","bn":"মেয়ের সঙ্গে মিলে প্রথম মাসিকের ছোট ব্যাগ গুছিয়ে দিন"}'::jsonb, '{"en":"Put two pads, spare pants and a small plastic bag in a pouch for her school bag, and show her how to use a pad.","bn":"স্কুলব্যাগের জন্য একটা থলেতে দুটো প্যাড, একটা বাড়তি প্যান্টি আর ছোট একটা পলিথিন রাখুন, আর প্যাড কীভাবে ব্যবহার করতে হয় দেখিয়ে দিন।"}'::jsonb, '{"en":"A girl who is prepared before her first period feels calm and in control, even if it starts at school.","bn":"প্রথম মাসিকের আগে প্রস্তুত থাকলে মেয়ে শান্ত থাকে, নিজেকে সামলাতে পারে — স্কুলে শুরু হলেও।"}'::jsonb, '{"en":"No panic and no missed school days because of a surprise period.","bn":"হঠাৎ মাসিকে আতঙ্ক নেই, স্কুল কামাইও নেই।"}'::jsonb, '[]'::jsonb, '{}'::jsonb, 'recommended', 'once', 'shared', 'child', 3287, 4748, 15, 15, '🌸', 'puberty', 'mc-first-period-prep', 'who_adolescent_health', 'female', 'in_review'::lp_review_status, 7109)
